package com.travelguide;

import com.google.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.List;
import lombok.Getter;
import lombok.Setter;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import com.travelguide.pathfinder.Pathfinder;

public class DebugOverlayPanel extends OverlayPanel
{
	private final TravelGuidePlugin plugin;
	private final SeparatorLine separator;

	@Inject
	public DebugOverlayPanel(TravelGuidePlugin plugin)
	{
		super(plugin);
		this.plugin = plugin;

		separator = new SeparatorLine();
		separator.setColor(new Color(0, true)); // Invisible color

		setPosition(OverlayPosition.TOP_LEFT);
	}

	private LineComponent makeLine(String left, String right)
	{
		return LineComponent.builder()
			.left(left)
			.right(right)
			.build();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Pathfinder pathfinder = plugin.getPathfinder();
		Pathfinder.PathfinderStats stats;
		if (pathfinder == null || (stats = pathfinder.getStats()) == null)
		{
			return null;
		}

		List<LayoutableRenderableEntity> components = panelComponent.getChildren();

		components.add(
			TitleComponent.builder()
				.text("Shortest Path Debug")
				.color(Color.ORANGE)
				.build());

		components.add(separator);

		String pathLength = Integer.toString(pathfinder.getPath().size());
		components.add(makeLine("Path Length:", pathLength));

		components.add(separator);

		String nodes = Integer.toString(stats.getNodesChecked());
		components.add(makeLine("Nodes:", nodes));

		String transports = Integer.toString(stats.getTransportsChecked());
		components.add(makeLine("Transports:", transports));

		String totalNodes = Integer.toString(stats.getTotalNodesChecked());
		components.add(makeLine("Total:", totalNodes));

		components.add(separator);

		double milliTime = stats.getElapsedTimeNanos() / 1000000.0;
		String time = String.format("%.2fms", milliTime);
		components.add(makeLine("Time:", time));

		return super.render(graphics);
	}

	@Setter
	private static class SeparatorLine implements LayoutableRenderableEntity
	{
		@Getter
		private final Rectangle bounds = new Rectangle();
		private Color color = Color.GRAY;
		private Point preferredLocation = new Point();
		private Dimension preferredSize = new Dimension(ComponentConstants.STANDARD_WIDTH, 4);

		@Override
		public Dimension render(Graphics2D graphics)
		{
			final int separatorX = preferredLocation.x;
			final int separatorY = preferredLocation.y + 4;
			final int width = preferredSize.width;
			final int height = Math.max(preferredSize.height, 2);

			// Draw bar
			if (color != null && color.getAlpha() != 0)
			{
				graphics.setColor(color);
				graphics.fillRect(separatorX, separatorY, width, height);
			}

			final Dimension dimension = new Dimension(width, height + 4);
			bounds.setLocation(preferredLocation);
			bounds.setSize(dimension);

			return dimension;
		}
	}
}

package com.travelguide;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Scanner;
import java.util.Set;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import com.travelguide.transport.parser.FieldParser;
import com.travelguide.transport.parser.QuestParser;
import com.travelguide.transport.parser.SkillRequirementParser;
import com.travelguide.transport.parser.VarRequirement;
import com.travelguide.transport.parser.VarRequirementParser;

/**
 * Utility loader for destination coordinate sets grouped by feature category.
 * <p>
 * Destination data is stored in tab-separated value (TSV) resources under
 * {@code /destinations/**}. Each file's
 * first non-empty line is treated as a header (leading comment markers
 * {@code #} or {@code # } are stripped) and
 * defines column names. Rows beginning with {@code #} or blank lines are
 * ignored. Columns named "Destination" are
 * parsed as space-delimited triples {@code (x y plane)} that are packed into
 * single {@code int} values via
 * {@link WorldPointUtil#packWorldPoint(int, int, int)}.
 */
@Slf4j
public class Destination
{
	private static final FieldParser<int[]> SKILL_PARSER = new SkillRequirementParser();
	private static final FieldParser<Set<Quest>> QUEST_PARSER = new QuestParser();
	private static final FieldParser<Set<VarRequirement>> VARBIT_PARSER = VarRequirementParser.forVarbits();
	private static final FieldParser<Set<VarRequirement>> VARPLAYER_PARSER = VarRequirementParser.forVarPlayers();
	private static final String DELIM_COLUMN = "\t";
	private static final String PREFIX_COMMENT = "#";
	private static final String FILE_EXTENSION = ".";
	private static final String DELIM_PATH = "/";
	private static final String DELIM = " ";

	/**
	 * Parses a TSV resource of destination coordinates and merges them into the provided map.
	 * The key in the destination map is derived from the directory component immediately preceding the file
	 * name (e.g., {@code /destinations/game_features/bank.tsv -> bank}).
	 *
	 * @param destinations accumulator map of category key to a set of packed world point integers.
	 * @param path         classpath resource path to a TSV file beginning with a header line.
	 * @throws RuntimeException wrapping {@link IOException} if the resource cannot be read.
	 */
	private static void addDestinations(Map<String, Set<Integer>> destinations, String path)
	{
		try
		{
			String s = new String(Util.readAllBytes(Objects.requireNonNull(TravelGuidePlugin.class.getResourceAsStream(path))),
				StandardCharsets.UTF_8);
			Scanner scanner = new Scanner(s);

			// Header line is the first line in the file and will start with either '#' or
			// '# '
			String[] headers = parse_header_line(scanner);

			String[] parts = path.replace(FILE_EXTENSION, DELIM_PATH).split(DELIM_PATH);
			String entry = parts[parts.length - 2];

			while (scanner.hasNextLine())
			{
				String line = scanner.nextLine();

				if (line.startsWith(PREFIX_COMMENT) || line.isBlank())
				{
					continue;
				}

				String[] fields = line.split(DELIM_COLUMN);
				Map<String, List<String>> fieldMap = new HashMap<>();
				for (int i = 0; i < headers.length; i++)
				{
					if (i < fields.length)
					{
						List<String> values = fieldMap.getOrDefault(headers[i], new ArrayList<>());
						values.add(fields[i]);
						fieldMap.put(headers[i], values);
					}
				}
				for (String field : fieldMap.keySet())
				{
					if ("Destination".equals(field))
					{
						for (String value : fieldMap.get(field))
						{
							try
							{
								String[] destinationArray = value.split(DELIM);
								if (destinationArray.length == 3)
								{
									Set<Integer> entryDestinations = destinations.getOrDefault(entry, new HashSet<>());
									entryDestinations.add(WorldPointUtil.packWorldPoint(
										Integer.parseInt(destinationArray[0]),
										Integer.parseInt(destinationArray[1]),
										Integer.parseInt(destinationArray[2])));
									destinations.put(entry, entryDestinations);
								}
							}
							catch (NumberFormatException e)
							{
								log.error("Invalid destination coordinate", e);
							}
						}
					}
				}
			}
			scanner.close();
		}
		catch (IOException e)
		{
			throw new RuntimeException(e);
		}
	}

	private static String[] parse_header_line(Scanner scanner)
	{
		String headerLine = scanner.nextLine();
		headerLine = headerLine.startsWith(PREFIX_COMMENT + " ")
			? headerLine.replace(PREFIX_COMMENT + " ", PREFIX_COMMENT)
			: headerLine;
		headerLine = headerLine.startsWith(PREFIX_COMMENT) ? headerLine.replace(PREFIX_COMMENT, "") : headerLine;
		return headerLine.split(DELIM_COLUMN);
	}

	/**
	 * Loads a predefined subset of destination categories from bundled TSV resources.
	 *
	 * @return a map from destination category key to a set of packed world point integers.
	 */
	public static Map<String, Set<Integer>> loadAllFromResources()
	{
		Map<String, Set<Integer>> destinations = new HashMap<>(10);
		addDestinations(destinations, "/destinations/game_features/altar.tsv");
		addDestinations(destinations, "/destinations/game_features/bank.tsv");
		addDestinations(destinations, "/destinations/training/anvil.tsv");
		addDestinations(destinations, "/destinations/shopping/apothecary.tsv");
		return destinations;
	}

	/**
	 * Per-packed-point requirements for bank tiles, parsed from {@code bank.tsv} columns
	 * Skills, Quests, Varbits, and VarPlayers (same TSV format as transports).
	 * Tiles with no requirement rows behave as {@link DestinationRequirements#EMPTY}.
	 */
	public static Map<Integer, DestinationRequirements> loadBankRequirementsFromResources()
	{
		Map<Integer, DestinationRequirements> requirements = new HashMap<>();
		final String path = "/destinations/game_features/bank.tsv";
		final String DELIM_COLUMN = "\t";
		final String PREFIX_COMMENT = "#";
		final String DELIM = " ";

		try
		{
			String s = new String(Util.readAllBytes(Objects.requireNonNull(TravelGuidePlugin.class.getResourceAsStream(path))), StandardCharsets.UTF_8);
			try (Scanner scanner = new Scanner(s))
			{
				String[] headers = parse_header_line(scanner);
				for (int i = 0; i < headers.length; i++)
				{
					headers[i] = headers[i].trim();
				}

				int destCol = indexOf(headers, "Destination");
				int skillsCol = indexOf(headers, "Skills");
				int questsCol = indexOf(headers, "Quests");
				int varbitsCol = indexOf(headers, "Varbits");
				int varPlayersCol = indexOf(headers, "VarPlayers");
				if (destCol < 0)
				{
					return requirements;
				}

				while (scanner.hasNextLine())
				{
					String line = scanner.nextLine();
					if (line.startsWith(PREFIX_COMMENT) || line.isBlank())
					{
						continue;
					}
					String[] fields = line.split(DELIM_COLUMN, -1);
					if (fields.length <= destCol)
					{
						continue;
					}
					String destField = fields[destCol].trim();
					String[] destinationArray = destField.split(DELIM);
					if (destinationArray.length != 3)
					{
						continue;
					}
					int packed;
					try
					{
						packed = WorldPointUtil.packWorldPoint(
							Integer.parseInt(destinationArray[0]),
							Integer.parseInt(destinationArray[1]),
							Integer.parseInt(destinationArray[2]));
					}
					catch (NumberFormatException e)
					{
						log.error("Invalid destination coordinate in bank.tsv", e);
						continue;
					}

					String skillsStr = fieldAt(fields, skillsCol);
					String questsStr = fieldAt(fields, questsCol);
					String varbitsStr = fieldAt(fields, varbitsCol);
					String varPlayersStr = fieldAt(fields, varPlayersCol);

					int[] skillLevels = skillsCol >= 0 ? SKILL_PARSER.parse(blankToNull(skillsStr)) : new int[Skill.values().length + 3];
					Set<Quest> quests = questsCol >= 0 ? QUEST_PARSER.parse(blankToNull(questsStr)) : Set.of();
					Set<VarRequirement> varbits = varbitsCol >= 0 ? VARBIT_PARSER.parse(blankToNull(varbitsStr)) : Set.of();
					Set<VarRequirement> varPlayers = varPlayersCol >= 0 ? VARPLAYER_PARSER.parse(blankToNull(varPlayersStr)) : Set.of();

					DestinationRequirements rowReq = new DestinationRequirements(skillLevels, quests, varbits, varPlayers);
					requirements.merge(packed, rowReq, DestinationRequirements::merge);
				}
			}
		}
		catch (IOException e)
		{
			throw new RuntimeException(e);
		}
		return requirements;
	}

	private static int indexOf(String[] headers, String name)
	{
		for (int i = 0; i < headers.length; i++)
		{
			if (name.equals(headers[i]))
			{
				return i;
			}
		}
		return -1;
	}

	private static String fieldAt(String[] fields, int col)
	{
		if (col < 0 || col >= fields.length)
		{
			return "";
		}
		return fields[col];
	}

	private static String blankToNull(String s)
	{
		return s == null || s.isBlank() ? null : s;
	}
}

package com.travelguide;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import lombok.Getter;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import com.travelguide.transport.parser.VarRequirement;

/**
 * Optional access requirements for a destination tile (e.g. bank booths). Empty requirements mean
 * the destination is always usable when reached.
 */
public final class DestinationRequirements
{
	/**
	 * All-zero skill array; no skill requirements.
	 */
	public static final DestinationRequirements EMPTY = new DestinationRequirements();

	@Getter
	private final int[] skillLevels;
	@Getter
	private final Set<Quest> quests;
	@Getter
	private final Set<VarRequirement> varbits;
	@Getter
	private final Set<VarRequirement> varPlayers;

	private DestinationRequirements()
	{
		this.skillLevels = new int[Skill.values().length + 3];
		this.quests = Collections.emptySet();
		this.varbits = Collections.emptySet();
		this.varPlayers = Collections.emptySet();
	}

	public DestinationRequirements(
		int[] skillLevels,
		Set<Quest> quests,
		Set<VarRequirement> varbits,
		Set<VarRequirement> varPlayers)
	{
		this.skillLevels = skillLevels != null ? skillLevels : new int[Skill.values().length + 3];
		this.quests = quests != null ? quests : Collections.emptySet();
		this.varbits = varbits != null ? varbits : Collections.emptySet();
		this.varPlayers = varPlayers != null ? varPlayers : Collections.emptySet();
	}

	/**
	 * @return a merged requirement when the same tile appears on multiple rows (max skills, union sets).
	 */
	public static DestinationRequirements merge(DestinationRequirements a, DestinationRequirements b)
	{
		if (a == null || a.isEmpty())
		{
			return b != null ? b : EMPTY;
		}
		if (b == null || b.isEmpty())
		{
			return a;
		}
		int[] skills = new int[Skill.values().length + 3];
		for (int i = 0; i < skills.length; i++)
		{
			skills[i] = Math.max(a.skillLevels[i], b.skillLevels[i]);
		}
		Set<Quest> q = new HashSet<>(a.quests);
		q.addAll(b.quests);
		Set<VarRequirement> vb = new HashSet<>(a.varbits);
		vb.addAll(b.varbits);
		Set<VarRequirement> vp = new HashSet<>(a.varPlayers);
		vp.addAll(b.varPlayers);
		return new DestinationRequirements(skills, q, vb, vp);
	}

	public boolean isEmpty()
	{
		if (!quests.isEmpty())
		{
			return false;
		}
		if (!varbits.isEmpty() || !varPlayers.isEmpty())
		{
			return false;
		}
		for (int level : skillLevels)
		{
			if (level > 0)
			{
				return false;
			}
		}
		return true;
	}
}

package com.travelguide;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum JewelleryBoxTier
{
	NONE("None"),
	BASIC("Basic"),
	FANCY("Fancy"),
	ORNATE("Ornate"),
	;

	private final String type;

	public static JewelleryBoxTier fromType(String type)
	{
		for (JewelleryBoxTier tier : values())
		{
			if (tier.type.equals(type))
			{
				return tier;
			}
		}
		return null;
	}

	@Override
	public String toString()
	{
		return type;
	}
}

package com.travelguide;

import com.google.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.Area;
import java.util.Objects;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import com.travelguide.pathfinder.CollisionMap;
import com.travelguide.pathfinder.PathStep;
import com.travelguide.pathfinder.TransportAvailability;
import com.travelguide.transport.Transport;

public class PathMapOverlay extends Overlay
{
	private final Client client;
	private final TravelGuidePlugin plugin;

	@Inject
	private PathMapOverlay(Client client, TravelGuidePlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.MANUAL);
		drawAfterLayer(InterfaceID.Worldmap.MAP_CONTAINER);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.drawMap)
		{
			return null;
		}

		if (client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER) == null)
		{
			return null;
		}

		Rectangle worldMapRectangle = Objects.requireNonNull(client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER)).getBounds();
		Area worldMapClipArea = getWorldMapClipArea(worldMapRectangle);
		graphics.setClip(worldMapClipArea);

		if (plugin.drawCollisionMap)
		{
			graphics.setColor(plugin.colourCollisionMap);
			int mapWorldPoint = plugin.calculateMapPoint(worldMapRectangle.x, worldMapRectangle.y);
			int extentX = WorldPointUtil.unpackWorldX(mapWorldPoint);
			int extentY = WorldPointUtil.unpackWorldY(mapWorldPoint);
			int extentWidth = getWorldMapExtentWidth(worldMapRectangle);
			int extentHeight = getWorldMapExtentHeight(worldMapRectangle);
			final CollisionMap map = plugin.getMap();
			final int z = client.getTopLevelWorldView().getPlane();
			for (int x = extentX; x < (extentX + extentWidth + 1); x++)
			{
				for (int y = extentY - extentHeight; y < (extentY + 1); y++)
				{
					if (map.isBlocked(x, y, z))
					{
						drawOnMap(graphics, WorldPointUtil.packWorldPoint(x, y, z), false, null);
					}
				}
			}
		}

		if (plugin.drawTransports)
		{
			graphics.setColor(Color.WHITE);
			for (int a : plugin.getTransports().keys())
			{
				if (a == Transport.UNDEFINED_ORIGIN)
				{
					continue; // skip teleports
				}

				int mapAX = plugin.mapWorldPointToGraphicsPointX(a);
				int mapAY = plugin.mapWorldPointToGraphicsPointY(a);
				if (!worldMapClipArea.contains(mapAX, mapAY))
				{
					continue;
				}

				for (Transport b : plugin.getTransports().getOrDefault(a, TransportAvailability.EMPTY_TRANSPORTS))
				{
					if (b == null || (b.getType() != null && b.getType().isTeleport()))
					{
						continue; // skip teleports
					}

					int mapBX = plugin.mapWorldPointToGraphicsPointX(b.getDestination());
					int mapBY = plugin.mapWorldPointToGraphicsPointY(b.getDestination());
					if (!worldMapClipArea.contains(mapBX, mapBY))
					{
						continue;
					}

					graphics.drawLine(mapAX, mapAY, mapBX, mapBY);
				}
			}
		}

		if (plugin.getPathfinder() != null)
		{
			Color colour = plugin.getPathColor();
			java.util.List<PathStep> path = plugin.getPathfinder().getPath();
			Point cursorPos = client.getMouseCanvasPosition();
			for (int i = 0; i < path.size(); i++)
			{
				graphics.setColor(colour);
				int point = path.get(i).getPackedPosition();
				int lastPoint = (i > 0) ? path.get(i - 1).getPackedPosition() : point;
				if (WorldPointUtil.distanceBetween(point, lastPoint) > 1)
				{
					drawOnMap(graphics, lastPoint, point, true, cursorPos);
				}
				drawOnMap(graphics, point, true, cursorPos);
			}
			for (int target : plugin.getPathfinder().getTargets())
			{
				if (!path.isEmpty() && target != path.get(path.size() - 1).getPackedPosition())
				{
					graphics.setColor(plugin.colourPathCalculating);
					drawOnMap(graphics, target, true, cursorPos);
				}
			}
		}

		return null;
	}

	private void drawOnMap(Graphics2D graphics, int point, boolean checkHover, Point cursorPos)
	{
		drawOnMap(graphics, point, WorldPointUtil.dxdy(point, 1, -1), checkHover, cursorPos);
	}

	private void drawOnMap(Graphics2D graphics, int point, int offsetPoint, boolean checkHover, Point cursorPos)
	{
		int startX = plugin.mapWorldPointToGraphicsPointX(point);
		int startY = plugin.mapWorldPointToGraphicsPointY(point);
		int endX = plugin.mapWorldPointToGraphicsPointX(offsetPoint);
		int endY = plugin.mapWorldPointToGraphicsPointY(offsetPoint);

		if (startX == Integer.MIN_VALUE || startY == Integer.MIN_VALUE ||
			endX == Integer.MIN_VALUE || endY == Integer.MIN_VALUE)
		{
			return;
		}

		int x = startX;
		int y = startY;
		final int width = endX - x;
		final int height = endY - y;
		x -= width / 2;
		y -= height / 2;

		if (WorldPointUtil.distanceBetween(point, offsetPoint) > 1)
		{
			graphics.setStroke(new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_BEVEL, 0, new float[]{9}, 0));
			graphics.drawLine(startX, startY, endX, endY);
		}
		else
		{
			if (checkHover && cursorPos != null &&
				cursorPos.getX() >= x && cursorPos.getX() <= (endX - width / 2) &&
				cursorPos.getY() >= y && cursorPos.getY() <= (endY - width / 2))
			{
				graphics.setColor(graphics.getColor().darker());
			}
			graphics.fillRect(x, y, width, height);
		}
	}

	private Area getWorldMapClipArea(Rectangle baseRectangle)
	{
		final Widget overview = client.getWidget(InterfaceID.Worldmap.OVERVIEW_CONTAINER);
		final Widget surfaceSelector = client.getWidget(InterfaceID.Worldmap.MAPLIST_BOX_GRAPHIC0);

		Area clipArea = new Area(baseRectangle);

		if (overview != null && !overview.isHidden())
		{
			clipArea.subtract(new Area(overview.getBounds()));
		}

		if (surfaceSelector != null && !surfaceSelector.isHidden())
		{
			clipArea.subtract(new Area(surfaceSelector.getBounds()));
		}

		return clipArea;
	}

	private int getWorldMapExtentWidth(Rectangle baseRectangle)
	{
		return (WorldPointUtil.unpackWorldX(
			plugin.calculateMapPoint(
				baseRectangle.x + baseRectangle.width,
				baseRectangle.y + baseRectangle.height))
			-
			WorldPointUtil.unpackWorldX(
				plugin.calculateMapPoint(
					baseRectangle.x,
					baseRectangle.y)));
	}

	private int getWorldMapExtentHeight(Rectangle baseRectangle)
	{
		return (WorldPointUtil.unpackWorldY(
			plugin.calculateMapPoint(
				baseRectangle.x,
				baseRectangle.y))
			-
			WorldPointUtil.unpackWorldY(
				plugin.calculateMapPoint(
					baseRectangle.x + baseRectangle.width,
					baseRectangle.y + baseRectangle.height)));
	}
}

package com.travelguide;

import com.google.inject.Inject;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import com.travelguide.pathfinder.PathStep;
import com.travelguide.transport.Transport;

public class PathMapTooltipOverlay extends Overlay
{
	private static final int TOOLTIP_OFFSET_HEIGHT = 25;
	private static final int TOOLTIP_OFFSET_WIDTH = 15;
	private static final int TOOLTIP_PADDING_HEIGHT = 1;
	private static final int TOOLTIP_PADDING_WIDTH = 2;
	private static final int TOOLTIP_TEXT_OFFSET_HEIGHT = -2;

	private final Client client;
	private final TravelGuidePlugin plugin;

	@Inject
	private PathMapTooltipOverlay(Client client, TravelGuidePlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_HIGHEST);
		setLayer(OverlayLayer.MANUAL);
		drawAfterInterface(InterfaceID.WORLDMAP);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.drawMap || client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER) == null)
		{
			return null;
		}

		if (plugin.getPathfinder() != null)
		{
			List<PathStep> path = plugin.getPathfinder().getPath();
			Point cursorPos = client.getMouseCanvasPosition();
			for (int i = 0; i < path.size(); i++)
			{
				int nextPoint = WorldPointUtil.UNDEFINED;
				if (path.size() > i + 1)
				{
					nextPoint = path.get(i + 1).getPackedPosition();
				}
				if (drawTooltip(graphics, cursorPos, path.get(i).getPackedPosition(), nextPoint, i + 1, path, i))
				{
					return null;
				}
			}
			for (int target : plugin.getPathfinder().getTargets())
			{
				if (!path.isEmpty() && target != path.get(path.size() - 1).getPackedPosition())
				{
					drawTooltip(graphics, cursorPos, target, WorldPointUtil.UNDEFINED, -1, path, -1);
				}
			}
		}

		return null;
	}

	private boolean drawTooltip(Graphics2D graphics, Point cursorPos, int point, int nextPoint, int n,
		List<PathStep> path, int pathIndex)
	{
		int offsetPoint = WorldPointUtil.dxdy(point, 1, -1);
		int startX = plugin.mapWorldPointToGraphicsPointX(point);
		int startY = plugin.mapWorldPointToGraphicsPointY(point);
		int endX = plugin.mapWorldPointToGraphicsPointX(offsetPoint);
		int endY = plugin.mapWorldPointToGraphicsPointY(offsetPoint);

		if (startX == Integer.MIN_VALUE || startY == Integer.MIN_VALUE ||
			endX == Integer.MIN_VALUE || endY == Integer.MIN_VALUE)
		{
			return false;
		}

		int width = endX - startX;

		if (cursorPos.getX() < (startX - width / 2) || cursorPos.getX() > (endX - width / 2) ||
			cursorPos.getY() < (startY - width / 2) || cursorPos.getY() > (endY - width / 2))
		{
			return false;
		}

		List<String> rows = new ArrayList<>(Arrays.asList("Shortest path:",
			n < 0 ? "Unused target" : ("Step " + n + " of " + plugin.getPathfinder().getPath().size())));
		if (nextPoint != WorldPointUtil.UNDEFINED)
		{
			PathStep currentStep = path.get(pathIndex);
			PathStep nextStep = plugin.nextPathStep(path, pathIndex);
			for (Transport transport : plugin.transportsForEdge(currentStep, nextStep))
			{
				if (transport.getDisplayInfo() != null && !transport.getDisplayInfo().isEmpty())
				{
					String displayInfo = transport.getDisplayInfo();
					// Check if this transport goes to POH - if so, look ahead to find the exit
					// transport
					String pohExitInfo = plugin.getPohExitInfo(nextPoint, path, pathIndex);
					if (pohExitInfo != null)
					{
						displayInfo = displayInfo + " (Exit: " + pohExitInfo + ")";
					}
					rows.add(displayInfo);
					break;
				}
			}
		}

		graphics.setFont(FontManager.getRunescapeFont());
		FontMetrics fm = graphics.getFontMetrics();
		int tooltipHeight = fm.getHeight();
		int tooltipWidth = 0;
		if (rows.stream().map(fm::stringWidth).max(Integer::compare).isPresent())
		{
			tooltipWidth = rows.stream().map(fm::stringWidth).max(Integer::compareTo).get();
		}
		int clippedHeight = tooltipHeight * rows.size() + TOOLTIP_PADDING_HEIGHT * 2;
		int clippedWidth = tooltipWidth + TOOLTIP_PADDING_WIDTH * 2;

		Rectangle worldMapBounds = Objects.requireNonNull(client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER)).getBounds();
		int worldMapRightBoundary = worldMapBounds.width + worldMapBounds.x;
		int worldMapBottomBoundary = worldMapBounds.height + worldMapBounds.y;

		int drawPointX = startX + TOOLTIP_OFFSET_WIDTH;
		int drawPointY = startY;
		if (drawPointX + clippedWidth > worldMapRightBoundary)
		{
			drawPointX = worldMapRightBoundary - clippedWidth;
		}
		if (drawPointY + clippedHeight > worldMapBottomBoundary)
		{
			drawPointY = startY - clippedHeight;
		}
		drawPointY += TOOLTIP_OFFSET_HEIGHT;

		int tooltipRectX = drawPointX - TOOLTIP_PADDING_WIDTH;
		int tooltipRectY = drawPointY - TOOLTIP_PADDING_HEIGHT;

		graphics.setColor(JagexColors.TOOLTIP_BACKGROUND);
		graphics.fillRect(tooltipRectX, tooltipRectY, clippedWidth, clippedHeight);

		graphics.setColor(JagexColors.TOOLTIP_BORDER);
		graphics.drawRect(tooltipRectX, tooltipRectY, clippedWidth, clippedHeight);

		graphics.setColor(JagexColors.TOOLTIP_TEXT);
		for (int i = 0; i < rows.size(); i++)
		{
			graphics.drawString(rows.get(i), drawPointX, drawPointY + TOOLTIP_TEXT_OFFSET_HEIGHT + (i + 1) * tooltipHeight);
		}

		return true;
	}
}

package com.travelguide;

import com.google.inject.Inject;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import com.travelguide.pathfinder.PathStep;

public class PathMinimapOverlay extends Overlay
{
	private final Client client;
	private final TravelGuidePlugin plugin;

	@Inject
	private PathMinimapOverlay(Client client, TravelGuidePlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	public static void renderMinimapRect(Client client, Graphics2D graphics, Point center, Color color)
	{
		double angle = client.getCameraYawTarget() * Perspective.UNIT;
		double tileSize = client.getMinimapZoom();
		int x = (int) Math.round(center.getX() - tileSize / 2);
		int y = (int) Math.round(center.getY() - tileSize / 2);
		int width = (int) Math.round(tileSize);
		int height = (int) Math.round(tileSize);
		graphics.setColor(color);
		graphics.rotate(angle, center.getX(), center.getY());
		graphics.fillRect(x, y, width, height);
		graphics.rotate(-angle, center.getX(), center.getY());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.drawMinimap || plugin.getPathfinder() == null)
		{
			return null;
		}

		Shape minimapClipArea = plugin.getMinimapClipArea();
		if (minimapClipArea == null)
		{
			return null;
		}
		else
		{
			graphics.setClip(plugin.getMinimapClipArea());
		}
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);

		java.util.List<PathStep> pathPoints = plugin.getPathfinder().getPath();
		Color pathColor = plugin.getPathColor();
		for (PathStep point : pathPoints)
		{
			int pathPoint = point.getPackedPosition();
			if (WorldPointUtil.unpackWorldPlane(pathPoint) != client.getTopLevelWorldView().getPlane())
			{
				continue;
			}

			drawOnMinimap(graphics, pathPoint, pathColor);
		}
		for (int target : plugin.getPathfinder().getTargets())
		{
			if (!pathPoints.isEmpty() && target != pathPoints.get(pathPoints.size() - 1).getPackedPosition())
			{
				drawOnMinimap(graphics, target, plugin.colourPathCalculating);
			}
		}

		return null;
	}

	private void drawOnMinimap(Graphics2D graphics, int location, Color color)
	{
		PrimitiveIntList points = WorldPointUtil.toLocalInstance(client, location);
		for (int i = 0; i < points.size(); i++)
		{
			LocalPoint lp = WorldPointUtil.toLocalPoint(client, points.get(i));

			if (lp == null)
			{
				continue;
			}

			Point posOnMinimap = Perspective.localToMinimap(client, lp);

			if (posOnMinimap == null)
			{
				continue;
			}

			renderMinimapRect(client, graphics, posOnMinimap, color);
		}
	}
}

package com.travelguide;

import com.google.inject.Inject;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.geom.Line2D;
import java.awt.geom.Rectangle2D;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.Set;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.Tile;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import com.travelguide.pathfinder.CollisionMap;
import com.travelguide.pathfinder.PathStep;
import com.travelguide.pathfinder.TransportAvailability;
import com.travelguide.transport.BankPickupRequirements;
import com.travelguide.transport.Transport;

public class PathTileOverlay extends Overlay
{
	private static final int TRANSPORT_LABEL_GAP = 3;
	private final Client client;
	private final TravelGuidePlugin plugin;
	private int playerTileLabelOffset = 0;

	@Inject
	public PathTileOverlay(Client client, TravelGuidePlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	private void renderTransports(Graphics2D graphics)
	{
		for (int a : plugin.getTransports().keys())
		{
			if (a == Transport.UNDEFINED_ORIGIN)
			{
				continue; // skip teleports
			}

			boolean drawStart = false;

			Point ca = tileCenter(a);

			if (ca == null)
			{
				continue;
			}

			StringBuilder s = new StringBuilder();
			for (Transport b : plugin.getTransports().getOrDefault(a, TransportAvailability.EMPTY_TRANSPORTS))
			{
				if (b == null || (b.getType() != null && b.getType().isTeleport()))
				{
					continue; // skip teleports
				}
				PrimitiveIntList destinations = WorldPointUtil.toLocalInstance(client, b.getDestination());
				for (int i = 0; i < destinations.size(); i++)
				{
					int destination = destinations.get(i);
					if (destination == Transport.UNDEFINED_DESTINATION)
					{
						continue;
					}
					Point cb = tileCenter(destination);
					if (cb != null)
					{
						graphics.drawLine(ca.getX(), ca.getY(), cb.getX(), cb.getY());
						drawStart = true;
					}
					if (WorldPointUtil.unpackWorldPlane(destination) > WorldPointUtil.unpackWorldPlane(a))
					{
						s.append("+");
					}
					else if (WorldPointUtil.unpackWorldPlane(destination) < WorldPointUtil.unpackWorldPlane(a))
					{
						s.append("-");
					}
					else
					{
						s.append("=");
					}
				}
			}

			if (drawStart)
			{
				drawTile(graphics, a, plugin.colourTransports, -1, true);
			}

			graphics.setColor(Color.WHITE);
			graphics.drawString(s.toString(), ca.getX(), ca.getY());
		}
	}

	private void renderCollisionMap(Graphics2D graphics)
	{
		CollisionMap map = plugin.getMap();
		for (Tile[] row : client.getTopLevelWorldView().getScene().getTiles()[client.getTopLevelWorldView().getPlane()])
		{
			for (Tile tile : row)
			{
				if (tile == null)
				{
					continue;
				}

				Polygon tilePolygon = Perspective.getCanvasTilePoly(client, tile.getLocalLocation());

				if (tilePolygon == null)
				{
					continue;
				}

				int location = WorldPointUtil.fromLocalInstance(client, tile.getLocalLocation());
				int x = WorldPointUtil.unpackWorldX(location);
				int y = WorldPointUtil.unpackWorldY(location);
				int z = WorldPointUtil.unpackWorldPlane(location);

				String s = (!map.n(x, y, z) ? "n" : "") +
					(!map.s(x, y, z) ? "s" : "") +
					(!map.e(x, y, z) ? "e" : "") +
					(!map.w(x, y, z) ? "w" : "");

				if (map.isBlocked(x, y, z))
				{
					graphics.setColor(plugin.colourCollisionMap);
					graphics.fill(tilePolygon);
				}
				if (!s.isEmpty() && !s.equals("nsew"))
				{
					graphics.setColor(Color.WHITE);
					int stringX = (int) (tilePolygon.getBounds().getCenterX()
						- graphics.getFontMetrics().getStringBounds(s, graphics).getWidth() / 2);
					int stringY = (int) tilePolygon.getBounds().getCenterY();
					graphics.drawString(s, stringX, stringY);
				}
			}
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		playerTileLabelOffset = 0;

		if (plugin.drawTransports)
		{
			renderTransports(graphics);
		}

		if (plugin.drawCollisionMap)
		{
			renderCollisionMap(graphics);
		}

		if (plugin.drawTiles && plugin.getPathfinder() != null && plugin.getPathfinder().getPath() != null)
		{
			Color colorCalculating = new Color(
				plugin.colourPathCalculating.getRed(),
				plugin.colourPathCalculating.getGreen(),
				plugin.colourPathCalculating.getBlue(),
				plugin.colourPathCalculating.getAlpha() / 2);
			Color pathColor = plugin.getPathColor();
			Color color = new Color(
				pathColor.getRed(),
				pathColor.getGreen(),
				pathColor.getBlue(),
				pathColor.getAlpha() / 2);

			List<PathStep> path = plugin.getPathfinder().getPath();
			int counter = 0;
			if (TileStyle.LINES.equals(plugin.pathStyle))
			{
				for (int i = 1; i < path.size(); i++)
				{
					PathStep currentStep = path.get(i - 1);
					PathStep nextStep = path.get(i);
					drawLine(graphics, currentStep.getPackedPosition(), nextStep.getPackedPosition(), color, 1 + counter++);
					drawTransportInfo(graphics, currentStep, nextStep, path, i - 1);
				}
			}
			else
			{
				boolean showTiles = TileStyle.TILES.equals(plugin.pathStyle);
				for (int i = 0; i < path.size(); i++)
				{
					// Skip drawing tiles inside POH (no collision data, tiles render at wrong positions)
					PathStep currentStep = path.get(i);
					int pathPoint = currentStep.getPackedPosition();
					int pathX = WorldPointUtil.unpackWorldX(pathPoint);
					int pathY = WorldPointUtil.unpackWorldY(pathPoint);
					if (!TravelGuidePlugin.isInsidePoh(pathX, pathY))
					{
						drawTile(graphics, pathPoint, color, counter, showTiles);
					}
					counter++;
					drawTransportInfo(graphics, currentStep, plugin.nextPathStep(path, i), path, i);
				}
				for (int target : plugin.getPathfinder().getTargets())
				{
					if (!path.isEmpty() && target != path.get(path.size() - 1).getPackedPosition())
					{
						drawTile(graphics, target, colorCalculating, -1, showTiles);
					}
				}
			}

			if (plugin.isPathUnreachable())
			{
				playerTileLabelOffset += drawLabelOnPlayerTile(graphics, plugin.unreachableText, playerTileLabelOffset);
			}
		}

		return null;
	}

	private Point tileCenter(int b)
	{
		if (b == WorldPointUtil.UNDEFINED || client == null)
		{
			return null;
		}

		if (WorldPointUtil.unpackWorldPlane(b) != client.getTopLevelWorldView().getPlane())
		{
			return null;
		}

		LocalPoint lp = WorldPointUtil.toLocalPoint(client, b);
		if (lp == null)
		{
			return null;
		}

		Polygon poly = Perspective.getCanvasTilePoly(client, lp);
		if (poly == null)
		{
			return null;
		}

		int cx = poly.getBounds().x + poly.getBounds().width / 2;
		int cy = poly.getBounds().y + poly.getBounds().height / 2;
		return new Point(cx, cy);
	}

	private void drawTile(Graphics2D graphics, int location, Color color, int counter, boolean draw)
	{
		if (client == null)
		{
			return;
		}

		PrimitiveIntList points = WorldPointUtil.toLocalInstance(client, location);
		for (int i = 0; i < points.size(); i++)
		{
			int point = points.get(i);
			if (point == WorldPointUtil.UNDEFINED)
			{
				continue;
			}

			LocalPoint lp = WorldPointUtil.toLocalPoint(client, point);
			if (lp == null)
			{
				continue;
			}

			Polygon poly = Perspective.getCanvasTilePoly(client, lp);
			if (poly == null)
			{
				continue;
			}

			if (draw)
			{
				graphics.setColor(color);
				graphics.fill(poly);
			}

			drawCounter(graphics, poly.getBounds().getCenterX(), poly.getBounds().getCenterY(), counter);
		}
	}

	private void drawLine(Graphics2D graphics, int startLoc, int endLoc, Color color, int counter)
	{
		PrimitiveIntList starts = WorldPointUtil.toLocalInstance(client, startLoc);
		PrimitiveIntList ends = WorldPointUtil.toLocalInstance(client, endLoc);

		if (starts.isEmpty() || ends.isEmpty())
		{
			return;
		}

		int start = starts.get(0);
		int end = ends.get(0);

		final int z = client.getTopLevelWorldView().getPlane();
		if (WorldPointUtil.unpackWorldPlane(start) != z)
		{
			return;
		}

		LocalPoint lpStart = WorldPointUtil.toLocalPoint(client, start);
		LocalPoint lpEnd = WorldPointUtil.toLocalPoint(client, end);

		if (lpStart == null || lpEnd == null)
		{
			return;
		}

		final int startHeight = Perspective.getTileHeight(client, lpStart, z);
		final int endHeight = Perspective.getTileHeight(client, lpEnd, z);

		Point p1 = Perspective.localToCanvas(client, lpStart.getX(), lpStart.getY(), startHeight);
		Point p2 = Perspective.localToCanvas(client, lpEnd.getX(), lpEnd.getY(), endHeight);

		if (p1 == null || p2 == null)
		{
			return;
		}

		Line2D.Double line = new Line2D.Double(p1.getX(), p1.getY(), p2.getX(), p2.getY());

		graphics.setColor(color);
		graphics.setStroke(new BasicStroke(4));
		graphics.draw(line);

		if (counter == 1)
		{
			drawCounter(graphics, p1.getX(), p1.getY(), 0);
		}
		drawCounter(graphics, p2.getX(), p2.getY(), counter);
	}

	private void drawCounter(Graphics2D graphics, double x, double y, int counter)
	{
		if (counter >= 0 && !TileCounter.DISABLED.equals(plugin.showTileCounter))
		{
			int n = plugin.tileCounterStep > 0 ? plugin.tileCounterStep : 1;
			int s = plugin.getPathfinder().getPath().size();
			if ((counter % n != 0) && (s != (counter + 1)))
			{
				return;
			}
			if (TileCounter.REMAINING.equals(plugin.showTileCounter))
			{
				counter = s - counter - 1;
			}
			if (n > 1 && counter == 0)
			{
				return;
			}
			String counterText = Integer.toString(counter);
			graphics.setColor(plugin.colourText);
			graphics.drawString(
				counterText,
				(int) (x - graphics.getFontMetrics().getStringBounds(counterText, graphics).getWidth() / 2), (int) y);
		}
	}

	private int drawLabelAtCanvasPoint(Graphics2D graphics, Point point, String text, int verticalOffset)
	{
		if (point == null || text == null || text.isEmpty())
		{
			return 0;
		}

		double height = drawLabel(graphics, point, text, verticalOffset);

		return (int) height + TRANSPORT_LABEL_GAP;
	}

	private int drawLabelAtPackedLocation(Graphics2D graphics, int location, String text, int verticalOffset)
	{
		PrimitiveIntList points = WorldPointUtil.toLocalInstance(client, location);
		for (int i = 0; i < points.size(); i++)
		{
			LocalPoint lp = WorldPointUtil.toLocalPoint(client, points.get(i));
			if (lp == null)
			{
				continue;
			}

			Point p = Perspective.localToCanvas(client, lp, client.getTopLevelWorldView().getPlane());
			if (p == null)
			{
				continue;
			}

			verticalOffset += drawLabelAtCanvasPoint(graphics, p, text, verticalOffset);
		}
		return verticalOffset;
	}

	private double drawLabel(Graphics2D graphics, Point point, String text, int verticalOffset)
	{
		Rectangle2D textBounds = graphics.getFontMetrics().getStringBounds(text, graphics);
		double height = textBounds.getHeight();
		int x = (int) (point.getX() - textBounds.getWidth() / 2);
		int y = (int) (point.getY() - height) - verticalOffset;
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(plugin.colourText);
		graphics.drawString(text, x, y);
		return height;
	}

	private int drawLabelOnPlayerTile(Graphics2D graphics, String text, int verticalOffset)
	{
		if (client.getLocalPlayer() == null)
		{
			return 0;
		}

		Point playerPoint = Perspective.localToCanvas(client, client.getLocalPlayer().getLocalLocation(), client.getTopLevelWorldView().getPlane());
		return drawLabelAtCanvasPoint(graphics, playerPoint, text, verticalOffset);
	}

	private void drawTransportInfo(Graphics2D graphics, PathStep currentStep, PathStep nextStep, List<PathStep> path, int pathIndex)
	{
		int location = currentStep.getPackedPosition();
		if (nextStep == null || !plugin.showTransportInfo ||
			WorldPointUtil.unpackWorldPlane(location) != client.getTopLevelWorldView().getPlane())
		{
			return;
		}

		// Sailing: teleports are suppressed while aboard a boat. When the path is
		// unreachable as a result, show a one-time hint on the player tile.
		if (pathIndex == 0 && plugin.getPathfinderConfig().isOnSailingBoat()
			&& plugin.getPathfinder().isDone() && plugin.isPathUnreachable())
		{
			playerTileLabelOffset = drawLabelOnPlayerTile(graphics,
				"Disembark the boat to resume pathfinding", playerTileLabelOffset);
			return;
		}

		if (plugin.isPathUnreachable() || !plugin.getPathfinder().isDone())
		{
			return;
		}
		int locationEnd = nextStep.getPackedPosition();

		// Workaround for weird pathing inside PoH to instead show info on the player
		// tile
		LocalPoint playerLocalPoint = client.getLocalPlayer().getLocalLocation();
		int playerPackedPoint = WorldPointUtil.fromLocalInstance(client, playerLocalPoint);
		int px = WorldPointUtil.unpackWorldX(playerPackedPoint);
		int py = WorldPointUtil.unpackWorldY(playerPackedPoint);
		int tx = WorldPointUtil.unpackWorldX(location);
		int ty = WorldPointUtil.unpackWorldY(location);
		boolean transportAndPlayerInsidePoh = TravelGuidePlugin.isInsidePoh(tx, ty)
			&& TravelGuidePlugin.isInsidePoh(px, py);
		Set<Transport> candidateTransports = plugin.transportsForEdge(currentStep, nextStep);

		// When inside POH, only show the POH exit info once (not per-transport)
		if (transportAndPlayerInsidePoh)
		{
			String pohExitInfo = plugin.getPohExitInfo(locationEnd, path, pathIndex);
			if (pohExitInfo == null)
			{
				return;
			}

			// Find the display name of the teleport that brought us to POH using bank-aware
			// lookup
			String text = null;
			for (Transport transport : candidateTransports)
			{
				text = transport.getDisplayInfo();
				if (text != null && !text.isEmpty())
				{
					break;
				}
			}
			if (text == null || text.isEmpty())
			{
				return;
			}
			text = text + " (Exit: " + pohExitInfo + ")";

			Point p = Perspective.localToCanvas(client, playerLocalPoint, client.getTopLevelWorldView().getPlane());
			if (p == null)
			{
				return;
			}

			drawLabel(graphics, p, text, 0);
			return;
		}

		// Check if this is a bank step and items need to be picked up
		Set<Integer> bankLocations = plugin.getPathfinderConfig().getDestinations("bank");
		if (bankLocations != null && plugin.getPathfinderConfig().bank != null)
		{
			List<String> bankPickupItems = BankPickupRequirements.getRequiredBankItems(
				client,
				plugin.getPathfinderConfig().bank,
				plugin.getPathfinderConfig(),
				bankLocations,
				path,
				pathIndex
			);
			if (!bankPickupItems.isEmpty())
			{
				String pickupText = "Pick up: " + String.join(", ", bankPickupItems);
				playerTileLabelOffset = drawLabelAtPackedLocation(graphics, location, pickupText, playerTileLabelOffset);

				// By default, bank pickup info replaces the default transport hint text;
				// enable the option to show both
				if (!plugin.showBankPickupInfo)
				{
					return;
				}
			}
		}

		// Only show transports the player can currently use; fall back to all if none are usable.
		Map<Integer, Integer> playerHas = BankPickupRequirements.collectPlayerItems(client);
		List<Transport> usableTransports = new ArrayList<>();
		for (Transport t : candidateTransports)
		{
			if (BankPickupRequirements.transportSatisfiedBy(t, playerHas))
			{
				usableTransports.add(t);
			}
		}
		Collection<Transport> transportsToShow = usableTransports.isEmpty() ? candidateTransports : usableTransports;

		for (Transport transport : transportsToShow)
		{
			String text = transport.getDisplayInfo();
			if (text == null || text.isEmpty())
			{
				continue;
			}

			// Check if this transport goes to POH - if so, look ahead to find the exit
			// transport
			String pohExitInfo = plugin.getPohExitInfo(locationEnd, path, pathIndex);
			if (pohExitInfo != null)
			{
				text = text + " (Exit: " + pohExitInfo + ")";
			}

			playerTileLabelOffset = drawLabelAtPackedLocation(graphics, location, text, playerTileLabelOffset);
		}
	}
}

package com.travelguide;

public class PendingTask
{
	private final int tick;
	private final Runnable task;

	PendingTask(int tick, Runnable task)
	{
		this.tick = tick;
		this.task = task;
	}

	public boolean check(int tick)
	{
		return tick >= this.tick;
	}

	public void run()
	{
		task.run();
	}
}

package com.travelguide;

import java.util.Arrays;
import java.util.Collection;

/**
 * A lightweight hash map keyed by primitive {@code int} values using an open-addressed table with
 * linear probing.
 * <p>
 * Keys and values are stored in two parallel arrays ({@link #keys} / {@link #values}) rather than a
 * node object per entry, so the map holds only a couple of arrays regardless of how many entries it
 * contains (issue #491). A slot is occupied iff its value reference is non-null; since null values
 * are rejected, {@code int} keys including {@code 0} need no separate sentinel. When the entry count
 * reaches the configured {@linkplain #capacity load threshold} the table is rehashed into a larger
 * power-of-two array.
 * <p>
 * This implementation is intentionally minimal and tailored for the plugin's pathfinding needs:
 * <ul>
 * <li>No support for removing entries.</li>
 * <li>No iteration views (keys, values, or entry set) are exposed beyond {@link #keys()}.</li>
 * <li>Duplicate key insertion replaces the previous value, or appends collection contents when both
 * the old and new values are {@link Collection}s (best effort; falls back to replacement on
 * errors).</li>
 * </ul>
 *
 * @param <V> the value type stored for each primitive {@code int} key. Must be non-null.
 */
public class PrimitiveIntHashMap<V>
{
	private static final int MINIMUM_SIZE = 8;

	// How full the map should get before growing it again. Smaller values speed up
	// lookup times at the expense of space
	private static final float DEFAULT_LOAD_FACTOR = 0.75f;
	private final float loadFactor;
	private int[] keys;
	private Object[] values;
	private int size;
	private int capacity;
	private int maxSize;
	private int mask;

	/**
	 * Creates a new map with the specified initial size and the default load factor (0.75).
	 *
	 * @param initialSize initial expected number of elements; rounded to the next power of two
	 *                    internally.
	 */
	public PrimitiveIntHashMap(int initialSize)
	{
		this(initialSize, DEFAULT_LOAD_FACTOR);
	}

	/**
	 * Creates a new map with the given initial size and load factor.
	 *
	 * @param initialSize initial expected number of elements; rounded up to maintain a
	 *                    power-of-two capacity.
	 * @param loadFactor  a value in the range {@code [0.0, 1.0]} determining when the map rehashes.
	 * @throws IllegalArgumentException if {@code loadFactor} is outside the inclusive range 0..1.
	 */
	public PrimitiveIntHashMap(int initialSize, float loadFactor)
	{
		if (loadFactor < 0.0f || loadFactor > 1.0f)
		{
			throw new IllegalArgumentException("Load factor must be between 0 and 1");
		}

		this.loadFactor = loadFactor;
		size = 0;
		setNewSize(initialSize);
		recreateArrays();
	}

	/**
	 * Hash function tuned for packed world point integer encodings. Mixes higher bits downward to
	 * reduce clustering while remaining inexpensive.
	 */
	private static int hash(int value)
	{
		// Full multiplicative avalanche. Linear probing is very sensitive to clustering, and packed
		// world points of nearby tiles differ only in a few low bits, so the cheap xor-shift mix used
		// previously left spatially-clustered transport origins clustered in the table too -> long
		// probe runs on the per-tile miss lookups. Fibonacci-style multiply + xorshift spreads them.
		int h = value * 0x9E3779B1;
		return h ^ (h >>> 16);
	}

	/**
	 * Returns the number of key/value pairs currently stored.
	 *
	 * @return current entry count (always {@code >= 0}).
	 */
	public int size()
	{
		return size;
	}

	/**
	 * Returns all keys present in the map as a freshly allocated {@code int[]}.
	 *
	 * @return array of all keys in unspecified order; length equals {@link #size()}.
	 */
	@SuppressWarnings("unused")
	public int[] keys()
	{
		int[] result = new int[size];
		int index = 0;
		for (int i = 0; i < values.length; ++i)
		{
			if (values[i] != null)
			{
				result[index++] = keys[i];
			}
		}
		return result;
	}

	/**
	 * Retrieves the value mapped to the provided key, or {@code null} if absent.
	 *
	 * @param key primitive key to look up.
	 * @return the mapped value, or {@code null} if the key does not exist.
	 */
	public V get(int key)
	{
		return getOrDefault(key, null);
	}

	/**
	 * Retrieves the value mapped to the provided key.
	 *
	 * @param key          primitive key to look up.
	 * @param defaultValue value to return if the key is not present.
	 * @return the mapped value, or {@code defaultValue} when absent.
	 */
	@SuppressWarnings("unchecked")
	public V getOrDefault(int key, V defaultValue)
	{
		final int slot = findSlot(key);
		if (slot < 0)
		{
			return defaultValue;
		}
		return (V) values[slot];
	}

	/**
	 * Associates the specified value with the given key.
	 * <p>
	 * If a mapping already exists and both the existing and new values implement {@link Collection},
	 * the method attempts to append all elements of the new collection into the existing one. If the
	 * append fails (e.g., due to incompatible element types or an unsupported operation) the existing
	 * value is replaced entirely. Otherwise the existing value is simply replaced.
	 *
	 * @param key   primitive key to insert or update.
	 * @param value non-null value to associate.
	 * @param <E>   inferred element type if both values are collections.
	 * @return the previous value mapped to {@code key} (if any), or {@code null} if inserting a new
	 * entry.
	 * @throws IllegalArgumentException if {@code value} is {@code null}.
	 */
	@SuppressWarnings({"unchecked"})
	public <E> V put(int key, V value)
	{
		if (value == null)
		{
			throw new IllegalArgumentException("Cannot insert a null value");
		}

		int i = (hash(key) & 0x7FFFFFFF) & mask;
		while (values[i] != null)
		{
			if (keys[i] == key)
			{
				V previous = (V) values[i];
				if (previous instanceof Collection<?> && value instanceof Collection<?>)
				{ // append
					try
					{
						Collection<E> prevCollection = (Collection<E>) values[i];
						Collection<E> newCollection = (Collection<E>) value;
						prevCollection.addAll(newCollection);
					}
					catch (ClassCastException | UnsupportedOperationException e)
					{
						// If the collections contain incompatible types or the operation is not
						// supported, just replace instead of append
						values[i] = value;
					}
				}
				else
				{ // replace
					values[i] = value;
				}
				return previous;
			}
			i = (i + 1) & mask;
		}

		keys[i] = key;
		values[i] = value;
		incrementSize();
		return null;
	}

	private int findSlot(int key)
	{
		int i = (hash(key) & 0x7FFFFFFF) & mask;
		while (values[i] != null)
		{
			if (keys[i] == key)
			{
				return i;
			}
			i = (i + 1) & mask;
		}
		return -1;
	}

	private void incrementSize()
	{
		size++;
		if (size >= capacity)
		{
			rehash();
		}
	}

	private int getNewMaxSize(int size)
	{
		int nextPow2 = -1 >>> Integer.numberOfLeadingZeros(size);
		if (nextPow2 >= (Integer.MAX_VALUE >>> 1))
		{
			return (Integer.MAX_VALUE >>> 1) + 1;
		}
		return nextPow2 + 1;
	}

	private void setNewSize(int size)
	{
		if (size < MINIMUM_SIZE)
		{
			size = MINIMUM_SIZE - 1;
		}

		maxSize = getNewMaxSize(size);
		mask = maxSize - 1;
		capacity = (int) (maxSize * loadFactor);
	}

	private void growCapacity()
	{
		setNewSize(maxSize);
	}

	// Grow the table then rehash all the values into it and discard the old arrays
	private void rehash()
	{
		growCapacity();

		final int[] oldKeys = keys;
		final Object[] oldValues = values;
		recreateArrays();

		for (int i = 0; i < oldValues.length; ++i)
		{
			if (oldValues[i] == null)
			{
				continue;
			}

			int slot = (hash(oldKeys[i]) & 0x7FFFFFFF) & mask;
			while (values[slot] != null)
			{
				slot = (slot + 1) & mask;
			}
			keys[slot] = oldKeys[i];
			values[slot] = oldValues[i];
		}
	}

	private void recreateArrays()
	{
		keys = new int[maxSize];
		values = new Object[maxSize];
	}

	/**
	 * Approximate fullness of the table as a percentage of the entry count over the table length.
	 *
	 * @return fullness percentage in {@code [0.0, 100.0]}, or {@link Double#NaN} when the map is
	 * empty.
	 */
	public double calculateFullness()
	{
		if (size == 0)
		{
			return Double.NaN;
		}
		return 100.0 * (double) size / (double) maxSize;
	}

	/**
	 * Removes all entries from the map. The backing arrays are retained and reused.
	 */
	public void clear()
	{
		size = 0;
		Arrays.fill(values, null);
	}
}

package com.travelguide;

import java.util.Arrays;

/**
 * A minimal, growable list implementation for primitive {@code int} values.
 * <p>
 * This class avoids boxing overhead present in {@link java.util.List Integer}
 * collections
 * by storing values in a backing {@code int[]} that grows as needed. It
 * purposefully
 * implements only the operations required by the pathfinding logic in this
 * plugin; it is
 * <strong>not</strong> a drop‑in replacement for {@link java.util.ArrayList}.
 * <p>
 * The growth policy increases capacity by 50% (similar to {@code ArrayList})
 * when the
 * existing array is exhausted. Capacity never shrinks.
 */
public class PrimitiveIntList
{
	private static final int MAX_ARRAY_SIZE = Integer.MAX_VALUE - 8;

	private int[] elementData;
	private int size;

	/**
	 * Creates a new list with the specified initial capacity.
	 *
	 * @param initialCapacity the initial length of the backing array (must be
	 *                        {@code >= 0}).
	 * @param initialize      if {@code true}, the {@link #size} is set equal to
	 *                        {@code initialCapacity},
	 *                        effectively pre-filling the logical list with zeroes.
	 *                        If {@code false},
	 *                        the list is created empty.
	 * @throws IllegalArgumentException if {@code initialCapacity < 0}.
	 */
	public PrimitiveIntList(int initialCapacity, boolean initialize)
	{
		if (initialCapacity < 0)
		{
			throw new IllegalArgumentException("Illegal capacity: " + initialCapacity);
		}
		this.elementData = new int[initialCapacity];
		if (initialize)
		{
			size = initialCapacity;
		}
	}

	/**
	 * Creates an empty list with the given backing array capacity.
	 *
	 * @param initialCapacity initial length of the internal array (must be
	 *                        {@code >= 0}).
	 */
	public PrimitiveIntList(int initialCapacity)
	{
		this(initialCapacity, false);
	}

	/**
	 * Creates an empty list with a default initial capacity of 10.
	 */
	public PrimitiveIntList()
	{
		this(10);
	}

	private static int hugeCapacity(int minCapacity)
	{
		if (minCapacity < 0)
		{ // overflow
			throw new OutOfMemoryError();
		}
		return (minCapacity > MAX_ARRAY_SIZE) ? Integer.MAX_VALUE : MAX_ARRAY_SIZE;
	}

	/**
	 * Ensures that the backing array can store at least {@code minCapacity}
	 * elements.
	 * If the current capacity is already sufficient the call is a no-op.
	 *
	 * @param minCapacity the desired minimum capacity (ignored if {@code <= 0}).
	 */
	public void ensureCapacity(int minCapacity)
	{
		if (minCapacity > 0)
		{
			ensureCapacityInternal(minCapacity);
		}
	}

	private void ensureCapacityInternal(int minCapacity)
	{
		if (minCapacity - elementData.length > 0)
		{
			grow(minCapacity);
		}
	}

	private void grow(int minCapacity)
	{
		int oldCapacity = elementData.length;
		int newCapacity = oldCapacity + (oldCapacity >> 1);
		if (newCapacity - minCapacity < 0)
		{
			newCapacity = minCapacity;
		}
		if (newCapacity - MAX_ARRAY_SIZE > 0)
		{
			newCapacity = hugeCapacity(minCapacity);
		}
		elementData = Arrays.copyOf(elementData, newCapacity);
	}

	/**
	 * Returns the number of elements that have been added to (or initialized in)
	 * this list.
	 *
	 * @return current element count (always {@code >= 0}).
	 */
	public int size()
	{
		return size;
	}

	/**
	 * Indicates whether the list currently holds zero elements.
	 *
	 * @return {@code true} if {@link #size()} is zero; {@code false} otherwise.
	 */
	public boolean isEmpty()
	{
		return size == 0;
	}

	/**
	 * Tests whether the specified primitive value exists in the list.
	 *
	 * @param e the value to search for.
	 * @return {@code true} if the value occurs at least once; {@code false}
	 * otherwise.
	 */
	public boolean contains(int e)
	{
		return indexOf(e) >= 0;
	}

	/**
	 * Returns the index of the first occurrence of the given value, or {@code -1}
	 * if absent.
	 *
	 * @param e the value to locate.
	 * @return zero-based index of the value, or {@code -1} if not found.
	 */
	public int indexOf(int e)
	{
		for (int i = 0; i < size; i++)
		{
			if (e == elementData[i])
			{
				return i;
			}
		}
		return -1;
	}

	/**
	 * Retrieves the value at the specified index.
	 *
	 * @param index zero-based position of the element to return.
	 * @return the value stored at {@code index}.
	 * @throws IndexOutOfBoundsException if {@code index < 0 || index >= size}.
	 */
	public int get(int index)
	{
		rangeCheck(index);
		return elementData[index];
	}

	/**
	 * Replaces the value at the specified index.
	 *
	 * @param index   zero-based position of the element to overwrite.
	 * @param element the new value.
	 * @return the previous value stored at {@code index}.
	 * @throws IndexOutOfBoundsException if {@code index < 0 || index >= size}.
	 */
	public int set(int index, int element)
	{
		rangeCheck(index);
		int oldValue = elementData[index];
		elementData[index] = element;
		return oldValue;
	}

	/**
	 * Appends a value to the end of the list, growing the backing array if
	 * required.
	 *
	 * @param e value to append.
	 */
	public void add(int e)
	{
		ensureCapacityInternal(size + 1);
		elementData[size++] = e;
	}

	/**
	 * Inserts a value at the specified index, shifting subsequent elements one
	 * position to the right.
	 *
	 * @param index   zero-based insertion point (may be equal to {@link #size()} to
	 *                append).
	 * @param element the value to insert.
	 * @throws IndexOutOfBoundsException if {@code index < 0 || index > size}.
	 */
	public void add(int index, int element)
	{
		rangeCheckForAdd(index);
		ensureCapacityInternal(size + 1);
		System.arraycopy(elementData, index, elementData, index + 1, size - index);
		elementData[index] = element;
		size++;
	}

	/**
	 * Removes the value at the specified index and compacts the list.
	 *
	 * @param index zero-based index of the element to remove.
	 * @return the removed value.
	 * @throws IndexOutOfBoundsException if {@code index < 0 || index >= size}.
	 */
	public int removeAt(int index)
	{
		rangeCheck(index);
		int oldValue = elementData[index];
		int numMoved = size - index - 1;
		if (numMoved > 0)
		{
			System.arraycopy(elementData, index + 1, elementData, index, numMoved);
		}
		elementData[--size] = 0;
		return oldValue;
	}

	/**
	 * Removes the first occurrence of the specified value, if present.
	 *
	 * @param e value to remove.
	 * @return {@code true} if a value was removed; {@code false} otherwise.
	 */
	public boolean remove(int e)
	{
		for (int i = 0; i < size; i++)
		{
			if (e == elementData[i])
			{
				fastRemove(i);
				return true;
			}
		}
		return false;
	}

	private void fastRemove(int index)
	{
		int numMoved = size - index - 1;
		if (numMoved > 0)
		{
			System.arraycopy(elementData, index + 1, elementData, index, numMoved);
		}
		elementData[--size] = 0;
	}

	/**
	 * Removes all elements from the list and resets {@link #size()} to zero.
	 * The backing array is retained for reuse.
	 */
	public void clear()
	{
		for (int i = 0; i < size; i++)
		{
			elementData[i] = 0;
		}
		size = 0;
	}

	private void rangeCheck(int index)
	{
		if (index >= size)
		{
			throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);
		}
	}

	private void rangeCheckForAdd(int index)
	{
		if (index > size || index < 0)
		{
			throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);
		}
	}
}

