	 * any thread.
	 */
	public void guideTo(int packedTarget, String label)
	{
		guideTo(Set.of(packedTarget), label);
	}

	/**
	 * Starts guiding to whichever of several candidate tiles is closest by route
	 * (e.g. the spawns of an NPC). Safe to call from any thread.
	 */
	public void guideTo(Set<Integer> targets, String label)
	{
		if (targets == null || targets.isEmpty())
		{
			return;
		}
		clientThread.invokeLater(() ->
		{
			pendingTargetLabel = label;
			setTargets(new HashSet<>(targets), false);
		});
	}

