package com.travelguide.guide;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.List;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Item;

/**
 * Remembers bank contents on disk per account so routes can plan around banked items
 * before the bank has been opened in the current session.
 */
@Slf4j
public final class BankMemory
{
	@Value
	public static class Snapshot
	{
		long savedAt;
		Item[] items;
	}

	/** Wire format: {"savedAt": millis, "items": [[id, quantity], ...]} */
	private static class Dto
	{
		long savedAt;
		List<int[]> items;
	}

	private BankMemory()
	{
	}

	public static File fileFor(File dir, long accountHash)
	{
		return new File(dir, "bank-" + Long.toUnsignedString(accountHash) + ".json");
	}

	public static String serialize(Gson gson, Item[] items, long savedAt)
	{
		Dto dto = new Dto();
		dto.savedAt = savedAt;
		dto.items = new ArrayList<>();
		if (items != null)
		{
			for (Item item : items)
			{
				if (item != null && item.getId() >= 0 && item.getQuantity() > 0)
				{
					dto.items.add(new int[]{item.getId(), item.getQuantity()});
				}
			}
		}
		return gson.toJson(dto);
	}

	public static Snapshot parse(Gson gson, String json)
	{
		Dto dto = gson.fromJson(json, Dto.class);
		if (dto == null || dto.items == null)
		{
			return null;
		}
		List<Item> items = new ArrayList<>(dto.items.size());
		for (int[] pair : dto.items)
		{
			if (pair != null && pair.length >= 2 && pair[0] >= 0 && pair[1] > 0)
			{
				items.add(new Item(pair[0], pair[1]));
			}
		}
		return new Snapshot(dto.savedAt, items.toArray(new Item[0]));
	}

	/** Writes the snapshot; failures are logged, never thrown. */
	public static void save(Gson gson, File dir, long accountHash, Item[] items)
	{
		try
		{
			if (!dir.exists() && !dir.mkdirs())
			{
				log.warn("Could not create {}", dir);
				return;
			}
			File file = fileFor(dir, accountHash);
			File tmp = new File(file.getPath() + ".tmp");
			Files.write(tmp.toPath(), serialize(gson, items, System.currentTimeMillis()).getBytes(StandardCharsets.UTF_8));
			Files.move(tmp.toPath(), file.toPath(), java.nio.file.StandardCopyOption.REPLACE_EXISTING);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Failed to save bank snapshot", e);
		}
	}

	/** Reads the snapshot for an account, or null when none exists or it is unreadable. */
	public static Snapshot load(Gson gson, File dir, long accountHash)
	{
		File file = fileFor(dir, accountHash);
		if (!file.isFile())
		{
			return null;
		}
		try
		{
			return parse(gson, new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8));
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Failed to read bank snapshot {}", file, e);
			return null;
		}
	}
}

package com.travelguide.guide;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.function.BiFunction;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;
import com.travelguide.WorldPointUtil;
import com.travelguide.pathfinder.PathStep;
import com.travelguide.pathfinder.PathfinderConfig;
import com.travelguide.pathfinder.TransportAvailability;
import com.travelguide.transport.Transport;

/**
 * {@link RouteCompiler.Context} backed by the live game client. Build one per
 * compilation on the client thread; it snapshots inventory, equipment and rune pouch.
 */
public class ClientRouteContext implements RouteCompiler.Context
{
	private final BiFunction<PathStep, PathStep, Set<Transport>> edgeTransports;
	private final PathfinderConfig pathfinderConfig;
	private final ItemManager itemManager;
	private final PlaceIndex placeIndex;
	private final Map<Integer, Integer> onHand = new HashMap<>();
	private final Map<Integer, Integer> banked = new HashMap<>();
	private final boolean fairyRingsNeedStaff;

	public ClientRouteContext(
		Client client,
		ItemManager itemManager,
		PathfinderConfig pathfinderConfig,
		PlaceIndex placeIndex,
		BiFunction<PathStep, PathStep, Set<Transport>> edgeTransports)
	{
		this.edgeTransports = edgeTransports;
		this.pathfinderConfig = pathfinderConfig;
		this.itemManager = itemManager;
		this.placeIndex = placeIndex;
		this.fairyRingsNeedStaff = client.getVarbitValue(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE) != 1;
		Item[] bankItems = pathfinderConfig.bankItems();
		if (bankItems != null)
		{
			for (Item item : bankItems)
			{
				if (item != null && item.getId() >= 0 && item.getQuantity() > 0)
				{
					banked.merge(item.getId(), item.getQuantity(), Integer::sum);
				}
			}
		}
		snapshot(client);
	}

	private void snapshot(Client client)
	{
		addContainer(client.getItemContainer(InventoryID.INV));
		addContainer(client.getItemContainer(InventoryID.WORN));
		boolean hasPouch = false;
		for (int pouch : PathfinderConfig.RUNE_POUCHES)
		{
			if (onHand.containsKey(pouch))
			{
				hasPouch = true;
				break;
			}
		}
		if (hasPouch)
		{
			EnumComposition runePouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
			for (int i = 0; i < PathfinderConfig.RUNE_POUCH_RUNE_VARBITS.length; i++)
			{
				int runeEnumId = client.getVarbitValue(PathfinderConfig.RUNE_POUCH_RUNE_VARBITS[i]);
				int runeId = runeEnumId > 0 && runePouchEnum != null ? runePouchEnum.getIntValue(runeEnumId) : 0;
				int amount = client.getVarbitValue(PathfinderConfig.RUNE_POUCH_AMOUNT_VARBITS[i]);
				if (runeId > 0 && amount > 0)
				{
					onHand.merge(runeId, amount, Integer::sum);
				}
			}
		}
	}

	private void addContainer(ItemContainer container)
	{
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() >= 0 && item.getQuantity() > 0)
			{
				onHand.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
	}

	@Override
	public Set<Transport> transportsForEdge(PathStep from, PathStep to)
	{
		return edgeTransports.apply(from, to);
	}

	@Override
	public boolean usableWithoutBank(Transport transport)
	{
		TransportAvailability availability = pathfinderConfig.getTransportAvailability(false);
		if (transport.getOrigin() == WorldPointUtil.UNDEFINED)
		{
			return Arrays.asList(availability.getUsableTeleports()).contains(transport);
		}
		Transport[] atOrigin = availability.getTransportsPacked()
			.getOrDefault(transport.getOrigin(), TransportAvailability.EMPTY_TRANSPORTS);
		return Arrays.asList(atOrigin).contains(transport);
	}

	@Override
	public int onHandQuantity(int itemId)
	{
		return onHand.getOrDefault(itemId, 0);
	}

	@Override
	public int bankQuantity(int itemId)
	{
		return banked.getOrDefault(itemId, 0);
	}

	@Override
	public String itemName(int itemId)
	{
		try
		{
			return itemManager.getItemComposition(itemId).getName();
		}
		catch (Exception e)
		{
			return "item " + itemId;
		}
	}

	@Override
	public boolean fairyRingsNeedStaff()
	{
		return fairyRingsNeedStaff;
	}

	@Override
	public String bankNameAt(int packed)
	{
		return placeIndex == null ? null : placeIndex.bankNameAt(packed);
	}

	@Override
	public String nearestBankName(int packed, int maxDistance)
	{
		return placeIndex == null ? null : placeIndex.nearestBankName(packed, maxDistance);
	}
}

package com.travelguide.guide;

import java.util.Arrays;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;
import com.travelguide.WorldPointUtil;
import com.travelguide.pathfinder.PathStep;
import com.travelguide.pathfinder.PathfinderConfig;
import com.travelguide.pathfinder.TransportAvailability;
import com.travelguide.transport.Transport;
import com.travelguide.transport.TransportType;

/**
 * Which transports explain the edge between two consecutive path steps.
 * Extracted from the upstream plugin so the route compiler and its tests can share it.
 */
public final class EdgeTransports
{
	private EdgeTransports()
	{
	}

	public static Set<Transport> forEdge(PathfinderConfig pathfinderConfig, PathStep currentStep, PathStep nextStep)
	{
		if (currentStep == null || nextStep == null || pathfinderConfig == null)
		{
			return Set.of();
		}
		boolean bankVisited = currentStep.isBankVisited() || nextStep.isBankVisited();
		// Get the transports which start from the position of starting step.
		Set<Transport> stepTransports = new HashSet<>(Arrays.asList(
			pathfinderConfig.getTransportsPacked(bankVisited)
				.getOrDefault(currentStep.getPackedPosition(), TransportAvailability.EMPTY_TRANSPORTS)));
		// Add the teleports, which might be used from anywhere.
		stepTransports.addAll(Arrays.asList(pathfinderConfig.getUsableTeleports(bankVisited)));
		// Remove transports which do not target the correct location.
		stepTransports.removeIf(transport -> transport.getDestination() != nextStep.getPackedPosition());
		// Remove teleports that share destinations with a local transport type on this edge.
		// For example, if the path uses a QUETZAL (local) transport, suppress QUETZAL_WHISTLE hints.
		// Also suppress them when the edge distance is within the shared type's radius threshold,
		// which occurs when the path is simply walking to a landing site (not teleporting to it).
		Set<TransportType> localTypes = EnumSet.noneOf(TransportType.class);
		for (Transport t : stepTransports)
		{
			if (t.getOrigin() != Transport.UNDEFINED_ORIGIN && t.getType() != null)
			{
				localTypes.add(t.getType());
			}
		}
		int edgeDistance = WorldPointUtil.distanceBetween2D(currentStep.getPackedPosition(), nextStep.getPackedPosition());
		stepTransports.removeIf(t ->
		{
			if (t.getOrigin() != Transport.UNDEFINED_ORIGIN || t.getType() == null)
			{
				return false; // keep local transports
			}
			TransportType sharedType = t.getType().sharesDestinationsWith();
			if (sharedType == null)
			{
				return false; // not a shared-destination teleport, keep it
			}
			return localTypes.contains(sharedType)
				|| (sharedType.getRadiusThreshold() != null && edgeDistance <= sharedType.getRadiusThreshold());
		});
		return stepTransports;
	}
}

package com.travelguide.guide;

import java.util.Collections;
import java.util.List;
import java.util.function.IntUnaryOperator;
import lombok.Getter;
import com.travelguide.WorldPointUtil;
import com.travelguide.pathfinder.PathStep;

/**
 * The current guided route: compiled steps plus which one the player is on.
 * All methods are expected to be called from the client thread.
 */
public class GuideSession
{
	/** Ignore path points further away than this when locating the player on the path. */
	static final int MAX_SNAP_DISTANCE = 12;

	@Getter
	private String targetLabel = null;
	@Getter
	private List<PathStep> path = null;
	@Getter
	private List<RouteStep> steps = Collections.emptyList();
	@Getter
	private int currentStepIndex = 0;
	@Getter
	private int currentPathIndex = 0;
	@Getter
	private long version = 0;

	public void setTargetLabel(String label)
	{
		this.targetLabel = label;
	}

	public boolean isActive()
	{
		return !steps.isEmpty();
	}

	/** True when the given path object is the one the steps were compiled from. */
	public boolean isCompiledFrom(List<PathStep> candidate)
	{
		return path != null && path == candidate;
	}

	public void setRoute(List<PathStep> path, List<RouteStep> steps)
	{
		this.path = path;
		this.steps = steps == null ? Collections.emptyList() : steps;
		this.currentStepIndex = 0;
		this.currentPathIndex = 0;
		version++;
	}

	public void clear()
	{
		if (path == null && steps.isEmpty() && targetLabel == null)
		{
			return;
		}
		path = null;
		steps = Collections.emptyList();
		currentStepIndex = 0;
		currentPathIndex = 0;
		targetLabel = null;
		version++;
	}

	public RouteStep getCurrentStep()
	{
		return steps.isEmpty() ? null : steps.get(Math.min(currentStepIndex, steps.size() - 1));
	}

	public RouteStep getNextStep()
	{
		int i = currentStepIndex + 1;
		return i < steps.size() ? steps.get(i) : null;
	}

	/** Steps left after the current one, including the arrival. */
	public int remainingSteps()
	{
		return Math.max(0, steps.size() - currentStepIndex - 1);
	}

	/** Estimated ticks left from the current step to the end. */
	public int remainingTicks()
	{
		int total = 0;
		for (int i = currentStepIndex; i < steps.size(); i++)
		{
			total += steps.get(i).getTicks();
		}
		return total;
	}

	/** Remaining walking tiles from the current path index. */
	public int remainingTiles()
	{
		int total = 0;
		for (int i = currentStepIndex; i < steps.size(); i++)
		{
			RouteStep s = steps.get(i);
			if (!s.isWalk())
			{
				continue;
			}
			if (i == currentStepIndex)
			{
				total += Math.max(0, s.getPathIndexEnd() - Math.max(currentPathIndex, s.getPathIndexStart()));
			}
			else
			{
				total += s.getTiles();
			}
		}
		return total;
	}

	/**
	 * Re-evaluates which step is current from the player's position. Progress never moves
	 * backwards within the same compiled route; a new route resets it.
	 *
	 * @return true when the current step changed
	 */
	public boolean updatePosition(int playerPacked)
	{
		if (path == null || steps.isEmpty())
		{
			return false;
		}
		int nearest = nearestPathIndex(playerPacked);
		if (nearest < 0)
		{
			return false;
		}
		if (nearest > currentPathIndex)
		{
			currentPathIndex = nearest;
		}
		int newStep = Math.max(currentStepIndex, firstUnfinishedStep(currentPathIndex));
		if (newStep != currentStepIndex)
		{
			currentStepIndex = newStep;
			version++;
			return true;
		}
		return false;
	}

	/**
	 * Skips a bank step once the player has what it asked for.
	 */
	public boolean skipBankIfSatisfied(IntUnaryOperator onHandQuantity)
	{
		RouteStep current = getCurrentStep();
		if (current == null || !current.isBank() || current.getItems().isEmpty())
		{
			return false;
		}
		for (BankItem item : current.getItems())
		{
			if (onHandQuantity.applyAsInt(item.getItemId()) < item.getQuantity())
			{
				return false;
			}
		}
		if (currentStepIndex + 1 < steps.size())
		{
			currentStepIndex++;
			version++;
			return true;
		}
		return false;
	}

	/**
	 * The first step the player has not completed at this path index. A walk or transport
	 * is complete once the player reaches its last path index; a bank step once the player
	 * has moved past its tile; the arrival never.
	 */
	int firstUnfinishedStep(int pathIndex)
	{
		for (int k = 0; k < steps.size(); k++)
		{
			RouteStep s = steps.get(k);
			switch (s.getType())
			{
				case WALK:
				case TRANSPORT:
					if (pathIndex < s.getPathIndexEnd())
					{
						return k;
					}
					break;
				case BANK:
					if (pathIndex <= s.getPathIndexStart())
					{
						return k;
					}
					break;
				case ARRIVE:
				default:
					return k;
			}
		}
		return Math.max(0, steps.size() - 1);
	}

	/**
	 * Index of the closest path point to the player at or after the current index
	 * (earliest on ties, so a route that doubles back through the same tiles is not
	 * skipped). Returns -1 when the player is nowhere near the path.
	 */
	int nearestPathIndex(int playerPacked)
	{
		int best = -1;
		int bestDistance = MAX_SNAP_DISTANCE + 1;
		for (int i = Math.max(0, currentPathIndex); i < path.size(); i++)
		{
			int d = WorldPointUtil.distanceBetween(playerPacked, path.get(i).getPackedPosition());
			if (d < bestDistance)
			{
				bestDistance = d;
				best = i;
				if (d == 0)
				{
					break;
				}
			}
		}
		return best;
	}
}

package com.travelguide.guide;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import com.travelguide.Util;
import com.travelguide.WorldPointUtil;

/**
 * Named places from the bundled destination TSVs (banks, altars, ...). Used to label
 * walking steps ("Walk to the bank (Al Kharid)") and to offer a place search.
 */
@Slf4j
public class PlaceIndex
{
	@Value
	public static class Place
	{
		/** Category, e.g. "bank" or "altar". */
		String category;
		/** Human name, e.g. "Al Kharid". */
		String name;
		/** Packed world points belonging to this place. */
		List<Integer> points;

		public String label()
		{
			return name + " " + category;
		}

		public int firstPoint()
		{
			return points.get(0);
		}
	}

	private static final String[] RESOURCES = {
		"/destinations/game_features/bank.tsv",
		"/destinations/game_features/altar.tsv",
		"/destinations/shopping/apothecary.tsv",
	};

	private final List<Place> places;
	private final List<Place> banks;

	public PlaceIndex(List<Place> places)
	{
		this.places = Collections.unmodifiableList(new ArrayList<>(places));
		List<Place> bankList = new ArrayList<>();
		for (Place p : this.places)
		{
			if ("bank".equals(p.getCategory()))
			{
				bankList.add(p);
			}
		}
		this.banks = Collections.unmodifiableList(bankList);
	}

	public static PlaceIndex loadFromResources()
	{
		List<Place> all = new ArrayList<>();
		for (String resource : RESOURCES)
		{
			try (InputStream in = PlaceIndex.class.getResourceAsStream(resource))
			{
				if (in == null)
				{
					log.warn("Missing destination resource {}", resource);
					continue;
				}
				String category = categoryOf(resource);
				all.addAll(parse(category, new String(Util.readAllBytes(in), StandardCharsets.UTF_8)));
			}
			catch (IOException e)
			{
				log.warn("Failed to read {}", resource, e);
			}
		}
		return new PlaceIndex(all);
	}

	/** "/destinations/game_features/bank.tsv" -> "bank". */
	static String categoryOf(String resource)
	{
		String file = resource.substring(resource.lastIndexOf('/') + 1);
		int dot = file.indexOf('.');
		return dot < 0 ? file : file.substring(0, dot);
	}

	/**
	 * Parses a destination TSV with a "Destination" column and an optional "Info" column,
	 * grouping rows by name.
	 */
	static List<Place> parse(String category, String tsv)
	{
		Map<String, List<Integer>> byName = new HashMap<>();
		List<String> order = new ArrayList<>();
		int destinationColumn = -1;
		int infoColumn = -1;
		for (String line : tsv.split("\r?\n"))
		{
			if (line.isBlank())
			{
				continue;
			}
			if (line.startsWith("#"))
			{
				if (destinationColumn >= 0)
				{
					continue;
				}
				String[] headers = line.substring(1).trim().split("\t");
				for (int i = 0; i < headers.length; i++)
				{
					if ("Destination".equals(headers[i].trim()))
					{
						destinationColumn = i;
					}
					else if ("Info".equals(headers[i].trim()))
					{
						infoColumn = i;
					}
				}
				continue;
			}
			if (destinationColumn < 0)
			{
				continue;
			}
			String[] fields = line.split("\t");
			if (fields.length <= destinationColumn)
			{
				continue;
			}
			String[] xyz = fields[destinationColumn].trim().split(" ");
			if (xyz.length != 3)
			{
				continue;
			}
			int packed;
			try
			{
				packed = WorldPointUtil.packWorldPoint(
					Integer.parseInt(xyz[0]), Integer.parseInt(xyz[1]), Integer.parseInt(xyz[2]));
			}
			catch (NumberFormatException e)
			{
				continue;
			}
			String name = infoColumn >= 0 && fields.length > infoColumn ? fields[infoColumn].trim() : "";
			if (name.isEmpty())
			{
				continue;
			}
			List<Integer> pts = byName.get(name);
			if (pts == null)
			{
				pts = new ArrayList<>();
				byName.put(name, pts);
				order.add(name);
			}
			pts.add(packed);
		}
		List<Place> result = new ArrayList<>(order.size());
		for (String name : order)
		{
			result.add(new Place(category, name, Collections.unmodifiableList(byName.get(name))));
		}
		return result;
	}

	public List<Place> getPlaces()
	{
		return places;
	}

	public List<Place> getBanks()
	{
		return banks;
	}

	/**
	 * Name of the bank containing the given tile, or null.
	 */
	public String bankNameAt(int packed)
	{
		for (Place bank : banks)
		{
			if (bank.getPoints().contains(packed))
			{
				return bank.getName();
			}
		}
		return null;
	}

	/**
	 * Name of the nearest bank on the same plane within {@code maxDistance} tiles, or null.
	 * Used as a rough area label ("near Edgeville").
	 */
	public String nearestBankName(int packed, int maxDistance)
	{
		int plane = WorldPointUtil.unpackWorldPlane(packed);
		String best = null;
		int bestDistance = maxDistance + 1;
		for (Place bank : banks)
		{
			for (int p : bank.getPoints())
			{
				if (WorldPointUtil.unpackWorldPlane(p) != plane)
				{
					continue;
				}
				int d = WorldPointUtil.distanceBetween2D(packed, p);
				if (d < bestDistance)
				{
					bestDistance = d;
					best = bank.getName();
				}
			}
		}
		return best;
	}

	/**
	 * Case-insensitive substring search over "name category" labels.
	 */
	public List<Place> search(String query, int limit)
	{
		String q = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
		List<Place> out = new ArrayList<>();
		if (q.isEmpty())
		{
			return out;
		}
		for (Place p : places)
		{
			if (p.label().toLowerCase(Locale.ROOT).contains(q))
			{
				out.add(p);
				if (out.size() >= limit)
				{
					break;
				}
			}
		}
		return out;
	}
}

package com.travelguide.guide;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import com.travelguide.ItemVariations;
import com.travelguide.WorldPointUtil;
import com.travelguide.pathfinder.PathStep;
import com.travelguide.transport.Transport;
import com.travelguide.transport.TransportType;
import com.travelguide.transport.requirement.ItemRequirement;
import com.travelguide.transport.requirement.TransportItems;

/**
 * Compiles the pathfinder's tile-by-tile path into a short list of human instructions:
 * walk here, use this transport, bank for these items, arrive.
 * <p>
 * Pure logic: everything that needs the game client is behind {@link Context}.
 */
public final class RouteCompiler
{
	/** Ticks per tile when running (2 tiles per tick). */
	private static final double RUN_TILES_PER_TICK = 2.0;
	/** Rough cost of a bank visit, in ticks. */
	private static final int BANK_TICKS = 12;
	/** How far away a bank may be and still be used as an area label. */
	private static final int AREA_LABEL_DISTANCE = 60;

	public interface Context
	{
		/** The transports that explain the edge from one path step to the next (may be empty). */
		Set<Transport> transportsForEdge(PathStep from, PathStep to);

		/** Whether the player can use this transport with what they carry right now (no bank visit). */
		boolean usableWithoutBank(Transport transport);

		/** Quantity of an item in inventory, equipment or rune pouch. */
		int onHandQuantity(int itemId);

		/** Quantity of an item in the bank (0 when unknown). */
		int bankQuantity(int itemId);

		/** Display name for an item id. */
		String itemName(int itemId);

		/** True unless the Lumbridge elite diary makes fairy rings staff-free. */
		boolean fairyRingsNeedStaff();

		/** Name of the bank at this exact tile, or null. */
		String bankNameAt(int packed);

		/** Nearest bank name within the given distance, for "near X" hints, or null. */
		String nearestBankName(int packed, int maxDistance);
	}

	private RouteCompiler()
	{
	}

	/**
	 * @param path        the pathfinder's path (start tile first)
	 * @param ctx         game-facing lookups
	 * @param targetLabel what the destination is called, e.g. "Gemstone Crab" or "the marked tile"
	 * @param reached     whether the path actually reaches the target (false = closest reachable tile)
	 */
	public static List<RouteStep> compile(List<PathStep> path, Context ctx, String targetLabel, boolean reached)
	{
		List<RouteStep> steps = new ArrayList<>();
		if (path == null || path.isEmpty())
		{
			return steps;
		}
		String label = targetLabel == null || targetLabel.isBlank() ? "the destination" : targetLabel;
		int n = path.size();
		if (n == 1)
		{
			steps.add(arrive(path.get(0), 0, label, reached));
			return steps;
		}

		int walkStart = 0;
		int walkTiles = 0;
		List<Integer> bankStepIndices = new ArrayList<>();

		for (int i = 0; i < n - 1; i++)
		{
			PathStep a = path.get(i);
			PathStep b = path.get(i + 1);

			Transport transport = pickTransport(ctx.transportsForEdge(a, b));
			boolean isWalkEdge = transport == null || TransportDescriber.isMinorObstacle(transport);

			// Bank tile: the last step before the path flips into the banked state.
			if (!a.isBankVisited() && b.isBankVisited())
			{
				if (walkTiles > 0)
				{
					String bank = ctx.bankNameAt(a.getPackedPosition());
					steps.add(walk(path, walkStart, i, walkTiles, "Walk to the bank" + (bank == null ? "" : " (" + bank + ")")));
				}
				bankStepIndices.add(steps.size());
				steps.add(RouteStep.builder()
					.type(RouteStepType.BANK)
					.fromPacked(a.getPackedPosition())
					.toPacked(a.getPackedPosition())
					.pathIndexStart(i)
					.pathIndexEnd(i)
					.title("Bank")
					.detail(null)
					.ticks(BANK_TICKS)
					.items(Collections.emptyList())
					.build());
				walkStart = i;
				walkTiles = 0;
			}

			if (isWalkEdge)
			{
				walkTiles += Math.max(1, WorldPointUtil.distanceBetween2D(a.getPackedPosition(), b.getPackedPosition()));
				continue;
			}

			TransportDescriber.Description d = TransportDescriber.describe(transport);
			if (walkTiles > 0)
			{
				steps.add(walk(path, walkStart, i, walkTiles, walkTitle(d, ctx, a.getPackedPosition())));
			}
			steps.add(RouteStep.builder()
				.type(RouteStepType.TRANSPORT)
				.fromPacked(a.getPackedPosition())
				.toPacked(b.getPackedPosition())
				.pathIndexStart(i)
				.pathIndexEnd(i + 1)
				.title(d.getTitle())
				.detail(d.getDetail())
				.ticks(Math.max(1, transport.getDuration()))
				.transport(transport)
				.items(Collections.emptyList())
				.build());
			walkStart = i + 1;
			walkTiles = 0;
		}

		if (walkTiles > 0)
		{
			steps.add(walk(path, walkStart, n - 1, walkTiles, "Walk to " + label));
		}
		steps.add(arrive(path.get(n - 1), n - 1, label, reached));

		fillBankItems(steps, bankStepIndices, ctx);
		return dropEmptyBankSteps(steps);
	}

	/**
	 * The pathfinder flips into the banked state whenever the route merely crosses a bank
	 * tile, so a bank step with nothing to withdraw is noise. Remove it and merge the walks
	 * on either side back into one.
	 */
	static List<RouteStep> dropEmptyBankSteps(List<RouteStep> steps)
	{
		List<RouteStep> out = new ArrayList<>(steps.size());
		for (RouteStep step : steps)
		{
			if (step.isBank() && step.getItems().isEmpty())
			{
				continue;
			}
			RouteStep previous = out.isEmpty() ? null : out.get(out.size() - 1);
			if (step.isWalk() && previous != null && previous.isWalk()
				&& previous.getPathIndexEnd() == step.getPathIndexStart())
			{
				int tiles = previous.getTiles() + step.getTiles();
				out.set(out.size() - 1, RouteStep.builder()
					.type(RouteStepType.WALK)
					.fromPacked(previous.getFromPacked())
					.toPacked(step.getToPacked())
					.pathIndexStart(previous.getPathIndexStart())
					.pathIndexEnd(step.getPathIndexEnd())
					.title(step.getTitle())
					.detail(tiles + (tiles == 1 ? " tile" : " tiles"))
					.tiles(tiles)
					.ticks((int) Math.ceil(tiles / RUN_TILES_PER_TICK))
					.items(Collections.emptyList())
					.build());
				continue;
			}
			out.add(step);
		}
		return out;
	}

	/**
	 * Prefer a transport with a fixed origin (the thing the player walks to) over a
	 * teleport usable from anywhere, and otherwise the first one offered.
	 */
	static Transport pickTransport(Set<Transport> candidates)
	{
		if (candidates == null || candidates.isEmpty())
		{
			return null;
		}
		Transport best = null;
		for (Transport t : candidates)
		{
			if (best == null)
			{
				best = t;
				continue;
			}
			boolean bestLocal = best.getOrigin() != WorldPointUtil.UNDEFINED;
			boolean tLocal = t.getOrigin() != WorldPointUtil.UNDEFINED;
			if (tLocal && !bestLocal)
			{
				best = t;
			}
		}
		return best;
	}

	private static RouteStep walk(List<PathStep> path, int startIndex, int endIndex, int tiles, String title)
	{
		int ticks = (int) Math.ceil(tiles / RUN_TILES_PER_TICK);
		return RouteStep.builder()
			.type(RouteStepType.WALK)
			.fromPacked(path.get(startIndex).getPackedPosition())
			.toPacked(path.get(endIndex).getPackedPosition())
			.pathIndexStart(startIndex)
			.pathIndexEnd(endIndex)
			.title(title)
			.detail(tiles + (tiles == 1 ? " tile" : " tiles"))
			.tiles(tiles)
			.ticks(ticks)
			.items(Collections.emptyList())
			.build();
	}

	private static RouteStep arrive(PathStep last, int index, String label, boolean reached)
	{
		return RouteStep.builder()
			.type(RouteStepType.ARRIVE)
			.fromPacked(last.getPackedPosition())
			.toPacked(last.getPackedPosition())
			.pathIndexStart(index)
			.pathIndexEnd(index)
			.title(reached ? "Arrive at " + label : "Closest reachable point to " + label)
			.detail(reached ? null : "The destination itself could not be reached")
			.items(Collections.emptyList())
			.build();
	}

	private static String walkTitle(TransportDescriber.Description d, Context ctx, int transportOrigin)
	{
		if (d.getLandmark() == null)
		{
			return "Walk";
		}
		String title = "Walk to " + d.getLandmark();
		String near = ctx.nearestBankName(transportOrigin, AREA_LABEL_DISTANCE);
		if (near != null && !title.toLowerCase().contains(near.toLowerCase()))
		{
			title += " (near " + near + ")";
		}
		return title;
	}

	/**
	 * For every bank step, work out which items the later transports need that the player
	 * does not carry, and rewrite the step with that shopping list.
	 */
	private static void fillBankItems(List<RouteStep> steps, List<Integer> bankStepIndices, Context ctx)
	{
		for (int b = 0; b < bankStepIndices.size(); b++)
		{
			int bankIndex = bankStepIndices.get(b);
			int nextBankIndex = b + 1 < bankStepIndices.size() ? bankStepIndices.get(b + 1) : steps.size();
			Map<Integer, BankItem> wanted = new LinkedHashMap<>();
			for (int s = bankIndex + 1; s < nextBankIndex; s++)
			{
				RouteStep step = steps.get(s);
				if (!step.isTransport() || step.getTransport() == null)
				{
					continue;
				}
				Transport t = step.getTransport();
				if (ctx.usableWithoutBank(t))
				{
					continue;
				}
				for (BankItem item : missingItems(t, ctx))
				{
					BankItem existing = wanted.get(item.getItemId());
					if (existing == null || existing.getQuantity() < item.getQuantity())
					{
						wanted.put(item.getItemId(), item);
					}
				}
			}
			RouteStep old = steps.get(bankIndex);
			List<BankItem> items = new ArrayList<>(wanted.values());
			String bankName = ctx.bankNameAt(old.getFromPacked());
			String title = "Bank" + (bankName == null ? "" : " at " + bankName);
			String detail;
			if (items.isEmpty())
			{
				detail = "Withdraw what the route needs";
			}
			else
			{
				StringBuilder sb = new StringBuilder("Withdraw ");
				for (int i = 0; i < items.size(); i++)
				{
					if (i > 0)
					{
						sb.append(", ");
					}
					sb.append(items.get(i).describe());
				}
				detail = sb.toString();
			}
			steps.set(bankIndex, RouteStep.builder()
				.type(RouteStepType.BANK)
				.fromPacked(old.getFromPacked())
				.toPacked(old.getToPacked())
				.pathIndexStart(old.getPathIndexStart())
				.pathIndexEnd(old.getPathIndexEnd())
				.title(title)
				.detail(detail)
				.ticks(old.getTicks())
				.items(Collections.unmodifiableList(items))
				.build());
		}
	}

	/**
	 * Items a transport needs that are not on hand: for each requirement, the first
	 * alternative found in the bank (or the first alternative at all when the bank is unknown).
	 */
	static List<BankItem> missingItems(Transport t, Context ctx)
	{
		List<BankItem> out = new ArrayList<>();
		if (t.getType() == TransportType.FAIRY_RING && ctx.fairyRingsNeedStaff())
		{
			int[] staves = ItemVariations.DRAMEN_STAFF.getIds();
			if (!anyOnHand(staves, 1, ctx))
			{
				out.add(pick(staves, 1, ctx));
			}
		}
		TransportItems items = t.getItemRequirements();
		if (items == null)
		{
			return out;
		}
		for (ItemRequirement req : items.getRequirements())
		{
			int quantity = req.getQuantity();
			if (quantity <= 0)
			{
				continue;
			}
			if (anyOnHand(req.getItemIds(), quantity, ctx)
				|| anyOnHand(req.getStaffIds(), 1, ctx)
				|| anyOnHand(req.getOffhandIds(), 1, ctx))
			{
				continue;
			}
			BankItem choice = pickFromBank(req.getItemIds(), quantity, ctx);
			if (choice == null)
			{
				choice = pickFromBank(req.getStaffIds(), 1, ctx);
			}
			if (choice == null)
			{
				choice = pickFromBank(req.getOffhandIds(), 1, ctx);
			}
			if (choice == null && req.getItemIds() != null && req.getItemIds().length > 0)
			{
				choice = new BankItem(req.getItemIds()[0], quantity, ctx.itemName(req.getItemIds()[0]));
			}
			if (choice != null)
			{
				out.add(choice);
			}
		}
		return out;
	}

	private static boolean anyOnHand(int[] ids, int quantity, Context ctx)
	{
		if (ids == null)
		{
			return false;
		}
		for (int id : ids)
		{
			if (ctx.onHandQuantity(id) >= quantity)
			{
				return true;
			}
		}
		return false;
	}

	private static BankItem pickFromBank(int[] ids, int quantity, Context ctx)
	{
		if (ids == null)
		{
			return null;
		}
		for (int id : ids)
		{
			if (ctx.bankQuantity(id) >= quantity)
			{
				return new BankItem(id, quantity, ctx.itemName(id));
			}
		}
		return null;
	}

	private static BankItem pick(int[] ids, int quantity, Context ctx)
	{
		BankItem fromBank = pickFromBank(ids, quantity, ctx);
		return fromBank != null ? fromBank : new BankItem(ids[0], quantity, ctx.itemName(ids[0]));
	}
}

package com.travelguide.guide;

import java.util.List;
import lombok.Builder;
import lombok.Value;
import com.travelguide.transport.Transport;

/**
 * One human-readable instruction compiled from a stretch of the tile path.
 * <p>
 * {@code pathIndexStart} is the index in the pathfinder's step list where this
 * instruction begins; the step is considered current while the player's nearest
 * path index is in {@code [pathIndexStart, nextStep.pathIndexStart)}.
 */
@Value
@Builder
public class RouteStep
{
	RouteStepType type;
	/** Packed world point where the step begins. */
	int fromPacked;
	/** Packed world point where the step ends (the transport destination, the bank tile, the target). */
	int toPacked;
	int pathIndexStart;
	int pathIndexEnd;
	/** Short imperative, e.g. "Use fairy ring". */
	String title;
	/** Optional second line, e.g. "Dial AIQ" or "42 tiles". */
	String detail;
	/** Tiles walked in this step (WALK only). */
	int tiles;
	/** Rough duration in game ticks. */
	int ticks;
	/** The transport used (TRANSPORT only). */
	Transport transport;
	/** Items to withdraw (BANK only). */
	List<BankItem> items;

	public boolean isWalk()
	{
		return type == RouteStepType.WALK;
	}

	public boolean isTransport()
	{
		return type == RouteStepType.TRANSPORT;
	}

	public boolean isBank()
	{
		return type == RouteStepType.BANK;
	}

	public boolean isArrive()
	{
		return type == RouteStepType.ARRIVE;
	}

	/** Title and detail on one line, for compact display. */
	public String summary()
	{
		return detail == null || detail.isEmpty() ? title : title + " - " + detail;
	}
}

package com.travelguide.guide;

/**
 * The kind of instruction a {@link RouteStep} represents.
 */
public enum RouteStepType
{
	/** Walk (or run) along the path to the next point of interest. */
	WALK,
	/** Use a transport: fairy ring, boat, teleport spell, agility shortcut, ... */
	TRANSPORT,
	/** Visit a bank and withdraw the items the rest of the route needs. */
	BANK,
	/** The destination. */
	ARRIVE
}

package com.travelguide.guide;

import lombok.Value;
import com.travelguide.WorldPointUtil;
import com.travelguide.transport.Transport;
import com.travelguide.transport.TransportType;

/**
 * Turns a {@link Transport} into words: what to do, where it goes, and what the
 * player is walking towards before using it.
 */
public final class TransportDescriber
{
	@Value
	public static class Description
	{
		/** Imperative, e.g. "Use fairy ring". */
		String title;
		/** Optional qualifier, e.g. "Dial AIQ". */
		String detail;
		/** What the preceding walk heads for, e.g. "the fairy ring"; null for teleports usable anywhere. */
		String landmark;
	}

	private TransportDescriber()
	{
	}

	public static Description describe(Transport t)
	{
		TransportType type = t.getType();
		String[] menu = splitObjectInfo(t.getObjectInfo());
		String option = menu[0];
		String target = menu[1];
		String info = emptyToNull(t.getDisplayInfo());
		boolean anywhere = t.getOrigin() == WorldPointUtil.UNDEFINED;

		if (type == null)
		{
			return new Description(joinMenu(option, target, "Use transport"), info, target);
		}

		switch (type)
		{
			case FAIRY_RING:
				return new Description("Use fairy ring", info == null ? null : "Dial " + fairyCode(info), "the fairy ring");
			case SPIRIT_TREE:
				return new Description("Use spirit tree", info == null ? null : "Travel to " + info, "the spirit tree");
			case GNOME_GLIDER:
				return new Description("Take gnome glider", info == null ? null : "Fly to " + info, "the gnome glider");
			case HOT_AIR_BALLOON:
				return new Description("Take hot air balloon", info == null ? null : "Fly to " + info, "the hot air balloon");
			case MAGIC_CARPET:
				return new Description(joinMenu(option, target, "Take magic carpet"), info == null ? null : "Ride to " + info, nvl(target, "the rug merchant"));
			case MAGIC_MUSHTREE:
				return new Description("Use magic mushtree", info == null ? null : "Travel to " + info, "the mushtree");
			case MINECART:
				return new Description(joinMenu(option, target, "Take minecart"), info == null ? null : "Ride to " + info, nvl(target, "the minecart"));
			case QUETZAL:
				return new Description(joinMenu(option, target, "Take quetzal"), info == null ? null : "Fly to " + info, nvl(target, "the quetzal"));
			case QUETZAL_WHISTLE:
				return new Description("Use quetzal whistle", info == null ? null : "Fly to " + info, null);
			case CANOE:
				return new Description(joinMenu(option, target, "Take canoe"), info == null ? null : "Paddle to " + info, nvl(target, "the canoe station"));
			case CHARTER_SHIP:
				return new Description(joinMenu(option, target, "Charter a ship"), info == null ? null : "Sail to " + info, nvl(target, "the charter crew"));
			case SHIP:
			case BOAT:
				return new Description(joinMenu(option, target, "Take the boat"), info == null ? null : "Sail to " + info, nvl(target, "the boat"));
			case TELEPORTATION_SPELL:
			case TELEPORTATION_SPELL_HOME:
				return new Description("Cast " + nvl(info, "teleport"), null, anywhere ? null : nvl(target, null));
			case TELEPORTATION_ITEM:
			case SEASONAL_TRANSPORTS:
			{
				String[] parts = splitItemInfo(info);
				return new Description("Use " + nvl(parts[0], "teleport item"), parts[1] == null ? null : "Teleport to " + parts[1], anywhere ? null : nvl(target, null));
			}
			case TELEPORTATION_LEVER:
				return new Description("Pull the lever", info == null ? null : "Teleport to " + info, "the lever");
			case TELEPORTATION_PORTAL:
				return new Description(joinMenu(option, target, "Enter the portal"), info == null ? null : "Teleport to " + info, nvl(target, "the portal"));
			case TELEPORTATION_PORTAL_POH:
				return new Description("Use the portal nexus", info == null ? null : "Teleport to " + info, "the portal nexus");
			case TELEPORTATION_BOX:
				return new Description(joinMenu(option, target, "Use jewellery box"), info == null ? null : "Teleport to " + info, nvl(target, "the jewellery box"));
			case TELEPORTATION_MINIGAME:
				return new Description("Use minigame teleport", info == null ? null : "Teleport to " + info, null);
			case WILDERNESS_OBELISK:
				return new Description("Use the obelisk", info == null ? null : "Teleport to " + info, "the obelisk");
			case AGILITY_SHORTCUT:
				return new Description(joinMenu(option, target, "Use agility shortcut"), "Agility shortcut", nvl(target, "the shortcut"));
			case GRAPPLE_SHORTCUT:
				return new Description(joinMenu(option, target, "Use grapple shortcut"), "Grapple shortcut", nvl(target, "the shortcut"));
			case TRANSPORT:
			default:
				return new Description(joinMenu(option, target, "Use transport"), info, nvl(target, null));
		}
	}

	/**
	 * Whether a transport is a minor obstacle (door, gate, stile on the same plane, a
	 * tile or two apart) that should be folded into the surrounding walk rather than
	 * shown as its own step.
	 */
	public static boolean isMinorObstacle(Transport t)
	{
		if (t.getType() != TransportType.TRANSPORT)
		{
			return false;
		}
		int origin = t.getOrigin();
		int dest = t.getDestination();
		if (origin == WorldPointUtil.UNDEFINED || dest == WorldPointUtil.UNDEFINED)
		{
			return false;
		}
		if (WorldPointUtil.unpackWorldPlane(origin) != WorldPointUtil.unpackWorldPlane(dest))
		{
			return false;
		}
		return WorldPointUtil.distanceBetween2D(origin, dest) <= 2;
	}

	/**
	 * Splits "menuOption menuTarget objectID" into {option, target}; either may be null.
	 */
	static String[] splitObjectInfo(String objectInfo)
	{
		if (objectInfo == null || objectInfo.isBlank())
		{
			return new String[]{null, null};
		}
		String s = objectInfo.trim();
		// Drop the trailing numeric object/NPC id if present.
		int lastSpace = s.lastIndexOf(' ');
		if (lastSpace > 0 && s.substring(lastSpace + 1).chars().allMatch(Character::isDigit))
		{
			s = s.substring(0, lastSpace).trim();
		}
		int firstSpace = s.indexOf(' ');
		if (firstSpace < 0)
		{
			return new String[]{s, null};
		}
		return new String[]{s.substring(0, firstSpace), s.substring(firstSpace + 1).trim()};
	}

	/** "Ardougne cloak: Ardougne Farm" -> {"Ardougne cloak", "Ardougne Farm"}. */
	static String[] splitItemInfo(String info)
	{
		if (info == null)
		{
			return new String[]{null, null};
		}
		int colon = info.indexOf(':');
		if (colon < 0)
		{
			return new String[]{info.trim(), null};
		}
		return new String[]{info.substring(0, colon).trim(), emptyToNull(info.substring(colon + 1).trim())};
	}

	/** "A I Q" -> "AIQ"; "A I R - D L R" -> "AIR / DLR"; "ZANARIS" -> "Zanaris". */
	static String fairyCode(String info)
	{
		String[] alternatives = info.split("-");
		StringBuilder sb = new StringBuilder();
		for (String alt : alternatives)
		{
			String code = alt.trim();
			String compact = code.replace(" ", "");
			if (sb.length() > 0)
			{
				sb.append(" / ");
			}
			if (compact.length() == 3 && compact.chars().allMatch(Character::isUpperCase))
			{
				sb.append(compact);
			}
			else
			{
				sb.append(titleCase(code));
			}
		}
		return sb.toString();
	}

	private static String titleCase(String s)
	{
		if (s.isEmpty())
		{
			return s;
		}
		return s.charAt(0) + s.substring(1).toLowerCase();
	}

	private static String joinMenu(String option, String target, String fallback)
	{
		if (option == null)
		{
			return fallback;
		}
		return target == null ? option : option + " " + target;
	}

	private static String nvl(String value, String fallback)
	{
		return value == null || value.isEmpty() ? fallback : value;
	}

	private static String emptyToNull(String s)
	{
		return s == null || s.isBlank() ? null : s.trim();
	}
}

package com.travelguide.leagues;

import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.WorldType;

/**
 * Snapshot of the player's Demonic Pacts League state, refreshed once per
 * {@code PathfinderConfig.refresh()} cycle (i.e. on world change, login, or
 * any config-driven recompute).
 *
 * <p>
 * The Pathfinder asks two questions of this object on the hot path:
 * </p>
 * <ul>
 *   <li>{@link #isSeasonal()} — is the player currently on a Leagues world?
 *       When false, all league-specific filtering is bypassed.</li>
 *   <li>{@link #isUnlocked(LeagueRegion)} — has the player unlocked the
 *       supplied region? Always-unlocked regions
 *       ({@link LeagueRegion#isAlwaysUnlocked()}) return {@code true}
 *       regardless of seasonal status; always-blocked regions
 *       ({@link LeagueRegion#isAlwaysBlocked()}) always return {@code false}
 *       when seasonal.</li>
 * </ul>
 *
 * <p>
 * The unlock set is rebuilt from the {@code LEAGUE_AREA_SELECTION_*} varbit
 * slots ({@link #AREA_SELECTION_VARBITS}). Each slot stores a numeric area
 * id matching the wiki's enumeration (mapping defined in
 * {@link #AREA_VARBIT_TO_REGION}):
 * </p>
 * <ul>
 *   <li>Slot 0 ({@code 10662}) — pre-set to Varlamore on a seasonal world.</li>
 *   <li>Slot 1 ({@code 10663}) — Karamja, awarded for free with the player's
 *       first paid pick at 80 tasks.</li>
 *   <li>Slots 2-3 ({@code 10664}/{@code 10665}) — the player's three area
 *       picks at 200/300/450 tasks.</li>
 *   <li>Slots 4-5 ({@code 10666}/{@code 10667}) — reserved by the game for
 *       additional bonus unlocks; we read them defensively.</li>
 * </ul>
 *
 * <p>
 * The mapping is deliberately hard-coded here — these IDs are known not to
 * change during a league season.
 * </p>
 */
public class LeagueModeState
{
	/**
	 * Varbit IDs storing the league area unlocks. The values match
	 * {@code LEAGUE_AREA_SELECTION_0..5} from RuneLite's gameval VarbitID
	 * table. Slot 0 is the auto-set Varlamore slot, slot 1 is the Karamja
	 * free pick, and the remaining slots correspond to the three player
	 * picks at 200/300/450 tasks plus two bonus slots reserved by the game.
	 */
	static final int[] AREA_SELECTION_VARBITS = {
		10662, 10663, 10664, 10665, 10666, 10667,
	};

	/**
	 * Maps the numeric area id stored in a {@code LEAGUE_AREA_SELECTION_*}
	 * varbit to its {@link LeagueRegion}. Numbering was found through trial
	 * and error (id 1 = Misthalin is included for completeness even though
	 * it is never selectable).
	 */
	private static final Map<Integer, LeagueRegion> AREA_VARBIT_TO_REGION;

	static
	{
		AREA_VARBIT_TO_REGION = Map.ofEntries(
			Map.entry(1, LeagueRegion.MISTHALIN),
			Map.entry(2, LeagueRegion.KARAMJA),
			Map.entry(3, LeagueRegion.ASGARNIA),
			Map.entry(4, LeagueRegion.KANDARIN),
			Map.entry(5, LeagueRegion.MORYTANIA),
			Map.entry(6, LeagueRegion.DESERT),
			Map.entry(7, LeagueRegion.TIRANNWN),
			Map.entry(8, LeagueRegion.FREMENNIK),
			Map.entry(11, LeagueRegion.WILDERNESS),
			Map.entry(20, LeagueRegion.KOUREND),
			Map.entry(21, LeagueRegion.VARLAMORE));
	}

	@Getter
	private boolean seasonal;

	private Set<LeagueRegion> unlockedRegions = EnumSet.noneOf(LeagueRegion.class);

	/**
	 * Re-reads {@link Client#getWorldType()} and the area-unlock varbits.
	 * Called from {@code PathfinderConfig.refresh()} which already runs on
	 * world change, login, and config edits.
	 *
	 * <p>
	 * Off the game thread (or on a {@code null} client) this resets to a
	 * non-seasonal state with no extra unlocks; this is the safe default
	 * because non-seasonal logic mirrors normal pathfinding.
	 * </p>
	 */
	public void refresh(Client client)
	{
		if (client == null)
		{
			seasonal = false;
			unlockedRegions = EnumSet.noneOf(LeagueRegion.class);
			return;
		}
		EnumSet<WorldType> worldTypes = client.getWorldType();
		seasonal = worldTypes != null && worldTypes.contains(WorldType.SEASONAL);

		EnumSet<LeagueRegion> next = EnumSet.noneOf(LeagueRegion.class);
		if (seasonal)
		{
			for (int varbitId : AREA_SELECTION_VARBITS)
			{
				addRegionFromSlot(client, varbitId, next);
			}
		}
		unlockedRegions = next;
	}

	/**
	 * Whether the supplied region is currently traversable. Outside of
	 * seasonal mode every region is considered unlocked.
	 */
	public boolean isUnlocked(LeagueRegion region)
	{
		if (region == null)
		{
			return true;
		}
		if (region.isAlwaysUnlocked())
		{
			return true;
		}
		if (!seasonal)
		{
			return true;
		}
		if (region.isAlwaysBlocked())
		{
			return false;
		}
		return unlockedRegions.contains(region);
	}

	/**
	 * Whether the supplied tile is in the always-blocked region while the
	 * player is on a seasonal world. Returns {@code false} on non-seasonal
	 * worlds so normal pathfinding is unaffected.
	 */
	public boolean isInBlockedRegion(int packedPoint)
	{
		if (!seasonal)
		{
			return false;
		}
		return LeagueRegionChecker.getRegion(packedPoint).isAlwaysBlocked();
	}

	/**
	 * Test hook: forces the seasonal flag and unlock set without touching
	 * the client.
	 */
	public void setForTest(boolean seasonal, Set<LeagueRegion> unlocked)
	{
		this.seasonal = seasonal;
		this.unlockedRegions = unlocked == null
			? EnumSet.noneOf(LeagueRegion.class)
			: EnumSet.copyOf(unlocked);
	}

	private static void addRegionFromSlot(Client client, int varbitId, Set<LeagueRegion> out)
	{
		int value = client.getVarbitValue(varbitId);
		if (value <= 0)
		{
			return;
		}
		LeagueRegion region = AREA_VARBIT_TO_REGION.get(value);
		if (region != null)
		{
			out.add(region);
		}
	}
}

package com.travelguide.leagues;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

import lombok.extern.slf4j.Slf4j;
import com.travelguide.TravelGuidePlugin;
import com.travelguide.Util;
import com.travelguide.WorldPointUtil;

/**
 * Resolves a packed world point to its {@link LeagueRegion} for the Demonic
 * Pacts League.
 *
 * <p>
 * Mirrors the static-utility shape of
 * {@link com.travelguide.pathfinder.WildernessChecker}. The mapping is keyed by
 * OSRS map region id (a 64x64-tile chunk identifier matching
 * {@code WorldPoint.getRegionID()}: {@code (x >> 6) << 8 | (y >> 6)}) and
 * loaded from {@code /leagues/regions.tsv} on first access.
 * </p>
 *
 * <p>
 * Tiles whose region id is absent from the mapping fall back to
 * {@link LeagueRegion#NEUTRAL}. This is deliberate: it covers instances and
 * dynamic regions (POH, raids, dungeon entrances) which are universally
 * accessible during the league regardless of unlocked areas.
 * </p>
 */
@Slf4j
public class LeagueRegionChecker
{
	private static final String RESOURCE_PATH = "/leagues/regions.tsv";

	private static volatile Map<Integer, LeagueRegion> regionsById;

	private LeagueRegionChecker()
	{
	}

	/**
	 * Returns the league region containing the supplied packed world point.
	 * Never returns {@code null}; unmapped tiles resolve to
	 * {@link LeagueRegion#NEUTRAL}.
	 */
	public static LeagueRegion getRegion(int packedPoint)
	{
		final int x = WorldPointUtil.unpackWorldX(packedPoint);
		final int y = WorldPointUtil.unpackWorldY(packedPoint);
		final int regionId = ((x >> 6) << 8) | (y >> 6);
		return regions().getOrDefault(regionId, LeagueRegion.NEUTRAL);
	}

	/**
	 * Convenience predicate for the always-blocked region.
	 */
	public static boolean isInMisthalin(int packedPoint)
	{
		return getRegion(packedPoint) == LeagueRegion.MISTHALIN;
	}

	/**
	 * Returns the underlying region-id-to-region map. Lazily initialised on
	 * first call. Visible to tests via {@link #reload(String)}.
	 */
	private static Map<Integer, LeagueRegion> regions()
	{
		Map<Integer, LeagueRegion> snapshot = regionsById;
		if (snapshot == null)
		{
			synchronized (LeagueRegionChecker.class)
			{
				snapshot = regionsById;
				if (snapshot == null)
				{
					snapshot = loadFromResource();
					regionsById = snapshot;
				}
			}
		}
		return snapshot;
	}

	/**
	 * Replaces the in-memory mapping with a parsed copy of the supplied
	 * TSV body. Intended for tests. Pass {@code null} to clear the cache so
	 * the next call re-loads from the resource file.
	 */
	static synchronized void reload(String tsv)
	{
		if (tsv == null)
		{
			regionsById = null;
			return;
		}
		regionsById = parse(tsv);
	}

	private static Map<Integer, LeagueRegion> loadFromResource()
	{
		try (InputStream in = TravelGuidePlugin.class.getResourceAsStream(RESOURCE_PATH))
		{
			if (in == null)
			{
				log.warn("League regions resource not found at {}; defaulting all tiles to NEUTRAL", RESOURCE_PATH);
				return new HashMap<>();
			}
			String body = new String(Util.readAllBytes(Objects.requireNonNull(in)), StandardCharsets.UTF_8);
			return parse(body);
		}
		catch (IOException e)
		{
			log.error("Failed to load league regions from {}", RESOURCE_PATH, e);
			return new HashMap<>();
		}
	}

	private static Map<Integer, LeagueRegion> parse(String tsv)
	{
		Map<Integer, LeagueRegion> result = new HashMap<>();
		if (tsv == null || tsv.isEmpty())
		{
			return result;
		}
		int lineNumber = 0;
		for (String rawLine : tsv.split("\\R"))
		{
			lineNumber++;
			String line = rawLine.trim();
			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}
			String[] parts = line.split("\\s+", 2);
			if (parts.length != 2)
			{
				log.warn("Skipping malformed league regions row {}: '{}'", lineNumber, rawLine);
				continue;
			}
			final int regionId;
			try
			{
				regionId = Integer.parseInt(parts[0]);
			}
			catch (NumberFormatException e)
			{
				log.warn("Skipping league regions row {} with non-numeric region id '{}'", lineNumber, parts[0]);
				continue;
			}
			final LeagueRegion region;
			try
			{
				region = LeagueRegion.valueOf(parts[1]);
			}
			catch (IllegalArgumentException e)
			{
				log.warn("Skipping league regions row {} with unknown region '{}'", lineNumber, parts[1]);
				continue;
			}
			result.put(regionId, region);
		}
		return result;
	}
}

package com.travelguide.npc;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.zip.GZIPInputStream;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import com.travelguide.WorldPointUtil;

/**
 * NPC and monster spawn locations generated from the OSRS Wiki
 * (tools/generate-npcs.mjs). Read-only after construction.
 */
@Slf4j
public class NpcIndex
{
	private static final String RESOURCE = "npcs.json.gz";

	@Value
	public static class Npc
	{
		String name;
		String page;
		int[] ids;
		boolean members;
		/** Combat level for monsters, null for other NPCs. */
		Integer combat;
		/** Free-text location from the wiki, may be null. */
		String location;
		boolean monster;
		/** Packed world points of known spawns; never empty. */
		int[] spawns;

		public String label()
		{
			return page.equals(name) ? name : page;
		}

		public String subLabel()
		{
			StringBuilder sb = new StringBuilder(monster ? "Monster" : "NPC");
			if (combat != null && combat > 0)
			{
				sb.append(" lvl ").append(combat);
			}
			if (location != null && !location.isEmpty())
			{
				sb.append(" - ").append(location);
			}
			if (spawns.length > 1)
			{
				sb.append(" (").append(spawns.length).append(" spawns)");
			}
			return sb.toString();
		}
	}

	/** Wire format written by the generator. */
	private static class Dto
	{
		String generatedAt;
		String source;
		int count;
		List<NpcDto> npcs;
	}

	private static class NpcDto
	{
		String n;
		String p;
		int[] i;
		boolean m;
		Integer c;
		String l;
		@SerializedName("mo")
		Boolean monster;
		/** [x, y, plane] triples; doubles so a stray half-tile coordinate cannot break loading. */
		double[][] s;
	}

	private final List<Npc> npcs;
	private final String generatedAt;

	public NpcIndex(List<Npc> npcs, String generatedAt)
	{
		this.npcs = Collections.unmodifiableList(new ArrayList<>(npcs));
		this.generatedAt = generatedAt;
	}

	public static NpcIndex empty()
	{
		return new NpcIndex(Collections.emptyList(), null);
	}

	public static NpcIndex loadFromResources(Gson gson)
	{
		try (InputStream in = NpcIndex.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.warn("NPC data resource {} missing", RESOURCE);
				return empty();
			}
			try (Reader reader = new InputStreamReader(new GZIPInputStream(in), StandardCharsets.UTF_8))
			{
				return fromJson(gson, reader);
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Failed to load NPC data", e);
			return empty();
		}
	}

	static NpcIndex fromJson(Gson gson, Reader reader)
	{
		Dto dto = gson.fromJson(reader, Dto.class);
		List<Npc> out = new ArrayList<>(dto == null || dto.npcs == null ? 0 : dto.npcs.size());
		if (dto != null && dto.npcs != null)
		{
			for (NpcDto d : dto.npcs)
			{
				if (d == null || d.s == null || d.s.length == 0 || d.n == null)
				{
					continue;
				}
				int[] spawns = new int[d.s.length];
				int count = 0;
				for (double[] xyz : d.s)
				{
					if (xyz == null || xyz.length < 2)
					{
						continue;
					}
					int x = (int) Math.round(xyz[0]);
					int y = (int) Math.round(xyz[1]);
					int plane = xyz.length > 2 ? (int) Math.round(xyz[2]) : 0;
					if (x <= 0 || y <= 0 || plane < 0 || plane > 3)
					{
						continue;
					}
					spawns[count++] = WorldPointUtil.packWorldPoint(x, y, plane);
				}
				if (count == 0)
				{
					continue;
				}
				if (count < spawns.length)
				{
					int[] trimmed = new int[count];
					System.arraycopy(spawns, 0, trimmed, 0, count);
					spawns = trimmed;
				}
				out.add(new Npc(
					d.n,
					d.p == null ? d.n : d.p,
					d.i == null ? new int[0] : d.i,
					d.m,
					d.c,
					d.l,
					d.monster != null && d.monster,
					spawns));
			}
		}
		return new NpcIndex(out, dto == null ? null : dto.generatedAt);
	}

	public List<Npc> getNpcs()
	{
		return npcs;
	}

	public String getGeneratedAt()
	{
		return generatedAt;
	}

	public int size()
	{
		return npcs.size();
	}

	/**
	 * Case-insensitive search: names starting with the query first, then names or pages
	 * containing it, each group alphabetical (shorter names first on ties).
	 */
	public List<Npc> search(String query, int limit)
	{
		List<Npc> out = new ArrayList<>();
		String q = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
		if (q.isEmpty() || limit <= 0)
		{
			return out;
		}
		List<Npc> prefix = new ArrayList<>();
		List<Npc> contains = new ArrayList<>();
		for (Npc npc : npcs)
		{
			String name = npc.getName().toLowerCase(Locale.ROOT);
			if (name.startsWith(q))
			{
				prefix.add(npc);
			}
			else if (name.contains(q) || npc.getPage().toLowerCase(Locale.ROOT).contains(q))
			{
				contains.add(npc);
			}
		}
		prefix.sort((a, b) -> a.getName().length() != b.getName().length()
			? Integer.compare(a.getName().length(), b.getName().length())
			: a.getPage().compareToIgnoreCase(b.getPage()));
		contains.sort((a, b) -> a.getPage().compareToIgnoreCase(b.getPage()));
		for (Npc npc : prefix)
		{
			if (out.size() >= limit)
			{
				return out;
			}
			out.add(npc);
		}
		for (Npc npc : contains)
		{
			if (out.size() >= limit)
			{
				return out;
			}
			out.add(npc);
		}
		return out;
	}

	/** Exact (case-insensitive) match on name or page title, or null. */
	public Npc find(String nameOrPage)
	{
		if (nameOrPage == null)
		{
			return null;
		}
		for (Npc npc : npcs)
		{
			if (npc.getPage().equalsIgnoreCase(nameOrPage))
			{
				return npc;
			}
		}
		for (Npc npc : npcs)
		{
			if (npc.getName().equalsIgnoreCase(nameOrPage))
			{
				return npc;
			}
		}
		return null;
	}
}

package com.travelguide.pathfinder;

public enum AbstractNodeKind
{
	// These four abstract teleport states mirror the wilderness buckets that change
	// which teleports are legal.
	GLOBAL_TELEPORTS_OVER_30,
	GLOBAL_TELEPORTS_OVER_20,
	GLOBAL_TELEPORTS_OVER_0,
	GLOBAL_TELEPORTS_NORMAL;

	public static AbstractNodeKind fromWildernessLevel(int wildernessLevel)
	{
		if (wildernessLevel > 30)
		{
			return GLOBAL_TELEPORTS_OVER_30;
		}
		if (wildernessLevel > 20)
		{
			return GLOBAL_TELEPORTS_OVER_20;
		}
		if (wildernessLevel > 0)
		{
			return GLOBAL_TELEPORTS_OVER_0;
		}
		return GLOBAL_TELEPORTS_NORMAL;
	}

	public int maxWildernessLevel()
	{
		switch (this)
		{
			case GLOBAL_TELEPORTS_OVER_30:
				return 31;
			case GLOBAL_TELEPORTS_OVER_20:
				return 30;
			case GLOBAL_TELEPORTS_OVER_0:
				return 20;
			case GLOBAL_TELEPORTS_NORMAL:
			default:
				return 0;
		}
	}
}

package com.travelguide.pathfinder;

import com.travelguide.PrimitiveIntList;
import com.travelguide.WorldPointUtil;
import com.travelguide.transport.Transport;

public class CollisionMap
{
	// Enum.values() makes copies every time which hurts performance in the hotpath
	private static final OrdinalDirection[] ORDINAL_VALUES = OrdinalDirection.values();

	private final SplitFlagMap collisionData;
	// This is only safe if pathfinding is single-threaded. Holds the ids of the neighbour nodes
	// appended to the NodeGraph during the most recent getNeighbors call.
	private final PrimitiveIntList neighbors = new PrimitiveIntList(16);
	private final boolean[] traversable = new boolean[8];

	public CollisionMap(SplitFlagMap collisionData)
	{
		this.collisionData = collisionData;
	}

	private static int packedPointFromOrdinal(int startPacked, OrdinalDirection direction)
	{
		final int x = WorldPointUtil.unpackWorldX(startPacked);
		final int y = WorldPointUtil.unpackWorldY(startPacked);
		final int plane = WorldPointUtil.unpackWorldPlane(startPacked);
		return WorldPointUtil.packWorldPoint(x + direction.x, y + direction.y, plane);
	}

	public byte getRegionPlaneCounts(int regionIndex)
	{
		return collisionData.getRegionPlaneCounts(regionIndex);
	}

	private boolean get(int x, int y, int z, int flag)
	{
		return collisionData.get(x, y, z, flag);
	}

	public boolean n(int x, int y, int z)
	{
		return get(x, y, z, 0);
	}

	public boolean s(int x, int y, int z)
	{
		return n(x, y - 1, z);
	}

	public boolean e(int x, int y, int z)
	{
		return get(x, y, z, 1);
	}

	public boolean w(int x, int y, int z)
	{
		return e(x - 1, y, z);
	}

	private boolean ne(int x, int y, int z)
	{
		return n(x, y, z) && e(x, y + 1, z) && e(x, y, z) && n(x + 1, y, z);
	}

	private boolean nw(int x, int y, int z)
	{
		return n(x, y, z) && w(x, y + 1, z) && w(x, y, z) && n(x - 1, y, z);
	}

	private boolean se(int x, int y, int z)
	{
		return s(x, y, z) && e(x, y - 1, z) && e(x, y, z) && s(x + 1, y, z);
	}

	private boolean sw(int x, int y, int z)
	{
		return s(x, y, z) && w(x, y - 1, z) && w(x, y, z) && s(x - 1, y, z);
	}

	public boolean isBlocked(int x, int y, int z)
	{
		return !n(x, y, z) && !s(x, y, z) && !e(x, y, z) && !w(x, y, z);
	}

	public PrimitiveIntList getNeighbors(int node, VisitedTiles visited, PathfinderConfig config, int wildernessLevel, boolean targetInWilderness, NodeGraph graph)
	{
		if (graph.isTile(node))
		{
			return getTileNeighbors(node, visited, config, wildernessLevel, graph);
		}
		else
		{
			return getAbstractNodeNeighbors(node, visited, config, targetInWilderness, graph);
		}
	}

	// Get neighbours for a walkable tile:
	//      * Neighbouring tiles we can walk to
	//      * A transition into banked state, if the current tile is a bank.
	//      * Transition into abstract global teleport nodes, if we haven't tried that yet.
	private PrimitiveIntList getTileNeighbors(int node, VisitedTiles visited, PathfinderConfig config, int wildernessLevel, NodeGraph graph)
	{
		final int packedPosition = graph.packedPosition(node);
		final int x = WorldPointUtil.unpackWorldX(packedPosition);
		final int y = WorldPointUtil.unpackWorldY(packedPosition);
		final int z = WorldPointUtil.unpackWorldPlane(packedPosition);

		neighbors.clear();

		// Either we have already visited a bank, if the current tile is a bank switch into the bankVisited state for the
		// rest of the path.
		boolean pathBankVisited = graph.bankVisited(node)
			|| (config.isBankPathEnabled() && config.bankAccessible(packedPosition));

		// Firstly check if there are any transports or teleports which are applicable from the current tile.
		Transport[] transports = config.getTransportsPacked(pathBankVisited).getOrDefault(packedPosition, TransportAvailability.EMPTY_TRANSPORTS);
		// If this tile was itself reached via a delayed-visit teleport (e.g. QUETZAL_WHISTLE), propagate its
		// differential cost to any competing delayed-visit transports emitted from here. This prevents the
		// pathfinder from choosing a chain (e.g. whistle → landing site A → fly to B) over a direct teleport
		// to B, because the chain inherits the teleport's penalty and is therefore always more expensive.
		int inheritedDifferential = (graph.isTransport(node) && graph.isDelayedVisit(node))
			? graph.differentialCost(node)
			: 0;
		for (Transport transport : transports)
		{
			boolean delayedVisit = transport.getType().sharesDestinationsWith() != null;
			// Do not consider a transport if we have already visited its target tile.
			// For transports that share destinations with a teleport, skip this check
			// so both can compete in the priority queue (delayed visit).
			if (!delayedVisit && visited.get(transport.getDestination(), pathBankVisited))
			{
				continue;
			}
			// Inherit the parent teleport's differential as a real cost on chained shared-destination transports,
			// so that chaining (e.g. fly to landing site A then use station to B) is always more expensive than
			// a direct teleport to B.
			int chainPenalty = (delayedVisit && inheritedDifferential > 0) ? inheritedDifferential : 0;
			// NB: Do not need to check for wilderness level for transports, since transports have specific origin tile.
			neighbors.add(graph.createTransport(
				transport.getDestination(),
				node,
				transport.getDuration(),
				config.getAdditionalTransportCost(transport) + chainPenalty,
				pathBankVisited,
				delayedVisit,
				delayedVisit ? config.getDifferentialCost(transport) : 0));
		}

		// Global teleports are only considered from an abstract node, so each
		// wilderness/bank state expands them once.
		AbstractNodeKind abstractKind = AbstractNodeKind.fromWildernessLevel(wildernessLevel);
		if (!visited.getAbstract(abstractKind, pathBankVisited))
		{
			neighbors.add(graph.createAbstract(abstractKind, node, pathBankVisited));
		}

		// Then add tiles which we can walk to, which go into the FIFO boundary queue.
		if (isBlocked(x, y, z))
		{
			boolean westBlocked = isBlocked(x - 1, y, z);
			boolean eastBlocked = isBlocked(x + 1, y, z);
			boolean southBlocked = isBlocked(x, y - 1, z);
			boolean northBlocked = isBlocked(x, y + 1, z);
			boolean southWestBlocked = isBlocked(x - 1, y - 1, z);
			boolean southEastBlocked = isBlocked(x + 1, y - 1, z);
			boolean northWestBlocked = isBlocked(x - 1, y + 1, z);
			boolean northEastBlocked = isBlocked(x + 1, y + 1, z);
			traversable[0] = !westBlocked;
			traversable[1] = !eastBlocked;
			traversable[2] = !southBlocked;
			traversable[3] = !northBlocked;
			traversable[4] = !southWestBlocked && !westBlocked && !southBlocked;
			traversable[5] = !southEastBlocked && !eastBlocked && !southBlocked;
			traversable[6] = !northWestBlocked && !westBlocked && !northBlocked;
			traversable[7] = !northEastBlocked && !eastBlocked && !northBlocked;
		}
		else
		{
			traversable[0] = w(x, y, z);
			traversable[1] = e(x, y, z);
			traversable[2] = s(x, y, z);
			traversable[3] = n(x, y, z);
			traversable[4] = sw(x, y, z);
			traversable[5] = se(x, y, z);
			traversable[6] = nw(x, y, z);
			traversable[7] = ne(x, y, z);
		}

		for (int i = 0; i < traversable.length; i++)
		{
			OrdinalDirection d = ORDINAL_VALUES[i];
			int neighborPacked = packedPointFromOrdinal(packedPosition, d);
			if (visited.get(neighborPacked, pathBankVisited))
			{
				continue;
			}

			if (traversable[i])
			{
				neighbors.add(graph.createTile(neighborPacked, node, pathBankVisited));
			}
			else if (Math.abs(d.x + d.y) == 1 && isBlocked(x + d.x, y + d.y, z))
			{
				// The transport starts from a blocked adjacent tile, e.g. fairy ring
				// Only checks non-teleport transports (includes portals and levers, but not
				// items and spells)
				Transport[] neighborTransports = config.getTransportsPacked(pathBankVisited).getOrDefault(neighborPacked,
					TransportAvailability.EMPTY_TRANSPORTS);
				for (Transport transport : neighborTransports)
				{
					if (transport.getOrigin() == Transport.UNDEFINED_ORIGIN
						|| !(transport.isUsableAtWildernessLevel(wildernessLevel))
						|| visited.get(transport.getOrigin(), pathBankVisited))
					{
						continue;
					}
					neighbors.add(graph.createTile(transport.getOrigin(), node, pathBankVisited));
				}
			}
		}

		return neighbors;
	}

	// The only abstract nodes are currently for global teleports
	private PrimitiveIntList getAbstractNodeNeighbors(int node, VisitedTiles visited, PathfinderConfig config,
		boolean targetInWilderness, NodeGraph graph)
	{
		neighbors.clear();
		int sourceTile = graph.getClosestTilePosition(node);
		boolean bankVisited = graph.bankVisited(node);
		int maxWildernessLevel = graph.abstractKind(node).maxWildernessLevel();
		for (Transport transport : config.getUsableTeleports(bankVisited))
		{
			boolean delayedVisit = transport.getType().sharesDestinationsWith() != null;
			if (!delayedVisit && visited.get(transport.getDestination(), bankVisited))
			{
				continue;
			}
			if (!transport.isUsableAtWildernessLevel(maxWildernessLevel))
			{
				continue;
			}
			if (config.avoidWilderness(sourceTile, transport.getDestination(), targetInWilderness))
			{
				continue;
			}
			// The differential cost is only used for priority-queue ordering (compareCost), not
			// propagated as real cost, so applying it unconditionally is safe: a nearby partner
			// station can still win the dequeue race, and a far-away whistle still resolves as the
			// cheapest path because no competitor has a lower real cost to the same destination.
			int differentialCost = delayedVisit ? config.getDifferentialCost(transport) : 0;
			neighbors.add(graph.createTransport(
				transport.getDestination(),
				node,
				transport.getDuration(),
				config.getAdditionalTransportCost(transport),
				bankVisited,
				delayedVisit,
				differentialCost));
		}
		return neighbors;
	}
}

package com.travelguide.pathfinder;

/**
 * A minimal growable FIFO of primitive {@code int} node ids backed by a ring buffer.
 * <p>
 * Replaces the {@code ArrayDeque<Node>} boundary queue in {@link Pathfinder} so the search frontier
 * no longer boxes node references. Only the operations the pathfinder needs are implemented; it is
 * single-threaded (worker only) like the queue it replaces.
 */
class IntDeque
{
	private int[] elements;
	private int head;
	private int tail;
	private int size;

	IntDeque(int initialCapacity)
	{
		elements = new int[Math.max(1, initialCapacity)];
	}

	int size()
	{
		return size;
	}

	boolean isEmpty()
	{
		return size == 0;
	}

	void addLast(int value)
	{
		if (size == elements.length)
		{
			grow();
		}
		elements[tail] = value;
		tail = increment(tail);
		size++;
	}

	void addFirst(int value)
	{
		if (size == elements.length)
		{
			grow();
		}
		head = decrement(head);
		elements[head] = value;
		size++;
	}

	/**
	 * @return the first element, or {@link NodeGraph#NO_NODE} if empty.
	 */
	int peekFirst()
	{
		return size == 0 ? NodeGraph.NO_NODE : elements[head];
	}

	/**
	 * @return the removed first element, or {@link NodeGraph#NO_NODE} if empty.
	 */
	int pollFirst()
	{
		if (size == 0)
		{
			return NodeGraph.NO_NODE;
		}
		final int value = elements[head];
		head = increment(head);
		size--;
		return value;
	}

	void clear()
	{
		head = 0;
		tail = 0;
		size = 0;
	}

	private int increment(int index)
	{
		return index + 1 == elements.length ? 0 : index + 1;
	}

	private int decrement(int index)
	{
		return index == 0 ? elements.length - 1 : index - 1;
	}

	private void grow()
	{
		final int oldCapacity = elements.length;
		final int[] grown = new int[oldCapacity << 1];
		for (int i = 0; i < size; i++)
		{
			grown[i] = elements[(head + i) % oldCapacity];
		}
		elements = grown;
		head = 0;
		tail = size;
	}
}

package com.travelguide.pathfinder;

import java.util.Arrays;

/**
 * A binary min-heap of primitive {@code int} node ids ordered by {@link NodeGraph#compareCost}.
 * <p>
 * Replaces the {@code PriorityQueue<TransportNode>} pending queue in {@link Pathfinder} so transport
 * candidates are stored as int ids rather than boxed node objects. The ordering key is fixed when a
 * node is created (its differential cost never changes), so no decrease-key support is needed; the
 * pathfinder discards stale cheaper duplicates with its dequeue-time visited re-check. Single-threaded
 * (worker only), matching the queue it replaces.
 */
class IntMinHeap
{
	private final NodeGraph graph;
	private int[] heap;
	private int size;

	IntMinHeap(NodeGraph graph, int initialCapacity)
	{
		this.graph = graph;
		this.heap = new int[Math.max(1, initialCapacity)];
	}

	int size()
	{
		return size;
	}

	boolean isEmpty()
	{
		return size == 0;
	}

	/**
	 * @return the minimum-cost element, or {@link NodeGraph#NO_NODE} if empty.
	 */
	int peek()
	{
		return size == 0 ? NodeGraph.NO_NODE : heap[0];
	}

	void add(int id)
	{
		if (size == heap.length)
		{
			heap = Arrays.copyOf(heap, heap.length << 1);
		}
		heap[size] = id;
		siftUp(size);
		size++;
	}

	/**
	 * @return the removed minimum-cost element, or {@link NodeGraph#NO_NODE} if empty.
	 */
	int poll()
	{
		if (size == 0)
		{
			return NodeGraph.NO_NODE;
		}
		final int top = heap[0];
		size--;
		if (size > 0)
		{
			heap[0] = heap[size];
			siftDown(0);
		}
		return top;
	}

	void clear()
	{
		size = 0;
	}

	private void siftUp(int index)
	{
		final int id = heap[index];
		final int key = graph.compareCost(id);
		while (index > 0)
		{
			final int parent = (index - 1) >> 1;
			if (key >= graph.compareCost(heap[parent]))
			{
				break;
			}
			heap[index] = heap[parent];
			index = parent;
		}
		heap[index] = id;
	}

	private void siftDown(int index)
	{
		final int id = heap[index];
		final int key = graph.compareCost(id);
		final int half = size >> 1;
		while (index < half)
		{
			int child = (index << 1) + 1;
			int childKey = graph.compareCost(heap[child]);
			final int right = child + 1;
			if (right < size)
			{
				final int rightKey = graph.compareCost(heap[right]);
				if (rightKey < childKey)
				{
					child = right;
					childKey = rightKey;
				}
			}
			if (key <= childKey)
			{
				break;
			}
			heap[index] = heap[child];
			index = child;
		}
		heap[index] = id;
	}
}

package com.travelguide.pathfinder;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import com.travelguide.WorldPointUtil;

/**
 * Structure-of-Arrays store for pathfinding nodes.
 * <p>
 * The previous design allocated one {@link Object} per explored tile (a {@code Node} or
 * {@code TransportNode}). Heavy searches explore hundreds of thousands of tiles, so this produced
 * hundreds of thousands of live objects, each carrying a ~16-byte header plus several object
 * references (issue #491). Here every node is instead an {@code int} index into parallel primitive
 * arrays, so a whole search holds only a handful of arrays regardless of how many nodes it visits.
 * <p>
 * The fields packed per node are exactly those of the old {@code Node}/{@code TransportNode}:
 * packed world position, the index of the previous node ({@link #NO_NODE} for the start),
 * accumulated cost, the transport differential cost (queue-ordering only), a set of boolean flags,
 * and the {@link AbstractNodeKind} ordinal for abstract nodes.
 * <p>
 * <strong>Threading.</strong> The search runs on a single worker thread, but the render thread
 * reads the partial path while the search is still running (progressive rendering via
 * {@code Pathfinder.getPath()}). Node data is write-once and is published to the render thread by
 * the single volatile {@code Pathfinder.bestLastNode} handoff rather than by marking these arrays
 * {@code volatile} (which would cripple the hot loop, see the field comment). The chain walks
 * ({@link #getPathSteps} / {@link #getClosestTilePosition}) snapshot the arrays into locals and
 * tolerate an index that is out of bounds or released. This means a walk concurrent with a
 * grow/release can never throw; at worst it yields a one-frame-stale path.
 */
public class NodeGraph
{
	public static final int NO_NODE = -1;

	private static final byte FLAG_BANK_VISITED = 1;       // bit0
	private static final byte FLAG_ABSTRACT = 1 << 1;      // bit1
	private static final byte FLAG_DELAYED_VISIT = 1 << 2; // bit2
	private static final byte FLAG_TRANSPORT = 1 << 3;     // bit3

	// Enum.values() copies on every call, so cache it for the abstractKind lookup.
	private static final AbstractNodeKind[] ABSTRACT_KINDS = AbstractNodeKind.values();

	// The node arrays are NOT volatile: making them volatile forces every accessor (packedPosition,
	// cost, isTile, compareCost, the append() writes, ...) to re-read the array reference on each
	// call and blocks the JIT from caching the base in a register or eliminating bounds checks. The
	// hot loop touches these hundreds of times per node, so volatile reads roughly halved field
	// throughput (~1.6x slower searches). Safe publication to the render thread is provided instead
	// by the single volatile Pathfinder.bestLastNode handoff: the worker writes the node data, then
	// volatile-writes bestLastNode; the render thread volatile-reads bestLastNode before walking,
	// which establishes happens-before for all the plain writes above it. The walk methods snapshot
	// the references into locals and tolerate a null (post-release) or stale-but-valid (mid-grow,
	// Arrays.copyOf preserves every index) array, so a concurrent grow/release never throws.
	private int[] packedPosition;
	private int[] previous;
	private int[] cost;
	private int[] differentialCost;
	private byte[] flags;
	private byte[] abstractKind;
	private int size;

	public NodeGraph(int initialCapacity)
	{
		final int capacity = Math.max(1, initialCapacity);
		packedPosition = new int[capacity];
		previous = new int[capacity];
		cost = new int[capacity];
		differentialCost = new int[capacity];
		flags = new byte[capacity];
		abstractKind = new byte[capacity];
	}

	public int size()
	{
		return size;
	}

	private void ensureCapacity()
	{
		if (size < packedPosition.length)
		{
			return;
		}
		// Grow by 50% like ArrayList. Arrays.copyOf preserves every existing index, and node data
		// is write-once, so a render thread reading a pre-grow array still sees correct values for
		// the indices it walks.
		final int newCapacity = packedPosition.length + (packedPosition.length >> 1);
		packedPosition = Arrays.copyOf(packedPosition, newCapacity);
		previous = Arrays.copyOf(previous, newCapacity);
		cost = Arrays.copyOf(cost, newCapacity);
		differentialCost = Arrays.copyOf(differentialCost, newCapacity);
		flags = Arrays.copyOf(flags, newCapacity);
		abstractKind = Arrays.copyOf(abstractKind, newCapacity);
	}

	private int append(int packed, int prev, int nodeCost, int diffCost, byte flagBits, byte kind)
	{
		ensureCapacity();
		final int id = size;
		packedPosition[id] = packed;
		previous[id] = prev;
		cost[id] = nodeCost;
		differentialCost[id] = diffCost;
		abstractKind[id] = kind;
		flags[id] = flagBits;
		size = id + 1;
		return id;
	}

	private int costOf(int id)
	{
		return id == NO_NODE ? 0 : cost[id];
	}

	/**
	 * The search root. Carries no previous node and zero cost.
	 */
	public int createStart(int packedPosition)
	{
		return append(packedPosition, NO_NODE, 0, 0, (byte) 0, (byte) 0);
	}

	/**
	 * A concrete walkable tile. Travel cost is the walking distance from the previous node, but
	 * only when the previous node is itself a tile (mirrors the old {@code Node.cost}); reaching a
	 * tile from an abstract node adds no travel cost.
	 */
	public int createTile(int packedPosition, int previous, boolean bankVisited)
	{
		final int travelTime = (previous != NO_NODE && isTile(previous))
			? WorldPointUtil.distanceBetween(this.packedPosition[previous], packedPosition)
			: 0;
		final byte flagBits = bankVisited ? FLAG_BANK_VISITED : 0;
		return append(packedPosition, previous, costOf(previous) + travelTime, 0, flagBits, (byte) 0);
	}

	/**
	 * A transport destination tile. Cost is the previous cost plus the transport's travel time and
	 * any additional cost; there is no walking-distance term (mirrors the old {@code TransportNode}).
	 */
	public int createTransport(int packedPosition, int previous, int travelTime, int additionalCost,
		boolean bankVisited, boolean delayedVisit, int differentialCost)
	{
		byte flagBits = FLAG_TRANSPORT;
		if (bankVisited)
		{
			flagBits |= FLAG_BANK_VISITED;
		}
		if (delayedVisit)
		{
			flagBits |= FLAG_DELAYED_VISIT;
		}
		return append(packedPosition, previous, costOf(previous) + travelTime + additionalCost,
			differentialCost, flagBits, (byte) 0);
	}

	/**
	 * An abstract search-state node (global teleports). Has no world position and inherits the
	 * previous node's cost (mirrors the old {@code Node.abstractNode}).
	 */
	public int createAbstract(AbstractNodeKind abstractKind, int previous, boolean bankVisited)
	{
		byte flagBits = FLAG_ABSTRACT;
		if (bankVisited)
		{
			flagBits |= FLAG_BANK_VISITED;
		}
		return append(WorldPointUtil.UNDEFINED, previous, costOf(previous), 0, flagBits,
			(byte) abstractKind.ordinal());
	}

	public int packedPosition(int id)
	{
		return packedPosition[id];
	}

	public int previous(int id)
	{
		return previous[id];
	}

	public int cost(int id)
	{
		return cost[id];
	}

	public int differentialCost(int id)
	{
		return differentialCost[id];
	}

	/**
	 * The cost used for priority-queue ordering, includes the transport differential.
	 */
	public int compareCost(int id)
	{
		return cost[id] + differentialCost[id];
	}

	public boolean bankVisited(int id)
	{
		return (flags[id] & FLAG_BANK_VISITED) != 0;
	}

	public boolean isTile(int id)
	{
		return (flags[id] & FLAG_ABSTRACT) == 0;
	}

	public boolean isAbstract(int id)
	{
		return (flags[id] & FLAG_ABSTRACT) != 0;
	}

	public boolean isTransport(int id)
	{
		return (flags[id] & FLAG_TRANSPORT) != 0;
	}

	public boolean isDelayedVisit(int id)
	{
		return (flags[id] & FLAG_DELAYED_VISIT) != 0;
	}

	public AbstractNodeKind abstractKind(int id)
	{
		return ABSTRACT_KINDS[abstractKind[id]];
	}

	/**
	 * Walks the previous chain from {@code id} to the start, collecting the tile nodes (abstract
	 * nodes are skipped) into an ordered list of path steps.
	 * <p>
	 * Safe to call from the render thread during the search: the arrays are snapshotted into locals
	 * and the walk is bounds-tolerant, so a concurrent grow or {@link #release()} yields an empty
	 * or one-frame-stale result rather than throwing.
	 */
	public List<PathStep> getPathSteps(int id)
	{
		final int[] prev = previous;
		final int[] packed = packedPosition;
		final byte[] flg = flags;
		if (prev == null || packed == null || flg == null || id == NO_NODE)
		{
			return new ArrayList<>();
		}
		final int len = prev.length;

		int node = id;
		int n = 0;
		while (node != NO_NODE && node < len)
		{
			if ((flg[node] & FLAG_ABSTRACT) == 0)
			{
				n++;
			}
			node = prev[node];
		}

		final List<PathStep> pathSteps = new ArrayList<>(n);
		for (int i = 0; i < n; i++)
		{
			pathSteps.add(null);
		}

		node = id;
		int i = n;
		while (node != NO_NODE && node < len && i > 0)
		{
			if ((flg[node] & FLAG_ABSTRACT) == 0)
			{
				pathSteps.set(--i, new PathStep(packed[node], (flg[node] & FLAG_BANK_VISITED) != 0));
			}
			node = prev[node];
		}

		return pathSteps;
	}

	/**
	 * Walks the previous chain from {@code id} until the first tile node and returns its packed
	 * position, or {@link WorldPointUtil#UNDEFINED} if none. Same threading guarantees as
	 * {@link #getPathSteps}.
	 */
	public int getClosestTilePosition(int id)
	{
		final int[] prev = previous;
		final int[] packed = packedPosition;
		final byte[] flg = flags;
		if (prev == null || packed == null || flg == null)
		{
			return WorldPointUtil.UNDEFINED;
		}
		final int len = prev.length;
		int node = id;
		while (node != NO_NODE && node < len && (flg[node] & FLAG_ABSTRACT) != 0)
		{
			node = prev[node];
		}
		return (node != NO_NODE && node < len) ? packed[node] : WorldPointUtil.UNDEFINED;
	}

	/**
	 * Releases the backing arrays once the search is finished and the final path has been
	 * materialised, so the large per-search working set becomes eligible for garbage collection
	 * (the old design dropped the explored {@code Node} objects the same way by clearing the
	 * frontier collections). A render-thread walk in flight keeps its own local references and
	 * finishes safely.
	 */
	public void release()
	{
		packedPosition = null;
		previous = null;
		cost = null;
		differentialCost = null;
		flags = null;
		abstractKind = null;
		size = 0;
	}
}

package com.travelguide.pathfinder;

public enum OrdinalDirection
{
	WEST(-1, 0),
	EAST(1, 0),
	SOUTH(0, -1),
	NORTH(0, 1),
	SOUTH_WEST(-1, -1),
	SOUTH_EAST(1, -1),
	NORTH_WEST(-1, 1),
	NORTH_EAST(1, 1);

	final int x;
	final int y;

	OrdinalDirection(int x, int y)
	{
		this.x = x;
		this.y = y;
	}
}

package com.travelguide.pathfinder;

import lombok.Getter;

@Getter
public final class PathStep
{
	private final int packedPosition;
	private final boolean bankVisited;

	public PathStep(int packedPosition, boolean bankVisited)
	{
		this.packedPosition = packedPosition;
		this.bankVisited = bankVisited;
	}
}

package com.travelguide.pathfinder;

public enum PathTerminationReason
{
	TARGET_REACHED,
	SEARCH_EXHAUSTED,
	CUTOFF_REACHED,
	CANCELLED
}

package com.travelguide.pathfinder;

import java.util.List;
import java.util.Set;

import lombok.Getter;
import com.travelguide.PrimitiveIntList;
import com.travelguide.WorldPointUtil;
import com.travelguide.leagues.LeagueModeState;

public class Pathfinder implements Runnable
{
	private final PathfinderStats stats;
	@Getter
	private final int start;
	@Getter
	private final Set<Integer> targets;
	private final PathfinderConfig config;
	private final CollisionMap map;
	private final boolean targetInWilderness;
	private final boolean targetInBlockedRegion;
	private final Runnable completionCallback;
	// Nodes are stored structure-of-arrays style: each node is an int id into the graph, instead of
	// an object per explored tile. This keeps a whole search to a handful of arrays (issue #491).
	private final NodeGraph graph = new NodeGraph(1 << 14);
	// Capacities should be enough to store all nodes without requiring the queue to grow
	// They were found by checking the max queue size
	private final IntDeque boundary = new IntDeque(4096);
	private final IntMinHeap pending = new IntMinHeap(graph, 256);
	private final VisitedTiles visited;
	@Getter
	private volatile boolean done = false;
	private volatile boolean cancelled = false;
	// Read by the render thread during the search to draw the partial path; written by the worker.
	private volatile int bestLastNode = NodeGraph.NO_NODE;
	// The path the render thread builds progressively while the search runs.
	private List<PathStep> pathSteps = List.of();
	private boolean pathNeedsUpdate = false;
	// Built once on the worker thread when the search finishes, then served to the render thread so
	// it never walks the node chain (which is released) after the search is done.
	private volatile List<PathStep> finalPath = null;
	private volatile int closestReachedPoint = WorldPointUtil.UNDEFINED;
	private int bestRemainingDistance = Integer.MAX_VALUE;
	private int bestTravelledDistance = Integer.MAX_VALUE;
	private int bestX = Integer.MAX_VALUE;
	private int bestY = Integer.MAX_VALUE;
	private int reachedTarget = WorldPointUtil.UNDEFINED;
	private PathTerminationReason terminationReason;
	/**
	 * Teleportation transports are updated when this changes.
	 * Can be either:
	 * 0 = all teleports can be used (e.g. Chronicle)
	 * 20 = most teleports can be used (e.g. Varrock Teleport)
	 * 30 = some teleports can be used (e.g. Amulet of Glory)
	 * 31 = no teleports can be used
	 */
	private int wildernessLevel;

	public Pathfinder(PathfinderConfig config, int start, Set<Integer> targets, Runnable completionCallback)
	{
		stats = new PathfinderStats();
		this.config = config;
		this.map = config.getMap();
		this.start = start;
		this.targets = targets;
		this.completionCallback = completionCallback;
		visited = new VisitedTiles(map);
		targetInWilderness = WildernessChecker.isInWilderness(targets);
		targetInBlockedRegion = anyInBlockedRegion(config.getLeagueModeState(), targets);
		wildernessLevel = 31;
	}

	private static boolean anyInBlockedRegion(LeagueModeState league, Set<Integer> packed)
	{
		if (!league.isSeasonal() || packed == null || packed.isEmpty())
		{
			return false;
		}
		for (Integer point : packed)
		{
			if (league.isInBlockedRegion(point))
			{
				return true;
			}
		}
		return false;
	}

	public Pathfinder(PathfinderConfig config, int start, Set<Integer> targets)
	{
		this(config, start, targets, null);
	}

	public void cancel()
	{
		cancelled = true;
	}

	public PathfinderStats getStats()
	{
		if (stats.started && stats.ended)
		{
			return stats;
		}

		// Don't give incomplete results
		return null;
	}

	public List<PathStep> getPath()
	{
		int lastNode = bestLastNode; // For thread safety, read bestLastNode once
		if (lastNode == NodeGraph.NO_NODE)
		{
			List<PathStep> finalised = finalPath;
			return finalised != null ? finalised : pathSteps;
		}

		// Once the search is finished the node graph is released, so serve the pre-built snapshot.
		if (done)
		{
			List<PathStep> finalised = finalPath;
			if (finalised != null)
			{
				return finalised;
			}
		}

		if (pathNeedsUpdate)
		{
			List<PathStep> walked = graph.getPathSteps(lastNode);
			// An empty result means the graph was released mid-walk; keep the last good path.
			if (!walked.isEmpty())
			{
				pathSteps = walked;
				pathNeedsUpdate = false;
			}
		}

		return pathSteps;
	}

	public PathfinderResult getResult()
	{
		PathfinderStats currentStats = getStats();
		if (currentStats == null)
		{
			return null;
		}

		List<PathStep> currentPath = getPath();
		boolean reached = reachedTarget != WorldPointUtil.UNDEFINED;
		int target = reached ? reachedTarget : (targets.isEmpty() ? WorldPointUtil.UNDEFINED : targets.iterator().next());
		// getStats() only returns non-null once the search has ended, so the snapshot is set.
		return new PathfinderResult(
			start,
			target,
			reached,
			currentPath,
			closestReachedPoint,
			currentStats.getNodesChecked(),
			currentStats.getTransportsChecked(),
			currentStats.getElapsedTimeNanos(),
			terminationReason
		);
	}

	private void addNeighbors(int node, boolean nodeIsTile, int nodePacked)
	{
		PrimitiveIntList nodes = map.getNeighbors(node, visited, config, wildernessLevel, targetInWilderness, graph);
		final int count = nodes.size();
		for (int i = 0; i < count; i++)
		{
			int neighbor = nodes.get(i);
			// Each graph.xxx(id) re-indexes a backing array, so read each neighbour field once and
			// reuse the loop-invariant node fields passed in (the JIT cached these for free when nodes
			// were objects, but not when they are int ids into structure-of-arrays storage).
			final boolean neighborIsTile = graph.isTile(neighbor);
			if (nodeIsTile && neighborIsTile)
			{
				final int neighborPacked = graph.packedPosition(neighbor);
				if (config.avoidWilderness(nodePacked, neighborPacked, targetInWilderness))
				{
					continue;
				}
				if (config.avoidBlockedRegion(nodePacked, neighborPacked, targetInBlockedRegion))
				{
					continue;
				}
			}

			final boolean neighborIsTransport = graph.isTransport(neighbor);
			// For delayed-visit nodes (shared destinations), don't mark as visited on enqueue.
			// They will be checked and marked when dequeued from pending.
			if (!(neighborIsTransport && graph.isDelayedVisit(neighbor)))
			{
				visited.set(neighbor, graph);
			}
			if (neighborIsTransport)
			{
				pending.add(neighbor);
				++stats.transportsChecked;
			}
			else
			{
				boundary.addLast(neighbor);
				++stats.nodesChecked;
			}
		}
	}

	/**
	 * Pathfinding to an unreachable target is slightly different from normal pathfinding.
	 * Straight-line movement before diagonal movement is no longer prioritized, because the
	 * original target is moved to the closest reachable tile. To avoid having to move the
	 * original target we instead do the following to favour the closest reachable tile:
	 * - 1) Pick the path with the minimum Euclidean distance (no need to use square root though)
	 * - 2) If a tie occurs, pick the path with minimum travelled distance
	 * - 3) If another tie occurs, pick the path with minimum x-coordinate
	 * - 4) If another tie occurs, pick the path with minimum y-coordinate
	 */
	private boolean updateBestPathWhenUnreachable(int node, int packedPosition)
	{
		boolean update = false;

		final int travelledDistance = graph.cost(node);
		for (int target : targets)
		{
			int remainingDistance = WorldPointUtil.distanceBetween(target, packedPosition, WorldPointUtil.EUCLIDEAN_SQUARED_DISTANCE_METRIC);
			int x = WorldPointUtil.unpackWorldX(packedPosition);
			int y = WorldPointUtil.unpackWorldY(packedPosition);
			if ((remainingDistance < bestRemainingDistance) ||
				(remainingDistance == bestRemainingDistance && travelledDistance < bestTravelledDistance) ||
				(remainingDistance == bestRemainingDistance && travelledDistance == bestTravelledDistance && x < bestX) ||
				(remainingDistance == bestRemainingDistance && travelledDistance == bestTravelledDistance && x == bestX && y < bestY))
			{
				bestRemainingDistance = remainingDistance;
				bestTravelledDistance = travelledDistance;
				bestX = x;
				bestY = y;
				bestLastNode = node;
				pathNeedsUpdate = true;
				update = true;
			}
		}

		return update;
	}

	/**
	 * Update wilderness level based on the current node position.
	 */
	private void updateWildernessLevel(int packedPosition)
	{
		if (wildernessLevel > 0)
		{
			// These are overlapping boundaries, so if the node isn't in level 30, it's in 0-29
			// likewise, if the node isn't in level 20, it's in 0-19
			if (wildernessLevel > 30 && !WildernessChecker.isInLevel30Wilderness(packedPosition))
			{
				wildernessLevel = 30;
			}
			if (wildernessLevel > 20 && !WildernessChecker.isInLevel20Wilderness(packedPosition))
			{
				wildernessLevel = 20;
			}
			if (wildernessLevel > 0 && !WildernessChecker.isInWilderness(packedPosition))
			{
				wildernessLevel = 0;
			}
		}
	}

	@Override
	public void run()
	{
		stats.start();
		boundary.addFirst(graph.createStart(start));

		long cutoffDurationMillis = config.getCalculationCutoffMillis();
		long cutoffTimeMillis = System.currentTimeMillis() + cutoffDurationMillis;

		while (!cancelled && (!boundary.isEmpty() || !pending.isEmpty()))
		{
			int boundaryHead = boundary.peekFirst();
			int pendingHead = pending.peek();

			int node;
			if (pendingHead != NodeGraph.NO_NODE
				&& (boundaryHead == NodeGraph.NO_NODE || graph.compareCost(pendingHead) < graph.cost(boundaryHead)))
			{
				node = pending.poll();

				// For delayed-visit nodes, check if the destination was already
				// reached by a cheaper path while this node was queued.
				if (graph.isDelayedVisit(node))
				{
					int packed = graph.packedPosition(node);
					boolean bank = graph.bankVisited(node);
					if (visited.get(packed, bank))
					{
						continue;
					}
					visited.set(packed, bank);
				}
			}
			else
			{
				node = boundary.pollFirst();
			}
			if (node == NodeGraph.NO_NODE)
			{
				continue;
			}
			// Read the node's tile-ness and position once; every graph.xxx(id) re-indexes a backing
			// array, and these are used by several of the checks below.
			final boolean nodeIsTile = graph.isTile(node);
			final int nodePacked = nodeIsTile ? graph.packedPosition(node) : WorldPointUtil.UNDEFINED;
			if (nodeIsTile)
			{
				updateWildernessLevel(nodePacked);

				if (targets.contains(nodePacked))
				{
					bestLastNode = node;
					pathNeedsUpdate = true;
					reachedTarget = nodePacked;
					terminationReason = PathTerminationReason.TARGET_REACHED;
					break;
				}

				if (updateBestPathWhenUnreachable(node, nodePacked))
				{
					cutoffTimeMillis = System.currentTimeMillis() + cutoffDurationMillis;
				}
			}

			if (System.currentTimeMillis() > cutoffTimeMillis)
			{
				terminationReason = PathTerminationReason.CUTOFF_REACHED;
				break;
			}

			addNeighbors(node, nodeIsTile, nodePacked);
		}

		if (cancelled)
		{
			terminationReason = PathTerminationReason.CANCELLED;
		}
		else if (terminationReason == null)
		{
			terminationReason = PathTerminationReason.SEARCH_EXHAUSTED;
		}

		// Materialise the final path and closest reached tile on the worker thread, publish them,
		// then release the large node graph. Once done is set the render thread serves finalPath
		// and never touches the released graph, so this is race-free with progressive rendering.
		int lastNode = bestLastNode;
		if (lastNode != NodeGraph.NO_NODE)
		{
			finalPath = graph.getPathSteps(lastNode);
			closestReachedPoint = graph.getClosestTilePosition(lastNode);
		}
		else
		{
			finalPath = pathSteps;
			closestReachedPoint = start;
		}

		done = !cancelled;

		boundary.clear();
		visited.clear();
		pending.clear();
		graph.release();

		stats.end(); // Include cleanup in stats to get the total cost of pathfinding

		if (completionCallback != null)
		{
			completionCallback.run();
		}
	}

	public static class PathfinderStats
	{
		@Getter
		private int nodesChecked = 0, transportsChecked = 0;
		private long startNanos, endNanos;
		private volatile boolean started = false, ended = false;

		public int getTotalNodesChecked()
		{
			return nodesChecked + transportsChecked;
		}

		public long getElapsedTimeNanos()
		{
			return endNanos - startNanos;
		}

		private void start()
		{
			started = true;
			nodesChecked = 0;
			transportsChecked = 0;
			startNanos = System.nanoTime();
		}

		private void end()
		{
			endNanos = System.nanoTime();
			ended = true;
		}
	}
}

