package com.travelguide.pathfinder;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.util.Arrays;
import java.util.BitSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

import static net.runelite.api.Constants.REGION_SIZE;

import com.travelguide.TravelGuidePlugin;
import com.travelguide.Util;

public class SplitFlagMap
{
	private static final int FLAG_COUNT = 2;
	private static final int BITS_PER_PLANE = REGION_SIZE * REGION_SIZE * FLAG_COUNT;
	private static final int WORDS_PER_PLANE = BITS_PER_PLANE / Long.SIZE;
	private static final int REGION_MASK = REGION_SIZE - 1;

	@Getter
	private static RegionExtent regionExtents;

	private final byte[] regionMapPlaneCounts;
	// Every region's collision bits are packed into one shared word array instead of a separate
	// FlagMap + BitSet + long[] per region. regionWordOffset gives each region's start word, or -1
	// when the region has no collision data (issue #491).
	private final long[] flags;
	private final int[] regionWordOffset;
	private final int widthInclusive;

	public SplitFlagMap(Map<Integer, byte[]> compressedRegions)
	{
		widthInclusive = regionExtents.getWidth() + 1;
		final int heightInclusive = regionExtents.getHeight() + 1;
		final int regionCount = widthInclusive * heightInclusive;
		regionMapPlaneCounts = new byte[regionCount];
		regionWordOffset = new int[regionCount];
		Arrays.fill(regionWordOffset, -1);

		// First pass: decode each region and reserve it a slice of the shared word array.
		final Map<Integer, long[]> regionWords = new HashMap<>(compressedRegions.size());
		int totalWords = 0;
		for (Map.Entry<Integer, byte[]> entry : compressedRegions.entrySet())
		{
			final int pos = entry.getKey();
			final int index = getIndex(unpackX(pos), unpackY(pos));
			final BitSet bits = BitSet.valueOf(entry.getValue());
			// Same plane-count derivation the old FlagMap used.
			final int planeCount = (bits.size() + BITS_PER_PLANE - 1) / BITS_PER_PLANE;
			regionMapPlaneCounts[index] = (byte) planeCount;
			regionWordOffset[index] = totalWords;
			regionWords.put(index, bits.toLongArray());
			totalWords += planeCount * WORDS_PER_PLANE;
		}

		// Second pass: copy each region's words into its reserved slice (trailing zero words from
		// BitSet.toLongArray are left as the zero-filled remainder of the slice).
		flags = new long[totalWords];
		for (Map.Entry<Integer, long[]> entry : regionWords.entrySet())
		{
			final long[] words = entry.getValue();
			System.arraycopy(words, 0, flags, regionWordOffset[entry.getKey()], words.length);
		}
	}

	public static int unpackX(int position)
	{
		return position & 0xFFFF;
	}

	public static int unpackY(int position)
	{
		return (position >> 16) & 0xFFFF;
	}

	public static int packPosition(int x, int y)
	{
		return (x & 0xFFFF) | ((y & 0xFFFF) << 16);
	}

	public static SplitFlagMap fromResources()
	{
		Map<Integer, byte[]> compressedRegions = new HashMap<>();
		try (ZipInputStream in = new ZipInputStream(Objects.requireNonNull(TravelGuidePlugin.class.getResourceAsStream("/collision-map.zip"))))
		{
			int minX = Integer.MAX_VALUE;
			int minY = Integer.MAX_VALUE;
			int maxX = 0;
			int maxY = 0;

			ZipEntry entry;
			while ((entry = in.getNextEntry()) != null)
			{
				String[] n = entry.getName().split("_");
				final int x = Integer.parseInt(n[0]);
				final int y = Integer.parseInt(n[1]);
				minX = Math.min(minX, x);
				minY = Math.min(minY, y);
				maxX = Math.max(maxX, x);
				maxY = Math.max(maxY, y);

				compressedRegions.put(SplitFlagMap.packPosition(x, y), Util.readAllBytes(in));
			}

			regionExtents = new RegionExtent(minX, minY, maxX, maxY);
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}

		return new SplitFlagMap(compressedRegions);
	}

	public byte getRegionPlaneCounts(int index)
	{
		return regionMapPlaneCounts[index];
	}

	public boolean get(int x, int y, int z, int flag)
	{
		final int index = getIndex(x / REGION_SIZE, y / REGION_SIZE);
		if (index < 0 || index >= regionWordOffset.length)
		{
			return false;
		}

		final int wordOffset = regionWordOffset[index];
		if (wordOffset < 0 || z < 0 || z >= regionMapPlaneCounts[index])
		{
			return false;
		}

		// SplitFlagMap routes (x, y) to the region that contains it, so the in-region coordinates
		// are simply the low REGION_SIZE bits; this matches the old FlagMap.index arithmetic.
		final int localBit = (z * REGION_SIZE * REGION_SIZE
			+ (y & REGION_MASK) * REGION_SIZE
			+ (x & REGION_MASK)) * FLAG_COUNT + flag;
		return (flags[wordOffset + (localBit >> 6)] >>> (localBit & 63) & 1L) != 0L;
	}

	private int getIndex(int regionX, int regionY)
	{
		return (regionX - regionExtents.getMinX()) + (regionY - regionExtents.getMinY()) * widthInclusive;
	}

	@RequiredArgsConstructor
	@Getter
	public static class RegionExtent
	{
		public final int minX, minY, maxX, maxY;

		public int getWidth()
		{
			return maxX - minX;
		}

		public int getHeight()
		{
			return maxY - minY;
		}
	}
}

package com.travelguide.pathfinder;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

import com.travelguide.PrimitiveIntHashMap;
import com.travelguide.WorldPointUtil;
import com.travelguide.transport.Transport;

public final class TransportAvailability
{
	public static final Transport[] EMPTY_TRANSPORTS = new Transport[0];

	// Transports grouped by origin tile, stored as flat arrays. The per-origin HashSet/HashMap
	// wrappers used while building are not retained (issue #491).
	//
	// transportsPacked is the pathfinding view: a transport is reachable from its literal origin
	// tile, and POH transports are additionally reachable from the canonical landing tile.
	// displayTransports is the coarse display view used by overlays and getTransports(): POH origin
	// tiles are collapsed into the landing tile only. The two maps share their Transport[] arrays
	// for every non-POH origin.
	private final PrimitiveIntHashMap<Transport[]> transportsPacked;
	private final PrimitiveIntHashMap<Transport[]> displayTransports;
	private final Transport[] usableTeleports;

	TransportAvailability(
		PrimitiveIntHashMap<Transport[]> transportsPacked,
		PrimitiveIntHashMap<Transport[]> displayTransports,
		Transport[] usableTeleports)
	{
		this.transportsPacked = transportsPacked;
		this.displayTransports = displayTransports;
		this.usableTeleports = usableTeleports;
	}

	public PrimitiveIntHashMap<Transport[]> getTransportsPacked()
	{
		return transportsPacked;
	}

	public PrimitiveIntHashMap<Transport[]> getDisplayTransports()
	{
		return displayTransports;
	}

	public Transport[] getUsableTeleports()
	{
		return usableTeleports;
	}

	/**
	 * The transports that start at the given origin tile in the display view, or an empty array.
	 */
	public Transport[] getTransportsAt(int origin)
	{
		return displayTransports.getOrDefault(origin, EMPTY_TRANSPORTS);
	}

	/*
	 * Build a TransportAvailability by incrementally adding available transports.
	 */
	static final class Builder
	{
		// Temporary accumulation; converted to flat arrays in build() and not retained afterwards.
		private final Map<Integer, Set<Transport>> transportsByOrigin;
		private final Set<Transport> usableTeleports;
		private final Set<Integer> pohOrigins = new HashSet<>();

		Builder(int expectedTransportCount)
		{
			this.transportsByOrigin = new HashMap<>(expectedTransportCount / 2);
			this.usableTeleports = new HashSet<>(expectedTransportCount / 20);
		}

		void add(Transport transport)
		{
			if (transport.getOrigin() == WorldPointUtil.UNDEFINED)
			{
				usableTeleports.add(transport);
				return;
			}

			transportsByOrigin.computeIfAbsent(transport.getOrigin(), ignored -> new HashSet<>()).add(transport);
		}

		void remapPohTransports()
		{
			int pohLanding = WorldPointUtil.packWorldPoint(1923, 5709, 0);
			Set<Transport> pohTransports = new HashSet<>();

			for (Map.Entry<Integer, Set<Transport>> entry : transportsByOrigin.entrySet())
			{
				int origin = entry.getKey();
				int originX = WorldPointUtil.unpackWorldX(origin);
				int originY = WorldPointUtil.unpackWorldY(origin);
				if (com.travelguide.TravelGuidePlugin.isInsidePoh(originX, originY))
				{
					pohTransports.addAll(entry.getValue());
					// Kept in the pathfinding view, collapsed out of the display view.
					pohOrigins.add(origin);
				}
			}

			if (!pohTransports.isEmpty())
			{
				transportsByOrigin.computeIfAbsent(pohLanding, ignored -> new HashSet<>()).addAll(pohTransports);
			}
		}

		TransportAvailability build()
		{
			int expected = Math.max(1, transportsByOrigin.size());
			PrimitiveIntHashMap<Transport[]> packed = new PrimitiveIntHashMap<>(expected);
			PrimitiveIntHashMap<Transport[]> display = new PrimitiveIntHashMap<>(expected);
			for (Map.Entry<Integer, Set<Transport>> entry : transportsByOrigin.entrySet())
			{
				int origin = entry.getKey();
				Transport[] transports = entry.getValue().toArray(EMPTY_TRANSPORTS);
				packed.put(origin, transports);
				if (!pohOrigins.contains(origin))
				{
					display.put(origin, transports);
				}
			}
			return new TransportAvailability(packed, display, usableTeleports.toArray(EMPTY_TRANSPORTS));
		}
	}
}

package com.travelguide.pathfinder;

import static net.runelite.api.Constants.REGION_SIZE;

import com.travelguide.WorldPointUtil;

public class VisitedTiles
{
	private final SplitFlagMap.RegionExtent regionExtents;
	private final int widthInclusive;

	private final VisitedRegion[] visitedRegionsWithoutBank;
	private final VisitedRegion[] visitedRegionsWithBank;
	private final CollisionMap map;
	// Abstract nodes are visited separately from tile nodes because they represent
	// global search states, not map positions.
	private final boolean[] abstractVisitedWithoutBank = new boolean[AbstractNodeKind.values().length];
	private final boolean[] abstractVisitedWithBank = new boolean[AbstractNodeKind.values().length];

	public VisitedTiles(CollisionMap map)
	{
		this.map = map;
		regionExtents = SplitFlagMap.getRegionExtents();
		widthInclusive = regionExtents.getWidth() + 1;
		final int heightInclusive = regionExtents.getHeight() + 1;

		visitedRegionsWithoutBank = new VisitedRegion[widthInclusive * heightInclusive];
		visitedRegionsWithBank = new VisitedRegion[widthInclusive * heightInclusive];
	}

	public boolean get(int packedPoint, boolean bankVisited)
	{
		final int x = WorldPointUtil.unpackWorldX(packedPoint);
		final int y = WorldPointUtil.unpackWorldY(packedPoint);
		final int plane = WorldPointUtil.unpackWorldPlane(packedPoint);
		return get(x, y, plane, bankVisited);
	}

	public boolean get(int x, int y, int plane, boolean bankVisited)
	{
		VisitedRegion[] visitedRegions = bankVisited ? visitedRegionsWithBank : visitedRegionsWithoutBank;
		final int regionIndex = getRegionIndex(x / REGION_SIZE, y / REGION_SIZE);
		if (regionIndex < 0 || regionIndex >= visitedRegions.length)
		{
			return true; // Region is out of bounds; report that it's been visited to avoid exploring it
			// further
		}

		final VisitedRegion region = visitedRegions[regionIndex];
		if (region == null)
		{
			return false;
		}

		return region.get(x % REGION_SIZE, y % REGION_SIZE, plane);
	}

	public boolean set(int packedPoint, boolean bankVisited)
	{
		final int x = WorldPointUtil.unpackWorldX(packedPoint);
		final int y = WorldPointUtil.unpackWorldY(packedPoint);
		final int plane = WorldPointUtil.unpackWorldPlane(packedPoint);
		return set(x, y, plane, bankVisited);
	}

	public boolean get(int id, NodeGraph graph)
	{
		if (graph.isTile(id))
		{
			return get(graph.packedPosition(id), graph.bankVisited(id));
		}
		return getAbstract(graph.abstractKind(id), graph.bankVisited(id));
	}

	public boolean getAbstract(AbstractNodeKind abstractKind, boolean bankVisited)
	{
		return bankVisited
			? abstractVisitedWithBank[abstractKind.ordinal()]
			: abstractVisitedWithoutBank[abstractKind.ordinal()];
	}

	public boolean set(int id, NodeGraph graph)
	{
		if (graph.isTile(id))
		{
			return set(graph.packedPosition(id), graph.bankVisited(id));
		}

		final AbstractNodeKind abstractKind = graph.abstractKind(id);
		boolean visited = getAbstract(abstractKind, graph.bankVisited(id));
		if (graph.bankVisited(id))
		{
			abstractVisitedWithBank[abstractKind.ordinal()] = true;
			// A banked abstract state dominates the equivalent unbanked state.
		}
		abstractVisitedWithoutBank[abstractKind.ordinal()] = true;
		return !visited;
	}

	public boolean set(int x, int y, int plane, boolean bankVisited)
	{
		final int regionIndex = getRegionIndex(x / REGION_SIZE, y / REGION_SIZE);
		if (regionIndex < 0 || regionIndex >= visitedRegionsWithoutBank.length)
		{
			return false; // Region is out of bounds; report that it's been visited to avoid exploring it
			// further
		}

		if (bankVisited)
		{
			boolean unique = setInRegion(visitedRegionsWithBank, regionIndex, x, y, plane);
			// A banked tile dominates the equivalent unbanked tile, so populate both
			// buckets.
			setInRegion(visitedRegionsWithoutBank, regionIndex, x, y, plane);
			return unique;
		}

		return setInRegion(visitedRegionsWithoutBank, regionIndex, x, y, plane);
	}

	private boolean setInRegion(VisitedRegion[] visitedRegions, int regionIndex, int x, int y, int plane)
	{
		VisitedRegion region = visitedRegions[regionIndex];
		if (region == null)
		{
			region = new VisitedRegion(map.getRegionPlaneCounts(regionIndex));
			visitedRegions[regionIndex] = region;
		}
		return region.set(x % REGION_SIZE, y % REGION_SIZE, plane);
	}

	public void clear()
	{
		for (int i = 0; i < visitedRegionsWithoutBank.length; ++i)
		{
			visitedRegionsWithoutBank[i] = null;
			visitedRegionsWithBank[i] = null;
		}
		for (int i = 0; i < abstractVisitedWithoutBank.length; i++)
		{
			abstractVisitedWithoutBank[i] = false;
			abstractVisitedWithBank[i] = false;
		}
	}

	private int getRegionIndex(int regionX, int regionY)
	{
		return (regionX - regionExtents.minX) + (regionY - regionExtents.minY) * widthInclusive;
	}

	private static class VisitedRegion
	{
		// This assumes a row is at most 64 tiles and fits in a long
		private final long[] planes;
		private final byte planeCount;

		VisitedRegion(byte planeCount)
		{
			this.planeCount = planeCount;
			this.planes = new long[planeCount * REGION_SIZE];
		}

		// Sets a tile as visited in the tile bitset
		// Returns true if the tile is unique and hasn't been seen before or false if it
		// was seen before
		public boolean set(int x, int y, int plane)
		{
			if (plane >= planeCount)
			{
				// Plane is out of bounds; report that it has been visited to avoid further
				// exploration
				return false;
			}
			final int index = y + plane * REGION_SIZE;
			boolean unique = (planes[index] & (1L << x)) == 0;
			planes[index] |= 1L << x;
			return unique;
		}

		public boolean get(int x, int y, int plane)
		{
			if (plane >= planeCount)
			{
				// This check is necessary since we check visited tiles before checking the
				// collision map, e.g. the node
				// at (2816, 3455, 1) will check its neighbour to the north which is in a new
				// region with no plane = 1
				return true;
			}
			return (planes[y + plane * REGION_SIZE] & (1L << x)) != 0;
		}
	}
}

package com.travelguide.pathfinder;

import java.util.Set;

import net.runelite.api.coords.WorldArea;
import com.travelguide.WorldPointUtil;

public class WildernessChecker
{

	private static final WorldArea WILDERNESS_ABOVE_GROUND = new WorldArea(2944, 3525, 448, 448, 0);
	private static final WorldArea WILDERNESS_UNDERGROUND = new WorldArea(2944, 9918, 518, 458, 0);

	private static final WorldArea FEROX_ENCLAVE_1 = new WorldArea(3123, 3622, 2, 10, 0);
	private static final WorldArea FEROX_ENCLAVE_2 = new WorldArea(3125, 3617, 16, 23, 0);
	private static final WorldArea FEROX_ENCLAVE_3 = new WorldArea(3138, 3636, 18, 10, 0);
	private static final WorldArea FEROX_ENCLAVE_4 = new WorldArea(3141, 3625, 14, 11, 0);
	private static final WorldArea FEROX_ENCLAVE_5 = new WorldArea(3141, 3619, 7, 6, 0);

	private static final WorldArea NOT_WILDERNESS_1 = new WorldArea(2997, 3525, 34, 9, 0);
	private static final WorldArea NOT_WILDERNESS_2 = new WorldArea(3005, 3534, 21, 10, 0);
	private static final WorldArea NOT_WILDERNESS_3 = new WorldArea(3000, 3534, 5, 5, 0);
	private static final WorldArea NOT_WILDERNESS_4 = new WorldArea(3031, 3525, 2, 2, 0);

	private static final WorldArea WILDERNESS_ABOVE_GROUND_LEVEL_20 = new WorldArea(2944, 3680, 448, 448, 0);
	private static final WorldArea WILDERNESS_ABOVE_GROUND_LEVEL_30 = new WorldArea(2944, 3760, 448, 448, 0);
	private static final WorldArea WILDERNESS_UNDERGROUND_LEVEL_20 = new WorldArea(2944, 10075, 518, 301, 0);
	private static final WorldArea WILDERNESS_UNDERGROUND_LEVEL_30 = new WorldArea(2944, 10155, 518, 221, 0);

	public static boolean isInWilderness(int packedPoint)
	{
		return WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_ABOVE_GROUND) == 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, FEROX_ENCLAVE_1) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, FEROX_ENCLAVE_2) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, FEROX_ENCLAVE_3) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, FEROX_ENCLAVE_4) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, FEROX_ENCLAVE_5) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, NOT_WILDERNESS_1) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, NOT_WILDERNESS_2) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, NOT_WILDERNESS_3) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, NOT_WILDERNESS_4) != 0
			|| WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_UNDERGROUND) == 0;
	}

	public static boolean isInWilderness(Set<Integer> packedPoints)
	{
		for (int packedPoint : packedPoints)
		{
			if (isInWilderness(packedPoint))
			{
				return true;
			}
		}
		return false;
	}

	public static boolean isInLevel20Wilderness(int packedPoint)
	{
		return WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_ABOVE_GROUND_LEVEL_20) == 0
			|| WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_UNDERGROUND_LEVEL_20) == 0;
	}

	public static boolean isInLevel30Wilderness(int packedPoint)
	{
		return WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_ABOVE_GROUND_LEVEL_30) == 0
			|| WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_UNDERGROUND_LEVEL_30) == 0;
	}
}

package com.travelguide.transport;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import com.travelguide.ItemVariations;
import com.travelguide.pathfinder.PathStep;
import com.travelguide.pathfinder.PathfinderConfig;
import com.travelguide.pathfinder.TransportAvailability;
import com.travelguide.transport.requirement.ItemRequirement;

/**
 * Determines what items need to be picked up from the bank for a given path.
 * This handles transport-specific requirements like the Dramen staff for fairy rings.
 * Multiple transports that connect the same edge are treated as alternatives (OR):
 * if the player can satisfy any one of them, no pickup is needed; otherwise the
 * cheapest single alternative that can be filled from the bank is chosen.
 */
@SuppressWarnings("unused") // Only static methods are used, incorrectly flagged
public final class BankPickupRequirements
{

	/**
	 * Gets a list of items that need to be picked up from the bank at a given path step.
	 *
	 * @param client           The game client
	 * @param bank             The bank ItemContainer
	 * @param pathfinderConfig The pathfinder config for bank-aware transport lookups
	 * @param bankLocations    Set of bank location coordinates
	 * @param path             The current path
	 * @param pathIndex        The current step index in the path
	 * @return List of item names to pick up, or empty list if none needed
	 */
	public static List<String> getRequiredBankItems(
		Client client,
		ItemContainer bank,
		PathfinderConfig pathfinderConfig,
		Set<Integer> bankLocations,
		List<PathStep> path,
		int pathIndex)
	{

		List<String> requiredItems = new ArrayList<>();

		if (bank == null || path == null || pathIndex < 0 || pathIndex >= path.size())
		{
			return requiredItems;
		}

		// Check if this is a bank step
		int currentPoint = path.get(pathIndex).getPackedPosition();
		if (!bankLocations.contains(currentPoint))
		{
			return requiredItems;
		}

		// Snapshot bank contents.
		Map<Integer, Integer> bankHas = new HashMap<>();
		for (Item bankItem : bank.getItems())
		{
			if (bankItem.getId() >= 0 && bankItem.getQuantity() > 0)
			{
				bankHas.merge(bankItem.getId(), bankItem.getQuantity(), Integer::sum);
			}
		}

		// Map runeId → pouchId for any rune pouch sitting in the bank.
		// Used so computeBankPickups can show "pick up rune pouch" instead of individual runes.
		Map<Integer, Integer> bankPouchRunes = buildBankPouchRunes(client, bankHas);

		// Snapshot what the player already has on them (inventory + equipment + rune pouch in hand).
		Map<Integer, Integer> playerHas = collectPlayerItems(client);

		// Each entry is one edge's pickup phrase, e.g. "Air rune (3), Law rune or Varrock teleport".
		// A LinkedHashSet preserves order while deduplicating identical phrases across edges.
		LinkedHashSet<String> phrases = new LinkedHashSet<>();
		boolean usesFairyRing = false;

		// Walk each edge in the remaining path and collect alternative transports per edge.
		for (int i = pathIndex; i < path.size() - 1; i++)
		{
			int stepPoint = path.get(i).getPackedPosition();
			int nextPoint = path.get(i + 1).getPackedPosition();
			boolean banked = path.get(i + 1).isBankVisited();
			TransportAvailability availability = pathfinderConfig.getTransportAvailability(banked);

			List<Transport> edgeAlternatives = new ArrayList<>();
			for (Transport t : availability.getTransportsAt(stepPoint))
			{
				if (t.getDestination() == nextPoint)
				{
					edgeAlternatives.add(t);
				}
			}
			for (Transport t : availability.getUsableTeleports())
			{
				if (t.getDestination() == nextPoint)
				{
					edgeAlternatives.add(t);
				}
			}
			if (edgeAlternatives.isEmpty())
			{
				continue;
			}

			// Fairy rings handled once globally via the staff requirement below.
			List<Transport> nonFairy = new ArrayList<>();
			for (Transport t : edgeAlternatives)
			{
				if (TransportType.FAIRY_RING.equals(t.getType()))
				{
					usesFairyRing = true;
				}
				else
				{
					nonFairy.add(t);
				}
			}
			if (nonFairy.isEmpty())
			{
				continue;
			}

			// If at least one alternative requires no items, nothing to pick up for this edge.
			boolean anyAlternativeIsFree = false;
			for (Transport t : nonFairy)
			{
				if (t.getItemRequirements() == null || t.getItemRequirements().size() == 0)
				{
					anyAlternativeIsFree = true;
					break;
				}
			}
			if (anyAlternativeIsFree)
			{
				continue;
			}

			// If any alternative is fully satisfied by the player already, no pickup needed.
			boolean satisfied = false;
			for (Transport t : nonFairy)
			{
				if (transportSatisfiedBy(t, playerHas))
				{
					satisfied = true;
					break;
				}
			}
			if (satisfied)
			{
				continue;
			}

			// Otherwise, surface every alternative the bank can fully supply, joined, bankPouchRunes by " or ".
			// Deduplicate alternatives that resolve to the exact same set of bank items.
			LinkedHashSet<String> altStrings = new LinkedHashSet<>();
			for (Transport t : nonFairy)
			{
				Map<Integer, Long> pickups = computeBankPickups(t, playerHas, bankHas, bankPouchRunes);
				if (pickups == null || pickups.isEmpty())
				{
					continue; // bank can't satisfy this alternative
				}
				altStrings.add(formatPickups(client, pickups));
			}
			if (altStrings.isEmpty())
			{
				continue;
			}
			phrases.add(String.join(" or ", altStrings));
		}

		// Fairy ring staff (Dramen / Lunar) is a single OR requirement across the whole trip.
		// Not needed if the Lumbridge Elite diary is complete.
		if (usesFairyRing && client.getVarbitValue(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE) != 1)
		{
			int[] staffIds = ItemVariations.DRAMEN_STAFF.getIds();
			if (!hasAnyItem(playerHas, staffIds, 1))
			{
				int foundId = findItemIdInBank(bankHas, staffIds, 1);
				if (foundId != -1)
				{
					Map<Integer, Long> single = new LinkedHashMap<>();
					single.put(foundId, 1L);
					phrases.add(formatPickups(client, single));
				}
			}
		}

		requiredItems.addAll(phrases);
		return requiredItems;
	}

	/**
	 * Formats a pickup map (item id → quantity) as a comma-separated, human-readable string.
	 */
	private static String formatPickups(Client client, Map<Integer, Long> pickups)
	{
		List<String> parts = new ArrayList<>(pickups.size());
		for (Map.Entry<Integer, Long> entry : pickups.entrySet())
		{
			int itemId = entry.getKey();
			long qty = entry.getValue();
			String itemName = client.getItemDefinition(itemId).getName();
			if (itemName == null || itemName.isEmpty() || "null".equals(itemName))
			{
				itemName = "Unknown item";
			}
			boolean isCurrency = PathfinderConfig.CURRENCIES.contains(itemId);
			if (isCurrency)
			{
				if (qty > 1)
				{
					itemName += " (" + String.format("%,d", qty) + ")";
				}
			}
			else
			{
				itemName = qty + " " + itemName;
			}
			parts.add(itemName);
		}
		return String.join(", ", parts);
	}

	/**
	 * Returns true if the player has at least {@code requiredQty} of any id in {@code itemIds}
	 * across inventory/equipment/rune-pouch.
	 */
	private static boolean hasAnyItem(Map<Integer, Integer> playerHas, int[] itemIds, int requiredQty)
	{
		if (itemIds == null)
		{
			return false;
		}
		for (int id : itemIds)
		{
			if (playerHas.getOrDefault(id, 0) >= requiredQty)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Returns the item ID from {@code itemIds} present in the bank with at least
	 * {@code requiredQty}, or -1 if none qualifies.
	 */
	private static int findItemIdInBank(Map<Integer, Integer> bankHas, int[] itemIds, int requiredQty)
	{
		if (itemIds == null)
		{
			return -1;
		}
		for (int id : itemIds)
		{
			if (bankHas.getOrDefault(id, 0) >= requiredQty)
			{
				return id;
			}
		}
		return -1;
	}

	/**
	 * Returns true if every requirement of the transport is already met by the player's
	 * inventory/equipment/rune-pouch (taking item-id, staff and offhand variations into account).
	 */
	public static boolean transportSatisfiedBy(Transport transport, Map<Integer, Integer> playerHas)
	{
		if (transport.getItemRequirements() == null)
		{
			return true;
		}
		for (ItemRequirement req : transport.getItemRequirements().getRequirements())
		{
			int qty = req.getQuantity() > 0 ? req.getQuantity() : 1;
			if (hasAnyItem(playerHas, req.getItemIds(), qty)
				|| hasAnyItem(playerHas, req.getStaffIds(), 1)
				|| hasAnyItem(playerHas, req.getOffhandIds(), 1))
			{
				continue;
			}
			return false;
		}
		return true;
	}

	/**
	 * For an unsatisfied transport, returns the items (id → qty) that need to be picked up
	 * from the bank to satisfy it, or null if the bank can't supply them.
	 * When a required rune is only available via a bank rune pouch, the pouch itself is
	 * returned as the pickup item (qty 1, deduped across multiple rune requirements).
	 */
	private static Map<Integer, Long> computeBankPickups(Transport transport,
		Map<Integer, Integer> playerHas,
		Map<Integer, Integer> bankHas,
		Map<Integer, Integer> bankPouchRunes)
	{
		Map<Integer, Long> pickups = new LinkedHashMap<>();
		Set<Integer> addedPouches = new HashSet<>(); // tracks pouch IDs already added to pickups
		if (transport.getItemRequirements() == null)
		{
			return pickups;
		}
		for (ItemRequirement req : transport.getItemRequirements().getRequirements())
		{
			int qty = req.getQuantity() > 0 ? req.getQuantity() : 1;
			// Already satisfied by player?
			if (hasAnyItem(playerHas, req.getItemIds(), qty)
				|| hasAnyItem(playerHas, req.getStaffIds(), 1)
				|| hasAnyItem(playerHas, req.getOffhandIds(), 1))
			{
				continue;
			}
			// Prefer bank rune pouch over individual runes. This avoids surfacing combination
			// rune variants (mist, dust, etc.) when the pouch already covers the requirement.
			boolean satisfied = false;
			if (req.getItemIds() != null)
			{
				for (int itemId : req.getItemIds())
				{
					Integer pouchId = bankPouchRunes.get(itemId);
					if (pouchId != null)
					{
						if (!addedPouches.contains(pouchId))
						{
							addedPouches.add(pouchId);
							pickups.put(pouchId, 1L);
						}
						satisfied = true;
						break;
					}
				}
			}
			if (satisfied)
			{
				continue;
			}
			// Try to satisfy from bank directly. Use the canonical (first) item ID for display
			// so we show "Air rune" rather than a combination rune variant like "Mist rune".
			int foundId = findItemIdInBank(bankHas, req.getItemIds(), qty);
			if (foundId != -1)
			{
				pickups.merge(req.getItemIds()[0], (long) qty, Long::sum);
				continue;
			}
			foundId = findItemIdInBank(bankHas, req.getStaffIds(), 1);
			if (foundId == -1)
			{
				foundId = findItemIdInBank(bankHas, req.getOffhandIds(), 1);
			}
			if (foundId == -1)
			{
				return null; // bank can't satisfy this requirement
			}
			pickups.merge(foundId, 1L, Long::sum);
		}
		return pickups;
	}

	/**
	 * Builds a map of runeId → pouchId for every rune stored inside any rune pouch in the bank.
	 * The varbits that encode pouch contents are always current regardless of pouch location.
	 */
	private static Map<Integer, Integer> buildBankPouchRunes(Client client, Map<Integer, Integer> bankHas)
	{
		Map<Integer, Integer> bankPouchRunes = new HashMap<>();
		for (Integer pouchId : PathfinderConfig.RUNE_POUCHES)
		{
			if (!bankHas.containsKey(pouchId))
			{
				continue;
			}
			EnumComposition runePouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
			if (runePouchEnum == null)
			{
				break;
			}
			for (int i = 0; i < PathfinderConfig.RUNE_POUCH_RUNE_VARBITS.length; i++)
			{
				int runeEnumId = client.getVarbitValue(PathfinderConfig.RUNE_POUCH_RUNE_VARBITS[i]);
				int runeId = runeEnumId > 0 ? runePouchEnum.getIntValue(runeEnumId) : 0;
				int runeAmount = client.getVarbitValue(PathfinderConfig.RUNE_POUCH_AMOUNT_VARBITS[i]);
				if (runeId > 0 && runeAmount > 0)
				{
					bankPouchRunes.put(runeId, pouchId);
				}
			}
			break; // one pouch per bank
		}
		return bankPouchRunes;
	}

	/**
	 * Snapshots what the player already has on them (inventory + equipment + rune pouch
	 * contents if the pouch is in inventory or equipped).
	 */
	public static Map<Integer, Integer> collectPlayerItems(Client client)
	{
		Map<Integer, Integer> totals = new HashMap<>();

		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory != null)
		{
			for (Item item : inventory.getItems())
			{
				if (item.getId() >= 0 && item.getQuantity() > 0)
				{
					totals.merge(item.getId(), item.getQuantity(), Integer::sum);
				}
			}
		}

		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment != null)
		{
			for (Item item : equipment.getItems())
			{
				if (item.getId() >= 0 && item.getQuantity() > 0)
				{
					totals.merge(item.getId(), item.getQuantity(), Integer::sum);
				}
			}
		}

		// Rune pouch contents — only when the pouch is actually on the player.
		boolean hasPouch = false;
		for (Integer pouchId : PathfinderConfig.RUNE_POUCHES)
		{
			if (totals.containsKey(pouchId))
			{
				hasPouch = true;
				break;
			}
		}
		if (hasPouch)
		{
			EnumComposition runePouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
			if (runePouchEnum != null)
			{
				for (int i = 0; i < PathfinderConfig.RUNE_POUCH_RUNE_VARBITS.length; i++)
				{
					int runeEnumId = client.getVarbitValue(PathfinderConfig.RUNE_POUCH_RUNE_VARBITS[i]);
					int runeId = runeEnumId > 0 ? runePouchEnum.getIntValue(runeEnumId) : 0;
					int runeAmount = client.getVarbitValue(PathfinderConfig.RUNE_POUCH_AMOUNT_VARBITS[i]);
					if (runeId > 0 && runeAmount > 0)
					{
						totals.merge(runeId, runeAmount, Integer::sum);
					}
				}
			}
		}

		return totals;
	}
}

package com.travelguide.transport;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import com.travelguide.transport.parser.VarRequirement;
import com.travelguide.transport.requirement.TransportItems;

/**
 * Load-scoped deduplication pools for transport requirement objects and display strings (issue
 * #491). Identical requirements and labels are extremely common across the permuted transport rows,
 * so a single canonical instance is shared. The interner is local to a {@code loadAllFromResources}
 * call and discarded afterwards, so the pools themselves are never retained.
 */
final class LoadInterner
{
	private final Map<TransportItems, TransportItems> items = new HashMap<>();
	private final Map<VarRequirement, VarRequirement> vars = new HashMap<>();
	private final Map<Set<VarRequirement>, Set<VarRequirement>> varSets = new HashMap<>();
	private final Map<Set<Quest>, Set<Quest>> questSets = new HashMap<>();
	private final Map<String, String> strings = new HashMap<>();

	TransportItems intern(TransportItems value)
	{
		return value == null ? null : items.computeIfAbsent(value, v -> v);
	}

	VarRequirement intern(VarRequirement value)
	{
		return vars.computeIfAbsent(value, v -> v);
	}

	Set<VarRequirement> internVarSet(Set<VarRequirement> value)
	{
		return varSets.computeIfAbsent(value, v -> v);
	}

	Set<Quest> internQuestSet(Set<Quest> value)
	{
		return questSets.computeIfAbsent(value, v -> v);
	}

	String internString(String value)
	{
		return value == null ? null : strings.computeIfAbsent(value, v -> v);
	}
}

package com.travelguide.transport;

import java.util.Collections;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;

import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import com.travelguide.WorldPointUtil;
import com.travelguide.leagues.LeagueRegion;
import com.travelguide.transport.parser.FieldParser;
import com.travelguide.transport.parser.ItemRequirementParser;
import com.travelguide.transport.parser.QuestParser;
import com.travelguide.transport.parser.SkillRequirementParser;
import com.travelguide.transport.parser.TransportRecord;
import com.travelguide.transport.parser.VarRequirement;
import com.travelguide.transport.parser.VarRequirementParser;
import com.travelguide.transport.parser.WorldPointParser;
import com.travelguide.transport.requirement.TransportItems;

/**
 * This class represents a travel point between two WorldPoints.
 */
@Slf4j
public class Transport
{
	public static final int UNDEFINED_ORIGIN = WorldPointUtil.UNDEFINED;
	public static final int UNDEFINED_DESTINATION = WorldPointUtil.UNDEFINED;
	/**
	 * A location placeholder different from null to use for permutation transports
	 */
	public static final int LOCATION_PERMUTATION = WorldPointUtil.packWorldPoint(-1, -1, 1);
	/**
	 * Shared, never-mutated all-zero skill array. Most transports require no skills, so they point
	 * at this singleton instead of each allocating their own {@code int[]} (issue #491).
	 */
	private static final int[] NO_SKILLS = new int[Skill.values().length + 3];
	/**
	 * The skill levels, total level, combat level and quest points required to use
	 * this transport. Defaults to {@link #NO_SKILLS} until real requirements are set.
	 */
	@Getter
	private int[] skillLevels = NO_SKILLS;
	/**
	 * Variable requirements (varbits and varplayers) for the transport to be valid.
	 * All must pass.
	 */
	// Defaults to a shared immutable empty set; only transports that actually declare var
	// requirements pay for a real Set. Most transports declare none, so this avoids ~one
	// HashSet (+ its HashMap) per transport (issue #491).
	@Getter
	private Set<VarRequirement> varRequirements = Collections.emptySet();
	/**
	 * The starting point of this transport
	 */
	@Getter
	private int origin = UNDEFINED_ORIGIN;
	/**
	 * The ending point of this transport
	 */
	@Setter
	@Getter
	private int destination = UNDEFINED_DESTINATION;

	/**
	 * The quests required to use this transport
	 */
	// Shared immutable empty set by default; see varRequirements above.
	@Getter
	private Set<Quest> quests = Collections.emptySet();
	/**
	 * The item requirements to use this transport
	 */
	@Getter
	private TransportItems itemRequirements;
	/**
	 * The type of transport
	 */
	@Getter
	private TransportType type;
	/**
	 * The travel waiting time in number of ticks
	 */
	@Getter
	private int duration;
	/**
	 * Info to display for this transport. For spirit trees, fairy rings,
	 * and others, this is the destination option to pick.
	 */
	@Getter
	private String displayInfo = null;
	/**
	 * If this is an item transport, this tracks if it is consumable (as opposed to
	 * having infinite uses)
	 */
	@Getter
	private boolean isConsumable = false;
	/**
	 * The maximum wilderness level that the transport can be used in
	 */
	@Getter
	private int maxWildernessLevel = -1;
	/**
	 * Object information for this transport
	 */
	@Getter
	private String objectInfo = null;
	/**
	 * Per-transport seasonal-league region override. When set, the league-mode
	 * region gate ({@code PathfinderConfig#isTransportRegionAllowed}) uses
	 * this region for the destination chunk instead of the result of
	 * {@code LeagueRegionChecker#getRegion(destination)}. Used for shortcuts
	 * whose destination tile sits in a chunk that the wiki classifies under
	 * a different region (e.g. Trollheim Wilderness climb — destination chunk
	 * is Wilderness, but the wiki lists the shortcut under Asgarnia).
	 */
	@Getter
	private LeagueRegion regionOverride = null;

	/**
	 * Creates a new transport from an origin-only transport
	 * and a destination-only transport, and merges requirements
	 */
	Transport(Transport origin, Transport destination)
	{
		TransportBuilder builder = new TransportBuilder()
			.origin(origin.origin)
			.destination(destination.destination)
			.type(origin.type)
			.startSkillLevels(origin.skillLevels)
			.startSkillLevels(destination.skillLevels)
			.quests(origin.quests)
			.quests(destination.quests)
			.itemRequirements(TransportItems.merge(origin.itemRequirements, destination.itemRequirements))
			.duration(Math.max(origin.duration, destination.duration))
			.displayInfo(destination.displayInfo)
			.isConsumable(origin.isConsumable || destination.isConsumable)
			.maxWildernessLevel(Math.max(origin.maxWildernessLevel, destination.maxWildernessLevel))
			.objectInfo(origin.objectInfo)
			.varRequirements(origin.varRequirements)
			.varRequirements(destination.varRequirements)
			.regionOverride(destination.regionOverride != null ? destination.regionOverride : origin.regionOverride);

		Transport builtTransport = builder.build();

		this.origin = builtTransport.origin;
		this.destination = builtTransport.destination;
		this.skillLevels = builtTransport.skillLevels;
		this.quests = builtTransport.quests;
		this.itemRequirements = builtTransport.itemRequirements;
		this.type = builtTransport.type;
		this.duration = builtTransport.duration;
		this.displayInfo = builtTransport.displayInfo;
		this.isConsumable = builtTransport.isConsumable;
		this.maxWildernessLevel = builtTransport.maxWildernessLevel;
		this.objectInfo = builtTransport.objectInfo;
		this.varRequirements = builtTransport.varRequirements;
	}

	Transport(TransportRecord record, TransportType transportType)
	{
		TransportBuilder builder = new TransportBuilder();
		builder.type(transportType);

		// Origin/Destination use hasKey because empty string means LOCATION_PERMUTATION
		if (record.hasKey(TransportRecord.Fields.ORIGIN))
		{
			builder.origin(record.getOrigin());
		}
		if (record.hasKey(TransportRecord.Fields.DESTINATION))
		{
			builder.destination(record.getDestination());
		}
		if (record.has(TransportRecord.Fields.SKILLS))
		{
			builder.skillLevels(record.getSkills());
		}
		if (record.has(TransportRecord.Fields.ITEMS))
		{
			builder.itemRequirements(record.getItems());
		}
		if (record.has(TransportRecord.Fields.QUESTS))
		{
			builder.quests(record.getQuests());
		}
		if (record.has(TransportRecord.Fields.DURATION))
		{
			builder.duration(record.getDuration());
		}
		if (record.has(TransportRecord.Fields.DISPLAY_INFO))
		{
			builder.displayInfo(record.getDisplayInfo());
		}
		if (record.has(TransportRecord.Fields.CONSUMABLE))
		{
			builder.isConsumable(record.getConsumable());
		}
		if (record.has(TransportRecord.Fields.WILDERNESS_LEVEL))
		{
			builder.maxWildernessLevel(record.getWildernessLevel());
		}
		if (record.has(TransportRecord.Fields.OBJECT_INFO))
		{
			builder.objectInfo(record.getObjectInfo());
		}
		if (record.has(TransportRecord.Fields.VARBITS))
		{
			builder.varbits(record.getVarbits());
		}
		if (record.has(TransportRecord.Fields.VAR_PLAYERS))
		{
			builder.varPlayers(record.getVarPlayers());
		}
		if (record.has(TransportRecord.Fields.REGION_OVERRIDE))
		{
			builder.regionOverride(record.getRegionOverride());
		}

		Transport builtTransport = builder.build();
		this.origin = builtTransport.origin;
		this.destination = builtTransport.destination;
		this.skillLevels = builtTransport.skillLevels;
		this.quests = builtTransport.quests;
		this.itemRequirements = builtTransport.itemRequirements;
		this.type = builtTransport.type;
		this.duration = builtTransport.duration;
		this.displayInfo = builtTransport.displayInfo;
		this.isConsumable = builtTransport.isConsumable;
		this.maxWildernessLevel = builtTransport.maxWildernessLevel;
		this.objectInfo = builtTransport.objectInfo;
		this.varRequirements = builtTransport.varRequirements;
		this.regionOverride = builtTransport.regionOverride;
	}

	private Transport()
	{
	}

	/**
	 * Hands back a shared immutable empty set when the builder accumulated nothing, so empty
	 * requirement sets do not allocate a {@code HashSet}/{@code HashMap} per transport. A non-empty
	 * builder set is handed over directly (the single-use builder is discarded afterwards).
	 */
	private static <T> Set<T> compact(Set<T> set)
	{
		return set.isEmpty() ? Collections.emptySet() : set;
	}

	/**
	 * Quest requirements are keyed on the {@link Quest} enum, so a non-empty set is stored as a
	 * compact {@link EnumSet} (a single bitmask object) rather than a HashSet plus its HashMap and
	 * per-element nodes (issue #491). The empty case keeps the shared immutable empty set.
	 */
	private static Set<Quest> compactQuests(Set<Quest> quests)
	{
		return quests.isEmpty() ? Collections.emptySet() : EnumSet.copyOf(quests);
	}

	/**
	 * Hands back the shared {@link #NO_SKILLS} singleton when no skill requirement is set, so
	 * all-zero skill arrays do not allocate a per-transport {@code int[]}. A non-empty builder array
	 * is handed over directly (the single-use builder is discarded afterwards).
	 */
	private static int[] compactSkills(int[] skills)
	{
		for (int level : skills)
		{
			if (level != 0)
			{
				return skills;
			}
		}
		return NO_SKILLS;
	}

	/**
	 * Load-time flyweight: replaces this transport's requirement objects with shared canonical
	 * instances from the supplied pools, so transports with identical item or var requirements share
	 * one {@code TransportItems}/{@code VarRequirement} instance (and the int[] arrays inside them)
	 * rather than each holding a distinct copy (issue #491). Identical requirements are extremely
	 * common across the permuted transport rows. The pools are local to loading and discarded after.
	 */
	void internRequirements(LoadInterner interner)
	{
		itemRequirements = interner.intern(itemRequirements);
		displayInfo = interner.internString(displayInfo);
		objectInfo = interner.internString(objectInfo);
		if (!varRequirements.isEmpty())
		{
			Set<VarRequirement> interned = new HashSet<>(varRequirements.size() * 2);
			for (VarRequirement requirement : varRequirements)
			{
				interned.add(interner.intern(requirement));
			}
			// Transports with identical var requirements (very common across permutations) share one
			// read-only Set instead of each keeping a copy.
			varRequirements = interner.internVarSet(interned);
		}
		if (!quests.isEmpty())
		{
			quests = interner.internQuestSet(quests);
		}
	}

	@Override
	public String toString()
	{
		return ("(" +
			WorldPointUtil.unpackWorldX(origin) + ", " +
			WorldPointUtil.unpackWorldY(origin) + ", " +
			WorldPointUtil.unpackWorldPlane(origin) + ") to (" +
			WorldPointUtil.unpackWorldX(destination) + ", " +
			WorldPointUtil.unpackWorldY(destination) + ", " +
			WorldPointUtil.unpackWorldPlane(destination) + ")");
	}

	/**
	 * Whether the transport has one or more quest requirements
	 */
	public boolean isQuestLocked()
	{
		return !quests.isEmpty();
	}

	/**
	 * Whether this transport is of the given type.
	 */
	public boolean isType(TransportType type)
	{
		return type.equals(this.type);
	}

	/**
	 * Whether this transport's display info contains the given substring.
	 * Returns false if displayInfo is null.
	 */
	public boolean hasDisplayInfo(String substring)
	{
		return displayInfo != null && displayInfo.contains(substring);
	}

	/**
	 * Whether this transport can be used at the given wilderness level.
	 */
	public boolean isUsableAtWildernessLevel(int wildernessLevel)
	{
		return !type.isTeleport() || wildernessLevel <= maxWildernessLevel;
	}

	/**
	 * Gets varbit requirements (filtered from varRequirements).
	 * For backward compatibility with code that needs separate varbit access.
	 */
	public Set<VarRequirement> getVarbits()
	{
		Set<VarRequirement> varbits = new HashSet<>();
		for (VarRequirement req : varRequirements)
		{
			if (req.isVarbit())
			{
				varbits.add(req);
			}
		}
		return varbits;
	}

	/**
	 * Whether this transport has a varbit requirement with the given ID.
	 */
	public boolean hasVarbit(int varbitId)
	{
		for (VarRequirement req : varRequirements)
		{
			if (req.isVarbit() && req.getId() == varbitId)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Gets varplayer requirements (filtered from varRequirements).
	 * For backward compatibility with code that needs separate varplayer access.
	 */
	public Set<VarRequirement> getVarPlayers()
	{
		Set<VarRequirement> varPlayers = new HashSet<>();
		for (VarRequirement req : varRequirements)
		{
			if (req.isVarPlayer())
			{
				varPlayers.add(req);
			}
		}
		return varPlayers;
	}

	public static class TransportBuilder
	{
		private final int[] skillLevels = new int[Skill.values().length + 3];
		private final Set<VarRequirement> varRequirements = new HashSet<>();
		private final FieldParser<int[]> skillParser = new SkillRequirementParser();
		private final FieldParser<TransportItems> itemParser = new ItemRequirementParser();
		private final FieldParser<Set<Quest>> questParser = new QuestParser();
		private final VarRequirementParser varbitParser = VarRequirementParser.forVarbits();
		private final VarRequirementParser varPlayerParser = VarRequirementParser.forVarPlayers();
		private final FieldParser<Integer> worldPointParser = new WorldPointParser();
		private final Set<Quest> quests = new HashSet<>();
		private int origin = UNDEFINED_ORIGIN;
		private int destination = UNDEFINED_DESTINATION;
		private TransportItems itemRequirements;
		private TransportType type;
		private int duration;
		private String displayInfo = null;
		private boolean isConsumable = false;
		private int maxWildernessLevel = -1;
		private String objectInfo = null;
		private LeagueRegion regionOverride = null;

		public TransportBuilder origin(int origin)
		{
			this.origin = origin;
			return this;
		}

		public TransportBuilder origin(String value)
		{
			this.origin = worldPointParser.parse(value);
			return this;
		}

		public TransportBuilder destination(int destination)
		{
			this.destination = destination;
			return this;
		}

		public TransportBuilder destination(String value)
		{
			this.destination = worldPointParser.parse(value);
			return this;
		}

		public TransportBuilder skillLevels(String value)
		{
			int[] parsedSkills = skillParser.parse(value);
			for (int i = 0; i < skillLevels.length; i++)
			{
				if (parsedSkills[i] > 0)
				{
					skillLevels[i] = parsedSkills[i];
				}
			}
			return this;
		}

		public TransportBuilder startSkillLevels(int[] otherSkillLevels)
		{
			for (int i = 0; i < skillLevels.length; i++)
			{
				this.skillLevels[i] = Math.max(this.skillLevels[i], otherSkillLevels[i]);
			}
			return this;
		}

		public TransportBuilder quests(Set<Quest> quests)
		{
			this.quests.addAll(quests);
			return this;
		}

		public TransportBuilder quests(String value)
		{
			this.quests.addAll(questParser.parse(value));
			return this;
		}

		public TransportBuilder itemRequirements(TransportItems itemRequirements)
		{
			this.itemRequirements = itemRequirements;
			return this;
		}

		public TransportBuilder itemRequirements(String value)
		{
			this.itemRequirements = itemParser.parse(value);
			return this;
		}

		public TransportBuilder type(TransportType type)
		{
			this.type = type;
			return this;
		}

		public TransportBuilder duration(int duration)
		{
			this.duration = Math.max(this.duration, duration);
			return this;
		}

		public TransportBuilder duration(String value)
		{
			if (value != null && !value.isEmpty())
			{
				try
				{
					this.duration = Integer.parseInt(value);
				}
				catch (NumberFormatException e)
				{
					log.error("Invalid tick duration: {}", value);
				}
			}
			return this;
		}

		public TransportBuilder displayInfo(String displayInfo)
		{
			this.displayInfo = displayInfo;
			return this;
		}

		public TransportBuilder isConsumable(boolean isConsumable)
		{
			this.isConsumable |= isConsumable;
			return this;
		}

		public TransportBuilder isConsumable(String value)
		{
			this.isConsumable = "T".equals(value) || "yes".equalsIgnoreCase(value);
			return this;
		}

		public TransportBuilder maxWildernessLevel(int maxWildernessLevel)
		{
			this.maxWildernessLevel = Math.max(this.maxWildernessLevel, maxWildernessLevel);
			return this;
		}

		public TransportBuilder maxWildernessLevel(String value)
		{
			if (value != null && !value.isEmpty())
			{
				try
				{
					this.maxWildernessLevel = Integer.parseInt(value);
				}
				catch (NumberFormatException e)
				{
					log.error("Invalid wilderness level: {}", value);
				}
			}
			return this;
		}

		public TransportBuilder objectInfo(String objectInfo)
		{
			this.objectInfo = objectInfo;
			return this;
		}

		public TransportBuilder regionOverride(LeagueRegion regionOverride)
		{
			if (regionOverride != null)
			{
				this.regionOverride = regionOverride;
			}
			return this;
		}

		public TransportBuilder regionOverride(String value)
		{
			if (value != null && !value.isEmpty())
			{
				try
				{
					this.regionOverride = LeagueRegion.valueOf(value.trim().toUpperCase());
				}
				catch (IllegalArgumentException e)
				{
					log.error("Invalid region override: {}", value);
				}
			}
			return this;
		}

		public TransportBuilder varRequirements(Set<VarRequirement> requirements)
		{
			this.varRequirements.addAll(requirements);
			return this;
		}

		public TransportBuilder varbits(String value)
		{
			this.varRequirements.addAll(varbitParser.parse(value));
			return this;
		}

		public TransportBuilder varPlayers(String value)
		{
			this.varRequirements.addAll(varPlayerParser.parse(value));
			return this;
		}

		public Transport build()
		{
			Transport transport = new Transport();
			transport.origin = this.origin;
			transport.destination = this.destination;
			transport.skillLevels = compactSkills(this.skillLevels);
			transport.quests = compactQuests(this.quests);
			transport.itemRequirements = this.itemRequirements;
			transport.type = this.type;
			transport.duration = this.duration;
			transport.displayInfo = this.displayInfo;
			transport.isConsumable = this.isConsumable;
			transport.maxWildernessLevel = this.maxWildernessLevel;
			transport.objectInfo = this.objectInfo;
			transport.varRequirements = compact(this.varRequirements);
			transport.regionOverride = this.regionOverride;

			// Post-build validation/refinement
			if (transport.type != null && transport.type.isTeleport())
			{
				transport.duration = Math.max(transport.duration, 1);
			}

			if (transport.type != null)
			{
				transport.type = transport.type.refine(transport.skillLevels);
			}

			return transport;
		}
	}
}

package com.travelguide.transport;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

import lombok.extern.slf4j.Slf4j;
import com.travelguide.TravelGuidePlugin;
import com.travelguide.Util;
import com.travelguide.WorldPointUtil;
import com.travelguide.transport.parser.TransportRecord;
import com.travelguide.transport.parser.TsvParser;

@Slf4j
public class TransportLoader
{
	private static final TsvParser tsvParser = new TsvParser();

	private static void addTransports(
		Map<Integer, Set<Transport>> transports, String path, TransportType transportType,
		int radiusThreshold)
	{
		try
		{
			String s = new String(
				Util.readAllBytes(Objects.requireNonNull(TravelGuidePlugin.class.getResourceAsStream(path))),
				StandardCharsets.UTF_8);
			addTransportsFromContents(transports, s, transportType, radiusThreshold);
		}
		catch (IOException e)
		{
			throw new RuntimeException(e);
		}
	}

	public static void addTransportsFromContents(
		Map<Integer, Set<Transport>> transports,
		String contents,
		TransportType transportType,
		int radiusThreshold)
	{
		List<TransportRecord> records = tsvParser.parse(contents);

		Set<Transport> newTransports = new HashSet<>();
		for (TransportRecord record : records)
		{
			Transport transport = new Transport(record, transportType);
			newTransports.add(transport);
		}

		/*
		 * A transport with origin A and destination B is one-way and must
		 * be duplicated as origin B and destination A to become two-way.
		 * Example: key-locked doors
		 *
		 * A transport with origin A and a missing destination is one-way,
		 * but can go from origin A to all destinations with a missing origin.
		 * Example: fairy ring AIQ -> <blank>
		 *
		 * A transport with a missing origin and destination B is one-way,
		 * but can go from all origins with a missing destination to destination B.
		 * Example: fairy ring <blank> -> AIQ
		 *
		 * Identical transports from origin A to destination A are skipped, and
		 * non-identical transports from origin A to destination A can be skipped
		 * by specifying a radius threshold to ignore almost identical coordinates.
		 * Example: fairy ring AIQ -> AIQ
		 */
		Set<Transport> transportOrigins = new HashSet<>();
		Set<Transport> transportDestinations = new HashSet<>();
		for (Transport transport : newTransports)
		{
			int origin = transport.getOrigin();
			int destination = transport.getDestination();
			// Logic to determine ordinary transport vs teleport vs permutation (e.g. fairy
			// ring)
			if ((origin == Transport.UNDEFINED_ORIGIN && destination == Transport.UNDEFINED_DESTINATION)
				|| (origin == Transport.LOCATION_PERMUTATION && destination == Transport.LOCATION_PERMUTATION))
			{
				continue;
			}
			else if (origin != Transport.LOCATION_PERMUTATION && origin != Transport.UNDEFINED_ORIGIN
				&& destination == Transport.LOCATION_PERMUTATION)
			{
				transportOrigins.add(transport);
			}
			else if (origin == Transport.LOCATION_PERMUTATION && destination != Transport.UNDEFINED_DESTINATION)
			{
				transportDestinations.add(transport);
			}
			if (origin != Transport.LOCATION_PERMUTATION
				&& destination != Transport.UNDEFINED_DESTINATION && destination != Transport.LOCATION_PERMUTATION
				&& (origin == Transport.UNDEFINED_ORIGIN || origin != destination))
			{
				transports.computeIfAbsent(origin, k -> new HashSet<>()).add(transport);
			}
		}
		for (Transport origin : transportOrigins)
		{
			for (Transport destination : transportDestinations)
			{
				// The radius threshold prevents transport permutations from including (almost)
				// same origin and destination
				if (WorldPointUtil.distanceBetween2D(origin.getOrigin(), destination.getDestination()) > radiusThreshold)
				{
					Transport combined = new Transport(origin, destination);
					transports
						.computeIfAbsent(origin.getOrigin(), k -> new HashSet<>())
						.add(combined);
				}
			}
		}
	}

	public static HashMap<Integer, Set<Transport>> loadAllFromResources()
	{
		HashMap<Integer, Set<Transport>> transports = new HashMap<>();

		for (TransportType type : TransportType.values())
		{
			if (type.hasResourcePath())
			{
				addTransports(transports, type.getResourcePath(), type,
					type.hasRadiusThreshold() ? type.getRadiusThreshold() : 0);
			}
		}

		internRequirements(transports);

		return transports;
	}

	/**
	 * Deduplicates the requirement objects shared across the loaded transports, so identical
	 * {@code TransportItems}/{@code VarRequirement} requirements point at one shared instance
	 * instead of a per-transport copy (issue #491). The interning pools are local and discarded
	 * once loading finishes.
	 */
	private static void internRequirements(Map<Integer, Set<Transport>> transports)
	{
		LoadInterner interner = new LoadInterner();
		Set<Transport> visited = Collections.newSetFromMap(new IdentityHashMap<>());
		for (Set<Transport> set : transports.values())
		{
			for (Transport transport : set)
			{
				if (visited.add(transport))
				{
					transport.internRequirements(interner);
				}
			}
		}
	}
}

