package com.travelguide.transport;

import java.util.EnumMap;
import java.util.Map;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import com.travelguide.TravelGuideConfig;
import com.travelguide.TravelGuidePlugin;
import com.travelguide.TeleportationItem;

/**
 * Manages the enabled/disabled state and cost thresholds of each TransportType
 * based on config.
 * This centralizes the config reading logic and automatically wires config
 * methods
 * from TransportType to TravelGuideConfig.
 *
 * <p>
 * When adding a new TransportType with config options, you only need to:
 * <ol>
 * <li>Add the config methods to TravelGuideConfig</li>
 * <li>Add the enum entry to TransportType with method references for the
 * enabledGetter and costGetter</li>
 * </ol>
 * This class will automatically pick up the new config getters.
 *
 * <p>
 * <b>Special cases:</b>
 * <ul>
 * <li>{@link TransportType#TELEPORTATION_ITEM} and
 * {@link TransportType#TELEPORTATION_BOX}
 * have no enabledGetter because they are controlled by the
 * {@link TeleportationItem} enum
 * via {@code useTeleportationItems} config. The per-transport filtering is
 * handled
 * in {@code PathfinderConfig.checkTeleportationItemRules()}.</li>
 * <li>{@link TransportType#TRANSPORT} has no enabledGetter because it's the
 * base transport
 * type and is always enabled.</li>
 * </ul>
 */
@Slf4j
public class TransportTypeConfig
{
	private final Map<TransportType, Boolean> enabledStates = new EnumMap<>(TransportType.class);
	private final Map<TransportType, Integer> costThresholds = new EnumMap<>(TransportType.class);
	private final TravelGuideConfig config;
	@Getter
	private TeleportationItem teleportationItemSetting;

	public TransportTypeConfig(TravelGuideConfig config)
	{
		this.config = config;
		refresh();
	}

	/**
	 * Refreshes all transport type enabled states and cost thresholds from config.
	 * Uses the functional getters defined in TransportType to read config values.
	 */
	public void refresh()
	{
		// Cache the teleportation item setting
		teleportationItemSetting = TravelGuidePlugin.override("useTeleportationItems", config.useTeleportationItems());

		for (TransportType type : TransportType.values())
		{
			enabledStates.put(type, getEnabledState(type));
			int cost = getCostThreshold(type);
			costThresholds.put(type, cost);
		}
	}

	/**
	 * Determines the enabled state for a transport type.
	 * Uses the enabledGetter function from TransportType to look up the config
	 * value.
	 *
	 * <p>
	 * Special handling for teleportation item types which are controlled by
	 * the TeleportationItem enum rather than a simple boolean.
	 */
	private boolean getEnabledState(TransportType type)
	{
		// Special handling for teleportation item types
		if (type == TransportType.TELEPORTATION_ITEM || type == TransportType.TELEPORTATION_BOX)
		{
			// These are enabled unless TeleportationItem is NONE
			// The detailed filtering (consumable, inventory, etc.) is done in
			// PathfinderConfig
			return teleportationItemSetting != TeleportationItem.NONE;
		}

		// No enabled getter means always enabled (controlled elsewhere or not
		// configurable)
		if (!type.hasEnabledGetter())
		{
			return true;
		}

		boolean configValue = type.getEnabledGetter().apply(config);
		return TravelGuidePlugin.override(type, configValue);
	}

	/**
	 * Determines the cost threshold for a transport type.
	 * Uses the costGetter function from TransportType to look up the config value.
	 */
	private int getCostThreshold(TransportType type)
	{
		// No cost getter means no additional cost
		if (!type.hasCostGetter())
		{
			return 0;
		}

		int configValue = type.getCostGetter().apply(config);
		return TravelGuidePlugin.override(type, configValue);
	}

	/**
	 * Checks if a transport type is enabled in config.
	 */
	public boolean isEnabled(TransportType type)
	{
		return enabledStates.getOrDefault(type, true);
	}

	/**
	 * Gets the cost threshold for a transport type.
	 */
	public int getCost(TransportType type)
	{
		return costThresholds.getOrDefault(type, 0);
	}

	/**
	 * Sets the enabled state for a transport type.
	 * Used for runtime modifications (e.g., disabling fairy rings without dramen
	 * staff).
	 */
	public void setEnabled(TransportType type, boolean enabled)
	{
		enabledStates.put(type, enabled);
	}

	/**
	 * Disables a transport type unless a condition is met.
	 * If the condition is false, the type is disabled.
	 * If the condition is true, the current enabled state is preserved (not
	 * changed).
	 * Useful for quest/item requirements that can only restrict, not enable.
	 */
	public void disableUnless(TransportType type, boolean condition)
	{
		if (!condition)
		{
			enabledStates.put(type, false);
		}
	}
}

package com.travelguide.transport.parser;

/**
 * Interface for parsing string field values into typed objects.
 * Used by TransportRecord to parse TSV field values.
 *
 * @param <T> The type of object produced by this parser
 */
public interface FieldParser<T>
{
	/**
	 * Parses a string value into the target type.
	 *
	 * @param value The string value to parse, may be null or empty
	 * @return The parsed value
	 */
	T parse(String value);
}

package com.travelguide.transport.parser;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

import lombok.extern.slf4j.Slf4j;
import com.travelguide.ItemVariations;
import com.travelguide.Util;
import com.travelguide.transport.requirement.ItemRequirement;
import com.travelguide.transport.requirement.TransportItems;

/**
 * Parses item requirements from TSV field values.
 *
 * <p>
 * Format: {@code ITEM_NAME=quantity} with AND (&amp;) and OR (|) operators
 * </p>
 * <p>
 * Example: {@code AIR_RUNE=3&FIRE_RUNE=2} (need both)
 * </p>
 * <p>
 * Example: {@code DRAMEN_STAFF=1|LUNAR_STAFF=1} (need either)
 * </p>
 */
@Slf4j
public class ItemRequirementParser implements FieldParser<TransportItems>
{
	private static final String DELIM_STATE = "=";
	private static final String DELIM_AND = "&";
	private static final String DELIM_OR = "|";

	@Override
	public TransportItems parse(String value)
	{
		if (value == null || value.isEmpty())
		{
			return null;
		}

		// Normalize the input
		String normalized = value.replace(" ", "")
			.replace(DELIM_AND + DELIM_AND, DELIM_AND)
			.replace(DELIM_OR + DELIM_OR, DELIM_OR)
			.toUpperCase();

		List<ItemRequirement> requirements = new ArrayList<>();

		try
		{
			// Split by AND to get individual requirements
			String[] andParts = normalized.split(DELIM_AND);

			for (String andPart : andParts)
			{
				ItemRequirement requirement = parseRequirement(andPart);
				requirements.add(requirement);
			}

			return requirements.isEmpty() ? null : new TransportItems(requirements);
		}
		catch (NumberFormatException e)
		{
			log.error("Invalid item or quantity: {}", value);
			return null;
		}
	}

	/**
	 * Parses a single requirement which may have OR alternatives.
	 * Example: "AIR_RUNE=3|DUST_RUNE=3"
	 */
	private ItemRequirement parseRequirement(String part)
	{
		String[] orParts = part.split(Pattern.quote(DELIM_OR));

		List<int[]> itemIdsList = new ArrayList<>();
		List<int[]> stavesList = new ArrayList<>();
		List<int[]> offhandsList = new ArrayList<>();
		int maxQuantity = -1;

		for (String orPart : orParts)
		{
			String[] itemAndQuantity = orPart.split(DELIM_STATE);
			if (itemAndQuantity.length != 2)
			{
				throw new NumberFormatException("Invalid format: " + part);
			}

			String itemName = itemAndQuantity[0];
			int quantity = Integer.parseInt(itemAndQuantity[1]);
			maxQuantity = Math.max(maxQuantity, quantity);

			ItemVariations variation = ItemVariations.fromName(itemName);
			if (variation != null)
			{
				itemIdsList.add(variation.getIds());
				stavesList.add(ItemVariations.staves(variation));
				offhandsList.add(ItemVariations.offhands(variation));
			}
			else
			{
				// Try parsing as raw item ID
				itemIdsList.add(new int[]{Integer.parseInt(itemName)});
				stavesList.add(new int[0]);
				offhandsList.add(new int[0]);
			}
		}

		return new ItemRequirement(
			Util.concatenate(itemIdsList.toArray(new int[0][])),
			Util.concatenate(stavesList.toArray(new int[0][])),
			Util.concatenate(offhandsList.toArray(new int[0][])),
			maxQuantity);
	}
}

package com.travelguide.transport.parser;

import java.util.HashSet;
import java.util.Set;

import net.runelite.api.Quest;

/**
 * Parses quest requirements from TSV field values.
 *
 * <p>
 * Format: Quest names separated by semicolons
 * </p>
 * <p>
 * Example: {@code Dragon Slayer I;Recipe for Disaster}
 * </p>
 */
public class QuestParser implements FieldParser<Set<Quest>>
{
	private static final String DELIM_MULTI = ";";

	@Override
	public Set<Quest> parse(String value)
	{
		Set<Quest> quests = new HashSet<>();
		if (value == null || value.isEmpty())
		{
			return quests;
		}

		String[] questNames = value.split(DELIM_MULTI);
		for (String questName : questNames)
		{
			for (Quest quest : Quest.values())
			{
				if (quest.getName().equals(questName))
				{
					quests.add(quest);
					break;
				}
			}
		}
		return quests;
	}
}

package com.travelguide.transport.parser;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;

/**
 * Parses skill level requirements from TSV field values.
 *
 * <p>
 * Format: {@code level skillName} (space-separated), multiple separated by
 * semicolons
 * </p>
 * <p>
 * Example: {@code 70 Agility;50 Strength}
 * </p>
 * <p>
 * Special skills: "Total level", "Combat level", "Quest points"
 * </p>
 */
@Slf4j
public class SkillRequirementParser implements FieldParser<int[]>
{
	private static final String DELIM_SPACE = " ";
	private static final String DELIM_MULTI = ";";

	@Override
	public int[] parse(String value)
	{
		int[] skillLevels = new int[Skill.values().length + 3];

		if (value == null)
		{
			return skillLevels;
		}

		String[] skillRequirements = value.split(DELIM_MULTI);

		try
		{
			for (String requirement : skillRequirements)
			{
				if (requirement.isEmpty())
				{
					continue;
				}
				String[] levelAndSkill = requirement.split(DELIM_SPACE);
				if (levelAndSkill.length != 2)
				{
					log.error("Invalid level and skill: '{}'", requirement);
					continue;
				}

				int level = Integer.parseInt(levelAndSkill[0]);
				String skillName = levelAndSkill[1] == null ? "" : levelAndSkill[1];

				Skill[] skills = Skill.values();
				int i = 0;
				for (; i < skills.length; i++)
				{
					if (skills[i].getName().equals(skillName))
					{
						skillLevels[i] = level;
					}
				}
				if (skillName.toLowerCase().startsWith("total"))
				{
					skillLevels[i] = level;
				}
				i++;
				if (skillName.toLowerCase().startsWith("combat"))
				{
					skillLevels[i] = level;
				}
				i++;
				if (skillName.toLowerCase().startsWith("quest"))
				{
					skillLevels[i] = level;
				}
			}
		}
		catch (NumberFormatException e)
		{
			log.error("Invalid level and skill: {}", value);
		}

		return skillLevels;
	}
}

