package com.travelguide.transport.parser;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

/**
 * Parses TSV file contents into TransportRecord objects.
 *
 * <p>
 * TSV files should have a header line (optionally starting with #)
 * followed by data lines. Empty lines and lines starting with # are ignored.
 * </p>
 */
public class TsvParser
{
	private static final String DELIM_COLUMN = "\t";
	private static final String PREFIX_COMMENT = "#";

	/**
	 * Parses TSV content into a list of TransportRecords.
	 * The first line must be a header line (optionally starting with #).
	 */
	public List<TransportRecord> parse(String contents)
	{
		List<TransportRecord> records = new ArrayList<>();
		Scanner scanner = new Scanner(contents);

		if (!scanner.hasNextLine())
		{
			scanner.close();
			return records;
		}

		// Parse header line
		String[] headers = parseHeaderLine(scanner.nextLine());

		// Parse data lines
		while (scanner.hasNextLine())
		{
			String line = scanner.nextLine();

			if (line.startsWith(PREFIX_COMMENT) || line.isBlank())
			{
				continue;
			}

			TransportRecord record = parseLine(line, headers);
			records.add(record);
		}

		scanner.close();
		return records;
	}

	/**
	 * Parses the header line, stripping the comment prefix if present.
	 */
	private String[] parseHeaderLine(String headerLine)
	{
		String normalized = headerLine;
		if (normalized.startsWith(PREFIX_COMMENT + " "))
		{
			normalized = normalized.substring(2);
		}
		else if (normalized.startsWith(PREFIX_COMMENT))
		{
			normalized = normalized.substring(1);
		}
		return normalized.split(DELIM_COLUMN);
	}

	/**
	 * Parses a single data line into a TransportRecord.
	 */
	private TransportRecord parseLine(String line, String[] headers)
	{
		// Use -1 limit to preserve trailing empty strings
		String[] fields = line.split(DELIM_COLUMN, -1);
		Map<String, String> fieldMap = new HashMap<>();

		for (int i = 0; i < headers.length; i++)
		{
			if (i < fields.length)
			{
				fieldMap.put(headers[i], fields[i]);
			}
		}

		return new TransportRecord(fieldMap);
	}
}

package com.travelguide.transport.parser;

import lombok.Getter;

/**
 * The type of comparison to perform when checking a variable requirement.
 */
@Getter
public enum VarCheckType
{
	BIT_SET("&"),
	COOLDOWN_MINUTES("@"),
	EQUAL("="),
	GREATER(">"),
	SMALLER("<");

	private final String code;

	VarCheckType(String code)
	{
		this.code = code;
	}
}

package com.travelguide.transport.parser;

import java.util.Map;

import lombok.Getter;

/**
 * Represents a variable-based requirement for a transport.
 * This can be either a varbit or a varplayer requirement.
 *
 * <p>
 * Consolidates the previously separate TransportVarbit and TransportVarPlayer
 * classes which had identical logic.
 * </p>
 */
@Getter
public class VarRequirement
{

	private final VarType varType;
	private final int id;
	private final int value;
	private final VarCheckType checkType;

	public VarRequirement(VarType varType, int id, int value, VarCheckType checkType)
	{
		this.varType = varType;
		this.id = id;
		this.value = value;
		this.checkType = checkType;
	}

	/**
	 * Creates a varbit requirement.
	 */
	public static VarRequirement varbit(int id, int value, VarCheckType checkType)
	{
		return new VarRequirement(VarType.VARBIT, id, value, checkType);
	}

	/**
	 * Creates a varplayer requirement.
	 */
	public static VarRequirement varPlayer(int id, int value, VarCheckType checkType)
	{
		return new VarRequirement(VarType.VARPLAYER, id, value, checkType);
	}

	/**
	 * Checks if this requirement is satisfied given the current variable values.
	 *
	 * @param values A map of variable IDs to their current values
	 * @return true if the requirement is satisfied
	 */
	public boolean check(Map<Integer, Integer> values)
	{
		Integer currentValue = values.get(id);
		if (currentValue == null)
		{
			return false;
		}
		return checkValue(currentValue);
	}

	/**
	 * Same logic as {@link #check(Map)} but with the variable value already resolved (e.g. from the client).
	 */
	public boolean checkValue(int currentValue)
	{
		switch (checkType)
		{
			case EQUAL:
				return currentValue == value;
			case GREATER:
				return currentValue > value;
			case SMALLER:
				return currentValue < value;
			case BIT_SET:
				return (currentValue & value) > 0;
			case COOLDOWN_MINUTES:
				return ((System.currentTimeMillis() / 60000) - currentValue) > value;
			default:
				return false;
		}
	}

	public boolean isVarbit()
	{
		return varType == VarType.VARBIT;
	}

	public boolean isVarPlayer()
	{
		return varType == VarType.VARPLAYER;
	}

	@Override
	public int hashCode()
	{
		int result = varType.hashCode();
		result = 31 * result + id;
		result = 31 * result + value;
		result = 31 * result + checkType.hashCode();
		return result;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (o == null || getClass() != o.getClass())
		{
			return false;
		}
		VarRequirement that = (VarRequirement) o;
		return id == that.id && value == that.value && varType == that.varType && checkType == that.checkType;
	}

	@Override
	public String toString()
	{
		return varType + "[" + id + " " + checkType.getCode() + " " + value + "]";
	}

	/**
	 * The type of variable this requirement checks.
	 */
	public enum VarType
	{
		VARBIT,
		VARPLAYER
	}
}

package com.travelguide.transport.parser;

import java.util.HashSet;
import java.util.Set;
import java.util.regex.Pattern;

import lombok.extern.slf4j.Slf4j;

/**
 * Parses variable requirement strings into VarRequirement objects.
 * Supports both varbit and varplayer requirements.
 *
 * <p>
 * Format: {@code <id><check><value>} where check is one of: = > < & @
 * </p>
 * <p>
 * Multiple requirements are separated by semicolons.
 * </p>
 * <p>
 * Example: {@code 1234=1;5678>10}
 * </p>
 */
@Slf4j
public class VarRequirementParser implements FieldParser<Set<VarRequirement>>
{
	private static final String DELIM_MULTI = ";";

	private final VarRequirement.VarType varType;

	/**
	 * Creates a parser for the specified variable type.
	 */
	public VarRequirementParser(VarRequirement.VarType varType)
	{
		this.varType = varType;
	}

	/**
	 * Creates a parser for varbit requirements.
	 */
	public static VarRequirementParser forVarbits()
	{
		return new VarRequirementParser(VarRequirement.VarType.VARBIT);
	}

	/**
	 * Creates a parser for varplayer requirements.
	 */
	public static VarRequirementParser forVarPlayers()
	{
		return new VarRequirementParser(VarRequirement.VarType.VARPLAYER);
	}

	@Override
	public Set<VarRequirement> parse(String value)
	{
		Set<VarRequirement> result = new HashSet<>();
		if (value == null || value.isEmpty())
		{
			return result;
		}

		try
		{
			for (String requirement : value.split(DELIM_MULTI))
			{
				if (requirement.isEmpty())
				{
					continue;
				}

				VarRequirement parsed = parseRequirement(requirement);
				if (parsed != null)
				{
					result.add(parsed);
				}
			}
		}
		catch (NumberFormatException e)
		{
			log.error("Invalid var requirement: {}", value);
		}
		return result;
	}

	private VarRequirement parseRequirement(String requirement)
	{
		for (VarCheckType checkType : VarCheckType.values())
		{
			String[] parts = requirement.split(Pattern.quote(checkType.getCode()));
			if (parts.length == 2)
			{
				int id = Integer.parseInt(parts[0]);
				int val = Integer.parseInt(parts[1]);
				return new VarRequirement(varType, id, val, checkType);
			}
		}
		log.error("Invalid var requirement: '{}'", requirement);
		return null;
	}
}

package com.travelguide.transport.parser;

import com.travelguide.WorldPointUtil;
import com.travelguide.transport.Transport;

/**
 * Parses world point coordinates from TSV field values.
 *
 * <p>
 * Format: {@code x y plane} (space-separated)
 * </p>
 * <p>
 * Empty values are treated as location permutations (for fairy rings, etc.)
 * </p>
 */
public class WorldPointParser implements FieldParser<Integer>
{
	private static final String DELIM_SPACE = " ";

	@Override
	public Integer parse(String value)
	{
		if (value == null || value.isEmpty())
		{
			return Transport.LOCATION_PERMUTATION;
		}
		String[] parts = value.split(DELIM_SPACE);
		return parts.length == 3 ? WorldPointUtil.packWorldPoint(
			Integer.parseInt(parts[0]),
			Integer.parseInt(parts[1]),
			Integer.parseInt(parts[2])) : Transport.LOCATION_PERMUTATION;
	}
}

package com.travelguide.transport.requirement;

import java.util.Arrays;

import lombok.Getter;

/**
 * Represents an item requirement with its variations and quantity.
 * For example: AIR_RUNE=3 where AIR_RUNE can be substituted by DUST_RUNE,
 * SMOKE_RUNE, etc.
 */
@Getter
public class ItemRequirement
{
	/**
	 * The item IDs that satisfy this requirement (variations)
	 */
	private final int[] itemIds;

	/**
	 * Staff IDs that can substitute runes for this requirement
	 */
	private final int[] staffIds;

	/**
	 * Offhand IDs that can substitute for this requirement
	 */
	private final int[] offhandIds;

	/**
	 * The quantity required
	 */
	private final int quantity;

	public ItemRequirement(int[] itemIds, int[] staffIds, int[] offhandIds, int quantity)
	{
		this.itemIds = itemIds;
		this.staffIds = staffIds;
		this.offhandIds = offhandIds;
		this.quantity = quantity;
	}

	@Override
	public int hashCode()
	{
		int result = Arrays.hashCode(itemIds);
		result = 31 * result + Arrays.hashCode(staffIds);
		result = 31 * result + Arrays.hashCode(offhandIds);
		result = 31 * result + quantity;
		return result;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (o == null || getClass() != o.getClass())
		{
			return false;
		}
		ItemRequirement that = (ItemRequirement) o;
		return quantity == that.quantity &&
			Arrays.equals(itemIds, that.itemIds) &&
			Arrays.equals(staffIds, that.staffIds) &&
			Arrays.equals(offhandIds, that.offhandIds);
	}
}

package com.travelguide.transport.requirement;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import lombok.Getter;

/**
 * Represents all item requirements for a transport.
 * All requirements must be satisfied.
 */
@Getter
public class TransportItems
{
	private final List<ItemRequirement> requirements;

	public TransportItems(List<ItemRequirement> requirements)
	{
		this.requirements = List.copyOf(requirements);
	}

	/**
	 * Creates TransportItems from legacy array format for backwards compatibility.
	 */
	public TransportItems(int[][] items, int[][] staves, int[][] offhands, int[] quantities)
	{
		List<ItemRequirement> reqs = new ArrayList<>();
		for (int i = 0; i < items.length; i++)
		{
			reqs.add(new ItemRequirement(
				items[i],
				staves != null && i < staves.length ? staves[i] : new int[0],
				offhands != null && i < offhands.length ? offhands[i] : new int[0],
				quantities[i]));
		}
		this.requirements = Collections.unmodifiableList(reqs);
	}

	/**
	 * Merges two TransportItems, combining all requirements from both.
	 * If either is null, returns the other.
	 */
	public static TransportItems merge(TransportItems first, TransportItems second)
	{
		if (first == null)
		{
			return second;
		}
		if (second == null)
		{
			return first;
		}
		List<ItemRequirement> merged = new ArrayList<>();
		merged.addAll(first.requirements);
		merged.addAll(second.requirements);
		return new TransportItems(merged);
	}

	/**
	 * Gets the number of item requirements.
	 */
	public int size()
	{
		return requirements.size();
	}

	// Legacy getters for backwards compatibility
	public int[][] getItems()
	{
		int[][] items = new int[requirements.size()][];
		for (int i = 0; i < requirements.size(); i++)
		{
			items[i] = requirements.get(i).getItemIds();
		}
		return items;
	}

	public int[][] getStaves()
	{
		int[][] staves = new int[requirements.size()][];
		for (int i = 0; i < requirements.size(); i++)
		{
			staves[i] = requirements.get(i).getStaffIds();
		}
		return staves;
	}

	public int[][] getOffhands()
	{
		int[][] offhands = new int[requirements.size()][];
		for (int i = 0; i < requirements.size(); i++)
		{
			offhands[i] = requirements.get(i).getOffhandIds();
		}
		return offhands;
	}

	public int[] getQuantities()
	{
		int[] quantities = new int[requirements.size()];
		for (int i = 0; i < requirements.size(); i++)
		{
			quantities[i] = requirements.get(i).getQuantity();
		}
		return quantities;
	}

	private String toString(int[][] array)
	{
		StringBuilder text = new StringBuilder();
		for (int[] inner : array)
		{
			text.append((text.length() == 0) ? "" : ", ").append(Arrays.toString(inner));
		}
		return "[" + text + "]";
	}

	@Override
	public int hashCode()
	{
		return requirements.hashCode();
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (o == null || getClass() != o.getClass())
		{
			return false;
		}
		TransportItems that = (TransportItems) o;
		if (requirements.size() != that.requirements.size())
		{
			return false;
		}
		for (int i = 0; i < requirements.size(); i++)
		{
			if (!requirements.get(i).equals(that.requirements.get(i)))
			{
				return false;
			}
		}
		return true;
	}

	@Override
	public String toString()
	{
		return "[" +
			toString(getItems()) + ", " +
			toString(getStaves()) + ", " +
			toString(getOffhands()) + ", " +
			Arrays.toString(getQuantities()) + "]";
	}
}

package com.travelguide.ui;

import com.google.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import com.travelguide.TravelGuideConfig;
import com.travelguide.TravelGuidePlugin;
import com.travelguide.guide.GuideSession;
import com.travelguide.guide.RouteStep;

/**
 * On-screen panel with the current instruction and the next few.
 */
public class GuideOverlay extends OverlayPanel
{
	private static final Color CURRENT = new Color(0x7ED957);
	private static final Color UPCOMING = new Color(0xC8C8C8);
	private static final Color MUTED = new Color(0x9A9A9A);

	private final TravelGuidePlugin plugin;
	private final TravelGuideConfig config;

	@Inject
	private GuideOverlay(TravelGuidePlugin plugin, TravelGuideConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setPreferredSize(new Dimension(260, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showGuideOverlay())
		{
			return null;
		}
		GuideSession session = plugin.getGuideSession();
		if (session == null || !session.isActive())
		{
			return null;
		}
		List<RouteStep> steps = session.getSteps();
		int current = session.getCurrentStepIndex();
		RouteStep step = session.getCurrentStep();
		if (step == null)
		{
			return null;
		}

		String label = session.getTargetLabel();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(label == null || label.isBlank() ? "Travel Guide" : "To: " + label)
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left((current + 1) + ". " + step.getTitle())
			.leftColor(CURRENT)
			.build());
		if (step.getDetail() != null && !step.getDetail().isEmpty())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("   " + step.getDetail())
				.leftColor(CURRENT)
				.build());
		}

		int shown = 0;
		for (int i = current + 1; i < steps.size() && shown < config.guideUpcomingSteps(); i++, shown++)
		{
			RouteStep next = steps.get(i);
			panelComponent.getChildren().add(LineComponent.builder()
				.left((i + 1) + ". " + next.summary())
				.leftColor(UPCOMING)
				.build());
		}

		int remainingSteps = session.remainingSteps();
		int seconds = (int) Math.round(session.remainingTicks() * 0.6);
		String eta = seconds >= 60 ? (seconds / 60) + "m " + (seconds % 60) + "s" : seconds + "s";
		panelComponent.getChildren().add(LineComponent.builder()
			.left(remainingSteps + (remainingSteps == 1 ? " step left" : " steps left"))
			.leftColor(MUTED)
			.right("~" + eta)
			.rightColor(MUTED)
			.build());

		return super.render(graphics);
	}
}

package com.travelguide.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.Rectangle;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.Scrollable;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import com.travelguide.TravelGuidePlugin;
import com.travelguide.guide.GuideSession;
import com.travelguide.guide.RouteStep;

/**
 * Side panel: search for a destination, see the compiled steps.
 * <p>
 * Layout: a fixed header (title, search box) on top, then a scroll pane whose content is
 * pinned to the top and always as wide as the viewport, so nothing drifts sideways or
 * floats to the bottom when there is spare space.
 */
public class GuidePanel extends PluginPanel
{
	private static final int MAX_RESULTS = 20;
	/** Pixel width for wrapped HTML text inside rows (panel width minus borders and gutters). */
	private static final int TEXT_WIDTH = PluginPanel.PANEL_WIDTH - 50;

	private final TravelGuidePlugin plugin;
	private final JTextField searchField = new JTextField();
	private final JPanel resultsPanel = new JPanel(new DynamicGridLayout(0, 1, 0, 2));
	private final JLabel routeTitle = new JLabel("No route");
	private final JButton clearButton = new JButton("Clear");
	private final JPanel stepsPanel = new JPanel(new DynamicGridLayout(0, 1, 0, 2));
	private final JLabel bankStatus = new JLabel();

	/** A panel that fills the viewport width and lays its content out from the top. */
	private static class TopAlignedScrollable extends JPanel implements Scrollable
	{
		TopAlignedScrollable()
		{
			super(new BorderLayout());
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return Math.max(16, visibleRect.height - 16);
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	public GuidePanel(TravelGuidePlugin plugin)
	{
		super(false);
		this.plugin = plugin;
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		// ---- fixed header
		JPanel header = new JPanel(new DynamicGridLayout(0, 1, 0, 4));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setBorder(BorderFactory.createEmptyBorder(8, 8, 6, 8));

		JLabel heading = new JLabel("Travel Guide");
		heading.setFont(FontManager.getRunescapeBoldFont());
		heading.setForeground(Color.WHITE);
		header.add(heading);

		JLabel searchLabel = new JLabel("Where to? Place, bank or NPC");
		searchLabel.setFont(FontManager.getRunescapeSmallFont());
		searchLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		header.add(searchLabel);

		searchField.addKeyListener(new KeyAdapter()
		{
			@Override
			public void keyReleased(KeyEvent e)
			{
				refreshResults();
			}
		});
		header.add(searchField);
		add(header, BorderLayout.NORTH);

		// ---- scrolling content, pinned to the top
		JPanel content = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.setBorder(BorderFactory.createEmptyBorder(0, 8, 8, 8));

		resultsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.add(resultsPanel);

		JPanel routeHeader = new JPanel(new BorderLayout(4, 0));
		routeHeader.setBackground(ColorScheme.DARK_GRAY_COLOR);
		routeHeader.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
		routeTitle.setFont(FontManager.getRunescapeBoldFont());
		routeTitle.setForeground(Color.WHITE);
		routeHeader.add(routeTitle, BorderLayout.CENTER);
		clearButton.setMargin(new Insets(1, 6, 1, 6));
		clearButton.setFocusPainted(false);
		clearButton.addActionListener(e -> plugin.clearGuide());
		routeHeader.add(clearButton, BorderLayout.EAST);
		content.add(routeHeader);

		stepsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.add(stepsPanel);

		bankStatus.setFont(FontManager.getRunescapeSmallFont());
		bankStatus.setBorder(BorderFactory.createEmptyBorder(6, 0, 0, 0));
		content.add(bankStatus);

		JLabel credit = new JLabel(html("<span style='color:#808080'>Routing: Shortest Path (BSD-2). "
			+ "NPC data: OSRS Wiki (CC BY-NC-SA 3.0).</span>"));
		credit.setFont(FontManager.getRunescapeSmallFont());
		credit.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));
		content.add(credit);

		TopAlignedScrollable view = new TopAlignedScrollable();
		view.setBackground(ColorScheme.DARK_GRAY_COLOR);
		view.add(content, BorderLayout.NORTH);

		JScrollPane scroll = new JScrollPane(view);
		scroll.setBorder(null);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(scroll, BorderLayout.CENTER);

		refresh();
	}

	private void refreshResults()
	{
		String query = searchField.getText();
		List<TravelGuidePlugin.SearchResult> results = plugin.search(query, MAX_RESULTS);
		resultsPanel.removeAll();
		for (TravelGuidePlugin.SearchResult r : results)
		{
			JButton b = new JButton(html("<b>" + escape(r.getLabel()) + "</b><br>"
				+ "<span style='color:#a0a0a0'>" + escape(r.getSubLabel()) + "</span>"));
			b.setHorizontalAlignment(SwingConstants.LEFT);
			b.setMargin(new Insets(3, 6, 3, 6));
			b.setFocusPainted(false);
			b.setToolTipText(r.getLabel() + " - " + r.getSubLabel());
			b.addActionListener(e -> plugin.guideTo(r.getTargets(), r.getLabel()));
			resultsPanel.add(b);
		}
		if (results.isEmpty() && !query.isBlank())
		{
			JLabel none = new JLabel("No matches");
			none.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			resultsPanel.add(none);
		}
		resultsPanel.revalidate();
		resultsPanel.repaint();
	}

	/** Rebuilds the steps list from the session. Safe to call from any thread. */
	public void refresh()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::refresh);
			return;
		}
		GuideSession session = plugin.getGuideSession();
		String status = plugin.bankStatus();
		String statusColor = status.startsWith("Bank: live") ? "#7ed957" : (status.startsWith("Bank: remembered") ? "#c8c8c8" : "#e0a040");
		bankStatus.setText(html("<span style='color:" + statusColor + "'>" + escape(status) + "</span>"));
		stepsPanel.removeAll();
		if (session == null || !session.isActive())
		{
			routeTitle.setText("No route");
			clearButton.setEnabled(false);
			JLabel hint = new JLabel(html("<span style='color:#a0a0a0'>Search above, or right-click the world map "
				+ "and choose <b>Set Target</b>.</span>"));
			stepsPanel.add(hint);
		}
		else
		{
			String label = session.getTargetLabel();
			routeTitle.setText(label == null || label.isBlank() ? "Route" : "To: " + label);
			clearButton.setEnabled(true);
			List<RouteStep> steps = session.getSteps();
			int current = session.getCurrentStepIndex();
			for (int i = 0; i < steps.size(); i++)
			{
				stepsPanel.add(stepRow(i, steps.get(i), i < current, i == current));
			}
		}
		stepsPanel.revalidate();
		stepsPanel.repaint();
	}

	private JPanel stepRow(int index, RouteStep step, boolean done, boolean current)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(current ? ColorScheme.DARKER_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
		Color bar = current ? ColorScheme.BRAND_ORANGE : (done ? ColorScheme.MEDIUM_GRAY_COLOR : ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, bar),
			BorderFactory.createEmptyBorder(4, 6, 4, 6)));

		String titleColor = current ? "#ffffff" : (done ? "#8c8c8c" : "#c8c8c8");
		String detail = step.getDetail() == null ? ""
			: "<br><span style='color:#a0a0a0'>" + escape(step.getDetail()) + "</span>";
		JLabel text = new JLabel(html("<span style='color:" + titleColor + "'>" + (index + 1) + ". "
			+ escape(step.getTitle()) + "</span>" + detail));
		row.add(text, BorderLayout.CENTER);
		return row;
	}

	/** Wraps HTML in a fixed-width body so long text wraps instead of widening the panel. */
	private static String html(String inner)
	{
		return "<html><body style='width:" + TEXT_WIDTH + "px'>" + inner + "</body></html>";
	}

	private static String escape(String s)
	{
		if (s == null)
		{
			return "";
		}
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.travelguide;

import net.runelite.client.game.AgilityShortcut;
import org.junit.Test;
import com.travelguide.transport.Transport;
import com.travelguide.transport.TransportLoader;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * This test checks every AgilityShortcut enum constant against the list of all transports
 * in the resource files, to ensure that our list is complete.
 * <p>
 * This test should only fail when a new AgilityShortcut enum constant is added
 * without a corresponding entry in the TSV file.
 * <p>
 * There are some known exceptions where an AgilityShortcut cannot be matched to a TSV entry,
 * for example when the Object ID changes as the result of "unlocking" the shortcut via a quest.
 * These exceptions can be added to the {@link #createExcludedIds()} method. Use this sparingly.
 */
public class AgilityShortcutTest
{
	private static final Pattern OBJECT_ID_PATTERN = Pattern.compile("\\d+");

	/**
	 * IDs that are known exceptions and cannot be matched to TSV entries.
	 * These typically represent shortcuts that change based on quest completion or other game state.
	 */
	private static final Set<Integer> EXCLUDED_OBJECT_IDS = createExcludedIds();

	private static Set<Integer> createExcludedIds()
	{
		Set<Integer> excluded = new HashSet<>();

		// These two IDs represent the same shortcut before and after a step in the 'Making Friends with My Arm' quest
		// See: https://oldschool.runescape.wiki/w/Broken_fence_(Weiss)
		excluded.add(46815);
		excluded.add(46817);

		// somehow not found in tsv
		excluded.add(23644);

		// somehow not found in tsv
		excluded.add(11948);

		// Somehow not found in tsv
		excluded.add(23568);
		excluded.add(23569);

		// The rocks in the rock cab cave is not found because the coordinate is one off. but this is where you land
		excluded.add(31697);

		return excluded;
	}

	@Test
	public void everyEnumHasTsvEntry()
	{
		Map<Integer, Set<Transport>> allTransports = TransportLoader.loadAllFromResources();
		TransportData transportData = extractTransportData(allTransports);

		List<String> missingShortcuts = findMissingShortcuts(transportData);

		if (!missingShortcuts.isEmpty())
		{
			String errorMessage = String.join("\n", missingShortcuts);
			System.out.println("WARNING: Missing TSV entries for the following AgilityShortcut enum constants:\n" + errorMessage);
			// Non-breaking: only warn so the build does not fail when new shortcuts are added.
			// This keeps the test suite green while still surfacing the missing entries in stdout.
		}
	}

	/**
	 * Extracts coordinate and object ID data from all transports.
	 */
	private TransportData extractTransportData(Map<Integer, Set<Transport>> allTransports)
	{
		Set<String> coordinates = new HashSet<>();
		Set<Integer> objectIds = new HashSet<>();

		for (Set<Transport> transportSet : allTransports.values())
		{
			for (Transport transport : transportSet)
			{
				addCoordinatesFromTransport(transport, coordinates);
				addObjectIdsFromTransport(transport, objectIds);
			}
		}

		return new TransportData(coordinates, objectIds);
	}

	/**
	 * Adds origin and destination coordinates from a transport to the coordinate set.
	 */
	private void addCoordinatesFromTransport(Transport transport, Set<String> coordinates)
	{
		addCoordinateIfValid(transport.getOrigin(), coordinates);
		addCoordinateIfValid(transport.getDestination(), coordinates);
	}

	/**
	 * Adds a coordinate to the set if it's valid (not undefined or a permutation).
	 */
	private void addCoordinateIfValid(int packedCoordinate, Set<String> coordinates)
	{
		if (packedCoordinate != Transport.UNDEFINED_ORIGIN &&
			packedCoordinate != Transport.UNDEFINED_DESTINATION &&
			packedCoordinate != Transport.LOCATION_PERMUTATION)
		{
			String coordinate = formatCoordinate(packedCoordinate);
			coordinates.add(coordinate);
		}
	}

	/**
	 * Formats a packed coordinate as "x y plane".
	 */
	private String formatCoordinate(int packed)
	{
		int x = WorldPointUtil.unpackWorldX(packed);
		int y = WorldPointUtil.unpackWorldY(packed);
		int plane = WorldPointUtil.unpackWorldPlane(packed);
		return x + " " + y + " " + plane;
	}

	/**
	 * Extracts object IDs from the transport's object info string.
	 */
	private void addObjectIdsFromTransport(Transport transport, Set<Integer> objectIds)
	{
		String objectInfo = transport.getObjectInfo();
		if (objectInfo == null || objectInfo.isEmpty())
		{
			return;
		}

		Matcher matcher = OBJECT_ID_PATTERN.matcher(objectInfo);
		while (matcher.find())
		{
			try
			{
				objectIds.add(Integer.parseInt(matcher.group()));
			}
			catch (NumberFormatException ignored)
			{
				// Skip invalid numbers
			}
		}
	}

	/**
	 * Finds all AgilityShortcut enum constants that don't have matching TSV entries.
	 */
	private List<String> findMissingShortcuts(TransportData transportData)
	{
		List<String> missing = new ArrayList<>();

		for (AgilityShortcut shortcut : AgilityShortcut.values())
		{
			if (!isShortcutMatched(shortcut, transportData))
			{
				missing.add(shortcut.name() + " - " + shortcut.getLevel() + " - " + shortcut.getWorldLocation());
			}
		}

		return missing;
	}

	/**
	 * Checks if an AgilityShortcut matches any entry in the transport data.
	 */
	private boolean isShortcutMatched(AgilityShortcut shortcut, TransportData transportData)
	{
		// Check by world location
		if (isMatchedByLocation(shortcut, transportData.coordinates))
		{
			return true;
		}

		// Check by obstacle IDs
		return isMatchedByObstacleIds(shortcut, transportData.objectIds);
	}

	/**
	 * Checks if the shortcut's world location matches any coordinate in the transport data.
	 */
	private boolean isMatchedByLocation(AgilityShortcut shortcut, Set<String> coordinates)
	{
		if (shortcut.getWorldLocation() == null)
		{
			return false;
		}

		String coordinate = shortcut.getWorldLocation().getX() + " "
							+ shortcut.getWorldLocation().getY() + " "
							+ shortcut.getWorldLocation().getPlane();

		return coordinates.contains(coordinate);
	}

	/**
	 * Checks if any of the shortcut's obstacle IDs match object IDs in the transport data.
	 * Returns true if any non-excluded ID matches, or if all IDs are excluded.
	 */
	private boolean isMatchedByObstacleIds(AgilityShortcut shortcut, Set<Integer> objectIds)
	{
		if (shortcut.getObstacleIds() == null)
		{
			return false;
		}

		boolean hasExcludedId = false;
		for (int obstacleId : shortcut.getObstacleIds())
		{
			if (EXCLUDED_OBJECT_IDS.contains(obstacleId))
			{
				System.out.println("Skipping excluded ID " + obstacleId + " for " + shortcut.name());
				hasExcludedId = true;
				continue;
			}

			if (objectIds.contains(obstacleId))
			{
				return true;
			}
		}

		// If all IDs were excluded, consider it matched to avoid false failures
		return hasExcludedId;
	}

	/**
	 * Holds coordinate and object ID data extracted from transports.
	 */
	private static class TransportData
	{
		final Set<String> coordinates;
		final Set<Integer> objectIds;

		TransportData(Set<String> coordinates, Set<Integer> objectIds)
		{
			this.coordinates = coordinates;
			this.objectIds = objectIds;
		}
	}
}

package com.travelguide;

import net.runelite.api.Quest;
import net.runelite.api.Skill;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import com.travelguide.transport.Transport;
import com.travelguide.transport.TransportLoader;
import com.travelguide.transport.TransportType;
import com.travelguide.transport.requirement.TransportItems;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/**
 * Unit tests for the Observatory Grapple Shortcut transport.
 * Tests the transport at coordinates 2449 3155 0 to 2444 3165 0 with requirements:
 * - 23 Agility
 * - CROSSBOW=1
 * - MITH_GRAPPLE=1
 * - Observatory Quest
 */
public class ObservatoryGrappleShortcutTest
{

	private Map<Integer, Set<Transport>> transports;
	private static final String TRANSPORT_DATA =
		"# Origin\tDestination\tmenuOption menuTarget objectID\tSkills\tItems\tVarbits\tVarPlayers\tDuration\tQuests\n" +
		"2449 3155 0\t2444 3165 0\tGrapple Rocks 31850\t23 Agility\tCROSSBOW=1&MITH_GRAPPLE=1\t\t\t\tObservatory Quest\n";

	@Before
	public void setUp()
	{
		transports = new HashMap<>();
		TransportLoader.addTransportsFromContents(transports, TRANSPORT_DATA, TransportType.GRAPPLE_SHORTCUT, 0);
	}

	private Transport getTransport()
	{
		int origin = WorldPointUtil.packWorldPoint(2449, 3155, 0);
		Set<Transport> transportSet = transports.get(origin);
		Assert.assertNotNull("Transport set should exist for origin", transportSet);
		Assert.assertEquals("Should have exactly one transport", 1, transportSet.size());
		return transportSet.iterator().next();
	}

	/**
	 * Scenario 1: Verify that the transport has the correct 23 Agility requirement
	 */
	@Test
	public void testHasAgilityRequirement()
	{
		Transport transport = getTransport();

		int agilityLevel = transport.getSkillLevels()[Skill.AGILITY.ordinal()];
		Assert.assertEquals("Transport should require 23 Agility", 23, agilityLevel);
	}

	/**
	 * Scenario 2: Verify that the transport requires a crossbow item
	 */
	@Test
	public void testHasCrossbowRequirement()
	{
		Transport transport = getTransport();

		TransportItems items = transport.getItemRequirements();
		Assert.assertNotNull("Transport should have item requirements", items);

		int[][] requiredItems = items.getItems();
		int[] quantities = items.getQuantities();

		Assert.assertEquals("Should have two item requirements (CROSSBOW and MITH_GRAPPLE)", 2, requiredItems.length);

		// Find the crossbow requirement
		boolean foundCrossbow = false;
		for (int i = 0; i < requiredItems.length; i++)
		{
			int[] itemGroup = requiredItems[i];
			// Check if this group contains any crossbow variant
			// The CROSSBOW ItemVariation should expand to multiple crossbow types
			if (itemGroup.length > 1)
			{
				// Crossbows have multiple variants
				foundCrossbow = true;
				Assert.assertEquals("Crossbow quantity should be 1", 1, quantities[i]);
				break;
			}
		}

		Assert.assertTrue("Transport should require a crossbow", foundCrossbow);
	}

	/**
	 * Scenario 3: Verify that the transport requires a mithril grapple item
	 */
	@Test
	public void testHasMithrilGrappleRequirement()
	{
		Transport transport = getTransport();

		TransportItems items = transport.getItemRequirements();
		Assert.assertNotNull("Transport should have item requirements", items);

		int[][] requiredItems = items.getItems();
		int[] quantities = items.getQuantities();

		Assert.assertEquals("Should have two item requirements (CROSSBOW and MITH_GRAPPLE)", 2, requiredItems.length);

		// Find the mithril grapple requirement
		boolean foundMithGrapple = false;
		for (int i = 0; i < requiredItems.length; i++)
		{
			int[] itemGroup = requiredItems[i];
			// MITH_GRAPPLE should be a single item (ItemID.XBOWS_GRAPPLE_TIP_BOLT_MITHRIL_ROPE)
			if (itemGroup.length == 1)
			{
				foundMithGrapple = true;
				Assert.assertEquals("Mithril grapple quantity should be 1", 1, quantities[i]);
				break;
			}
		}

		Assert.assertTrue("Transport should require a mithril grapple", foundMithGrapple);
	}

	/**
	 * Scenario 4: Verify that the transport requires Observatory Quest completion
	 */
	@Test
	public void testHasObservatoryQuestRequirement()
	{
		Transport transport = getTransport();

		Set<Quest> quests = transport.getQuests();
		Assert.assertNotNull("Transport should have quest requirements", quests);
		Assert.assertEquals("Should have exactly one quest requirement", 1, quests.size());
		Assert.assertTrue("Should require Observatory Quest", quests.contains(Quest.OBSERVATORY_QUEST));
		Assert.assertTrue("Transport should be quest locked", transport.isQuestLocked());
	}

	/**
	 * Scenario 5: Verify that other skill levels are not required (should be 0)
	 */
	@Test
	public void testNoOtherSkillRequirements()
	{
		Transport transport = getTransport();

		int[] skillLevels = transport.getSkillLevels();

		// Check all skills except Agility should be 0
		for (Skill skill : Skill.values())
		{
			if (skill != Skill.AGILITY)
			{
				int level = skillLevels[skill.ordinal()];
				Assert.assertEquals("Skill " + skill.getName() + " should not be required", 0, level);
			}
		}

		// Check total level, combat level, and quest points (last 3 indices)
		int totalLevelIndex = Skill.values().length;
		Assert.assertEquals("Total level should not be required", 0, skillLevels[totalLevelIndex]);
		Assert.assertEquals("Combat level should not be required", 0, skillLevels[totalLevelIndex + 1]);
		Assert.assertEquals("Quest points should not be required", 0, skillLevels[totalLevelIndex + 2]);
	}

	/**
	 * Scenario 6: Verify the transport has correct origin and destination coordinates
	 */
	@Test
	public void testTransportCoordinates()
	{
		Transport transport = getTransport();

		int expectedOrigin = WorldPointUtil.packWorldPoint(2449, 3155, 0);
		int expectedDestination = WorldPointUtil.packWorldPoint(2444, 3165, 0);

		Assert.assertEquals("Origin should be 2449 3155 0", expectedOrigin, transport.getOrigin());
		Assert.assertEquals("Destination should be 2444 3165 0", expectedDestination, transport.getDestination());

		// Verify unpacked coordinates
		Assert.assertEquals("Origin X should be 2449", 2449, WorldPointUtil.unpackWorldX(transport.getOrigin()));
		Assert.assertEquals("Origin Y should be 3155", 3155, WorldPointUtil.unpackWorldY(transport.getOrigin()));
		Assert.assertEquals("Origin plane should be 0", 0, WorldPointUtil.unpackWorldPlane(transport.getOrigin()));

		Assert.assertEquals("Destination X should be 2444", 2444, WorldPointUtil.unpackWorldX(transport.getDestination()));
		Assert.assertEquals("Destination Y should be 3165", 3165, WorldPointUtil.unpackWorldY(transport.getDestination()));
		Assert.assertEquals("Destination plane should be 0", 0, WorldPointUtil.unpackWorldPlane(transport.getDestination()));
	}

	/**
	 * Bonus Scenario: Verify the transport has correct object information
	 */
	@Test
	public void testObjectInformation()
	{
		Transport transport = getTransport();

		String objectInfo = transport.getObjectInfo();
		Assert.assertNotNull("Transport should have object info", objectInfo);
		Assert.assertEquals("Object info should match", "Grapple Rocks 31850", objectInfo);
	}

	/**
	 * Bonus Scenario: Verify the transport type is GRAPPLE_SHORTCUT
	 */
	@Test
	public void testTransportType()
	{
		Transport transport = getTransport();

		Assert.assertEquals("Transport type should be GRAPPLE_SHORTCUT",
			TransportType.GRAPPLE_SHORTCUT, transport.getType());
	}
}

