/**
 * End to end: real collision map and transports, compiled into steps.
 */
@RunWith(MockitoJUnitRunner.class)
public class RouteCompilerPathfinderTest
{
	@Mock
	Client client;
	@Mock
	ItemContainer inventory;
	@Mock
	ItemContainer equipment;
	@Mock
	ItemContainer bank;
	@Mock
	TravelGuideConfig config;

	private PathfinderConfig pathfinderConfig;
	private PlaceIndex placeIndex;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(30);
		when(config.currencyThreshold()).thenReturn(10000000);
		placeIndex = PlaceIndex.loadFromResources();
	}

	/** Context over the test pathfinder config, mirroring ClientRouteContext without a live client. */
	private RouteCompiler.Context context(Item[] onHand, Item[] banked)
	{
		return new RouteCompiler.Context()
		{
			@Override
			public Set<Transport> transportsForEdge(PathStep from, PathStep to)
			{
				return EdgeTransports.forEdge(pathfinderConfig, from, to);
			}

			@Override
			public boolean usableWithoutBank(Transport transport)
			{
				TransportAvailability availability = pathfinderConfig.getTransportAvailability(false);
				if (transport.getOrigin() == WorldPointUtil.UNDEFINED)
				{
					return Arrays.asList(availability.getUsableTeleports()).contains(transport);
				}
				Transport[] atOrigin = availability.getTransportsPacked()
					.getOrDefault(transport.getOrigin(), TransportAvailability.EMPTY_TRANSPORTS);
				return Arrays.asList(atOrigin).contains(transport);
			}

			@Override
			public int onHandQuantity(int itemId)
			{
				return count(onHand, itemId);
			}

			@Override
			public int bankQuantity(int itemId)
			{
				return count(banked, itemId);
			}

			@Override
			public String itemName(int itemId)
			{
				return "item#" + itemId;
			}

			@Override
			public boolean fairyRingsNeedStaff()
			{
				return true;
			}

			@Override
			public String bankNameAt(int packed)
			{
				return placeIndex.bankNameAt(packed);
			}

			@Override
			public String nearestBankName(int packed, int maxDistance)
			{
				return placeIndex.nearestBankName(packed, maxDistance);
			}
		};
	}

	private static int count(Item[] items, int id)
	{
		int total = 0;
		for (Item item : items)
		{
			if (item.getId() == id)
			{
				total += item.getQuantity();
			}
		}
		return total;
	}

	@Test
	public void castleWarsToAkqBanksForDramenStaffThenUsesFairyRing()
	{
		int castleWars = WorldPointUtil.packWorldPoint(2442, 3083, 0);
		int akqFairyRing = WorldPointUtil.packWorldPoint(2324, 3619, 0);

		when(config.useFairyRings()).thenReturn(true);
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.INVENTORY_AND_BANK);
		when(config.costConsumableTeleportationItems()).thenReturn(50);
		when(client.getVarbitValue(VarbitID.FAIRY2_QUEENCURE_QUEST)).thenReturn(100);
		when(config.includeBankPath()).thenReturn(true);
		when(config.usePoh()).thenReturn(false);

		Item[] onHand = new Item[0];
		Item[] banked = {
			new Item(ItemID.DRAMEN_STAFF, 1),
			new Item(ItemID.ARDY_CAPE_MEDIUM, 1),
			new Item(ItemID.NECKLACE_OF_PASSAGE_5, 1),
		};
		doReturn(inventory).when(client).getItemContainer(InventoryID.INV);
		doReturn(onHand).when(inventory).getItems();
		doReturn(equipment).when(client).getItemContainer(InventoryID.WORN);
		doReturn(onHand).when(equipment).getItems();

		pathfinderConfig = new TestPathfinderConfig(client, config, QuestState.FINISHED, true, true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		doReturn(banked).when(bank).getItems();
		pathfinderConfig.bank = bank;
		pathfinderConfig.refresh();

		Pathfinder pathfinder = new Pathfinder(pathfinderConfig, castleWars, Set.of(akqFairyRing));
		pathfinder.run();
		List<PathStep> path = pathfinder.getPath();
		assertFalse(path.isEmpty());

		List<RouteStep> steps = RouteCompiler.compile(path, context(onHand, banked), "AKQ fairy ring", true);
		for (RouteStep s : steps)
		{
			System.out.println(s.getType() + "  " + s.summary() + "  [" + s.getPathIndexStart() + ".." + s.getPathIndexEnd() + "]");
		}

		int bankIndex = -1;
		int ringIndex = -1;
		for (int i = 0; i < steps.size(); i++)
		{
			RouteStep s = steps.get(i);
			if (s.isBank() && bankIndex < 0)
			{
				bankIndex = i;
			}
			if (s.isTransport() && s.getTransport().getType() == TransportType.FAIRY_RING && ringIndex < 0)
			{
				ringIndex = i;
			}
		}
		assertTrue("route should contain a bank step", bankIndex >= 0);
		assertTrue("route should use a fairy ring", ringIndex >= 0);
		assertTrue("bank comes before the fairy ring", bankIndex < ringIndex);

		RouteStep bankStep = steps.get(bankIndex);
		assertNotNull(bankStep.getItems());
		boolean staffListed = false;
		for (BankItem item : bankStep.getItems())
		{
			if (item.getItemId() == ItemID.DRAMEN_STAFF)
			{
				staffListed = true;
			}
		}
		assertTrue("bank step should list the Dramen staff: " + bankStep.getDetail(), staffListed);
		assertEquals(RouteStepType.ARRIVE, steps.get(steps.size() - 1).getType());
		assertEquals("Arrive at AKQ fairy ring", steps.get(steps.size() - 1).getTitle());

		// Indices are monotonic and cover the whole path.
		int last = -1;
		for (RouteStep s : steps)
		{
			assertTrue(s.getPathIndexStart() >= last);
			last = s.getPathIndexStart();
		}
		assertEquals(path.size() - 1, steps.get(steps.size() - 1).getPathIndexStart());
	}
}

package com.travelguide.guide;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import com.travelguide.WorldPointUtil;
import com.travelguide.pathfinder.PathStep;
import com.travelguide.transport.Transport;
import com.travelguide.transport.TransportType;

public class RouteCompilerTest
{
	/** Test double: transports keyed by "fromPacked->toPacked", plus item state. */
	private static class FakeContext implements RouteCompiler.Context
	{
		final Map<String, Set<Transport>> edges = new HashMap<>();
		final Set<Transport> needsBank = new java.util.HashSet<>();
		final Map<Integer, Integer> onHand = new HashMap<>();
		final Map<Integer, Integer> bank = new HashMap<>();
		final Map<Integer, String> banksAt = new HashMap<>();
		boolean staffNeeded = true;

		void edge(Transport t)
		{
			edges.computeIfAbsent(t.getOrigin() + "->" + t.getDestination(), k -> new java.util.HashSet<>()).add(t);
		}

		void teleport(int from, Transport t)
		{
			edges.computeIfAbsent(from + "->" + t.getDestination(), k -> new java.util.HashSet<>()).add(t);
		}

		@Override
		public Set<Transport> transportsForEdge(PathStep from, PathStep to)
		{
			return edges.getOrDefault(from.getPackedPosition() + "->" + to.getPackedPosition(), Set.of());
		}

		@Override
		public boolean usableWithoutBank(Transport transport)
		{
			return !needsBank.contains(transport);
		}

		@Override
		public int onHandQuantity(int itemId)
		{
			return onHand.getOrDefault(itemId, 0);
		}

		@Override
		public int bankQuantity(int itemId)
		{
			return bank.getOrDefault(itemId, 0);
		}

		@Override
		public String itemName(int itemId)
		{
			return "item#" + itemId;
		}

		@Override
		public boolean fairyRingsNeedStaff()
		{
			return staffNeeded;
		}

		@Override
		public String bankNameAt(int packed)
		{
			return banksAt.get(packed);
		}

		@Override
		public String nearestBankName(int packed, int maxDistance)
		{
			return null;
		}
	}

	private static int p(int x, int y)
	{
		return WorldPointUtil.packWorldPoint(x, y, 0);
	}

	/** A straight line of steps from (x0,y) to (x1,y) inclusive. */
	private static List<PathStep> line(int x0, int x1, int y, boolean banked)
	{
		List<PathStep> steps = new ArrayList<>();
		int dir = x1 >= x0 ? 1 : -1;
		for (int x = x0; x != x1 + dir; x += dir)
		{
			steps.add(new PathStep(p(x, y), banked));
		}
		return steps;
	}

	@Test
	public void walkOnlyPathIsWalkThenArrive()
	{
		List<PathStep> path = line(3200, 3210, 3400, false);
		List<RouteStep> steps = RouteCompiler.compile(path, new FakeContext(), "Lumbridge", true);
		assertEquals(2, steps.size());
		assertEquals(RouteStepType.WALK, steps.get(0).getType());
		assertEquals("Walk to Lumbridge", steps.get(0).getTitle());
		assertEquals(10, steps.get(0).getTiles());
		assertEquals(0, steps.get(0).getPathIndexStart());
		assertEquals(10, steps.get(0).getPathIndexEnd());
		assertEquals(RouteStepType.ARRIVE, steps.get(1).getType());
		assertEquals("Arrive at Lumbridge", steps.get(1).getTitle());
	}

	@Test
	public void transportSplitsWalksAndNamesLandmark()
	{
		FakeContext ctx = new FakeContext();
		Transport ring = new Transport.TransportBuilder()
			.origin(p(3205, 3400)).destination(p(2996, 3114))
			.type(TransportType.FAIRY_RING).objectInfo("Configure Fairy ring 29495").displayInfo("A I Q").duration(5)
			.build();
		ctx.edge(ring);

		List<PathStep> path = new ArrayList<>(line(3200, 3205, 3400, false));
		path.addAll(line(2996, 3000, 3114, false));

		List<RouteStep> steps = RouteCompiler.compile(path, ctx, "the crab", true);
		assertEquals(4, steps.size());
		assertEquals("Walk to the fairy ring", steps.get(0).getTitle());
		assertEquals(5, steps.get(0).getTiles());
		assertEquals(RouteStepType.TRANSPORT, steps.get(1).getType());
		assertEquals("Use fairy ring", steps.get(1).getTitle());
		assertEquals("Dial AIQ", steps.get(1).getDetail());
		assertEquals(5, steps.get(1).getPathIndexStart());
		assertEquals(6, steps.get(1).getPathIndexEnd());
		assertEquals("Walk to the crab", steps.get(2).getTitle());
		assertEquals(6, steps.get(2).getPathIndexStart());
		assertEquals(RouteStepType.ARRIVE, steps.get(3).getType());
	}

	@Test
	public void teleportFromStartHasNoLeadingWalk()
	{
		FakeContext ctx = new FakeContext();
		Transport spell = new Transport.TransportBuilder()
			.destination(p(3213, 3424))
			.type(TransportType.TELEPORTATION_SPELL).displayInfo("Varrock Teleport").duration(4)
			.build();
		ctx.teleport(p(3000, 3000), spell);

		List<PathStep> path = new ArrayList<>();
		path.add(new PathStep(p(3000, 3000), false));
		path.addAll(line(3213, 3215, 3424, false));

		List<RouteStep> steps = RouteCompiler.compile(path, ctx, "Varrock", true);
		assertEquals("Cast Varrock Teleport", steps.get(0).getTitle());
		assertEquals(RouteStepType.TRANSPORT, steps.get(0).getType());
		assertEquals("Walk to Varrock", steps.get(1).getTitle());
	}

	@Test
	public void doorsFoldIntoTheWalk()
	{
		FakeContext ctx = new FakeContext();
		Transport door = new Transport.TransportBuilder()
			.origin(p(3202, 3400)).destination(p(3203, 3400))
			.type(TransportType.TRANSPORT).objectInfo("Open Door 9398").duration(1)
			.build();
		ctx.edge(door);
		List<PathStep> path = line(3200, 3210, 3400, false);
		List<RouteStep> steps = RouteCompiler.compile(path, ctx, "x", true);
		assertEquals(2, steps.size());
		assertEquals(RouteStepType.WALK, steps.get(0).getType());
	}

	@Test
	public void bankStepListsMissingItemsForLaterTransports()
	{
		FakeContext ctx = new FakeContext();
		int bankTile = p(3205, 3400);
		ctx.banksAt.put(bankTile, "Varrock");
		ctx.bank.put(ItemID.DRAMEN_STAFF, 1);
		ctx.bank.put(ItemID.LAWRUNE, 50);
		ctx.bank.put(ItemID.AIRRUNE, 500);
		ctx.bank.put(ItemID.FIRERUNE, 500);
		ctx.onHand.put(ItemID.AIRRUNE, 100); // already carrying air runes

		Transport spell = new Transport.TransportBuilder()
			.destination(p(2600, 3100))
			.type(TransportType.TELEPORTATION_SPELL).displayInfo("Somewhere Teleport").duration(4)
			.itemRequirements("AIR_RUNE=3&&FIRE_RUNE=1&&LAW_RUNE=1")
			.build();
		Transport ring = new Transport.TransportBuilder()
			.origin(p(2603, 3100)).destination(p(2996, 3114))
			.type(TransportType.FAIRY_RING).objectInfo("Configure Fairy ring 29495").displayInfo("A I Q").duration(5)
			.build();
		ctx.needsBank.add(spell);
		ctx.needsBank.add(ring);

		// walk to bank (unbanked), bank flips, teleport, walk to ring, ring, walk, arrive
		List<PathStep> path = new ArrayList<>(line(3200, 3205, 3400, false));
		path.add(new PathStep(p(2600, 3100), true));
		path.addAll(line(2601, 2603, 3100, true));
		path.addAll(line(2996, 2998, 3114, true));
		ctx.teleport(bankTile, spell);
		ctx.edge(ring);

		List<RouteStep> steps = RouteCompiler.compile(path, ctx, "AIQ", true);

		assertEquals("Walk to the bank (Varrock)", steps.get(0).getTitle());
		RouteStep bank = steps.get(1);
		assertEquals(RouteStepType.BANK, bank.getType());
		assertEquals("Bank at Varrock", bank.getTitle());
		assertEquals(5, bank.getPathIndexStart());
		List<Integer> ids = new ArrayList<>();
		for (BankItem item : bank.getItems())
		{
			ids.add(item.getItemId());
		}
		assertTrue("law runes should be withdrawn", ids.contains(ItemID.LAWRUNE));
		assertTrue("fire runes should be withdrawn", ids.contains(ItemID.FIRERUNE));
		assertFalse("air runes are already on hand", ids.contains(ItemID.AIRRUNE));
		assertTrue("dramen staff should be withdrawn for the fairy ring", ids.contains(ItemID.DRAMEN_STAFF));
		assertTrue(bank.getDetail().startsWith("Withdraw "));

		assertEquals("Cast Somewhere Teleport", steps.get(2).getTitle());
		assertEquals("Walk to the fairy ring", steps.get(3).getTitle());
		assertEquals("Use fairy ring", steps.get(4).getTitle());
		assertEquals("Walk to AIQ", steps.get(5).getTitle());
		assertEquals(RouteStepType.ARRIVE, steps.get(6).getType());
	}

	@Test
	public void crossingABankWithNothingToWithdrawIsNotAStep()
	{
		FakeContext ctx = new FakeContext();
		ctx.banksAt.put(p(3205, 3400), "Varrock");
		// Path walks over a bank tile (state flips at index 5) and on to the target; no transports.
		List<PathStep> path = new ArrayList<>(line(3200, 3205, 3400, false));
		path.addAll(line(3206, 3210, 3400, true));
		List<RouteStep> steps = RouteCompiler.compile(path, ctx, "Lumbridge", true);
		assertEquals(2, steps.size());
		assertEquals(RouteStepType.WALK, steps.get(0).getType());
		assertEquals("Walk to Lumbridge", steps.get(0).getTitle());
		assertEquals(10, steps.get(0).getTiles());
		assertEquals(0, steps.get(0).getPathIndexStart());
		assertEquals(10, steps.get(0).getPathIndexEnd());
		assertEquals(RouteStepType.ARRIVE, steps.get(1).getType());
	}

	@Test
	public void unreachableTargetIsLabelled()
	{
		List<RouteStep> steps = RouteCompiler.compile(line(1, 3, 1, false), new FakeContext(), "the moon", false);
		assertEquals("Closest reachable point to the moon", steps.get(1).getTitle());
	}

	@Test
	public void pickTransportPrefersFixedOriginOverTeleport()
	{
		Transport tele = new Transport.TransportBuilder().destination(p(1, 1)).type(TransportType.TELEPORTATION_SPELL).build();
		Transport local = new Transport.TransportBuilder().origin(p(0, 0)).destination(p(1, 1)).type(TransportType.BOAT).build();
		assertEquals(local, RouteCompiler.pickTransport(Set.of(tele, local)));
	}
}

