 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class RouteScenarioDebugTest
{
	@Mock
	Client client;
	@Mock
	ItemContainer inventory;
	@Mock
	ItemContainer equipment;
	@Mock
	ItemContainer bank;

	/** Real interface defaults (a fresh install) with a few switches to flip per scenario. */
	private static class DefaultsConfig implements TravelGuideConfig
	{
		boolean minigames = true;
		boolean quetzals = true;
		boolean fairyRings = true;

		@Override
		public boolean useTeleportationMinigames()
		{
			return minigames;
		}

		@Override
		public boolean useQuetzals()
		{
			return quetzals;
		}

		@Override
		public boolean useFairyRings()
		{
			return fairyRings;
		}

		@Override
		public void setBuiltTeleportationBoxes(String content)
		{
		}

		@Override
		public void setBuiltTeleportationPortalsPoh(String content)
		{
		}
	}

	private final DefaultsConfig config = new DefaultsConfig();
	private PathfinderConfig pathfinderConfig;
	private PlaceIndex placeIndex;
	private Item[] onHand;
	private Item[] banked;
	private int magicLevel = 99;

	@Before
	public void before()
	{
		Assume.assumeTrue("set -DrouteDebug=true to run", Boolean.getBoolean("routeDebug"));
		placeIndex = PlaceIndex.loadFromResources();
	}

	private void setup(Item[] inventoryItems, Item[] bankItems)
	{
		onHand = inventoryItems;
		banked = bankItems;
		doReturn(inventory).when(client).getItemContainer(InventoryID.INV);
		doReturn(inventoryItems).when(inventory).getItems();
		doReturn(equipment).when(client).getItemContainer(InventoryID.WORN);
		doReturn(new Item[0]).when(equipment).getItems();
		pathfinderConfig = new TestPathfinderConfig(client, config, QuestState.FINISHED, true, true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		when(client.getBoostedSkillLevel(Skill.MAGIC)).thenReturn(magicLevel);
		when(client.getVarbitValue(VarbitID.FAIRY2_QUEENCURE_QUEST)).thenReturn(100); // fairy rings unlocked
		doReturn(bankItems).when(bank).getItems();
		pathfinderConfig.bank = bank;
		pathfinderConfig.refresh();
	}

	private RouteCompiler.Context context()
	{
		return new RouteCompiler.Context()
		{
			@Override
			public Set<Transport> transportsForEdge(PathStep from, PathStep to)
			{
				return EdgeTransports.forEdge(pathfinderConfig, from, to);
			}

			@Override
			public boolean usableWithoutBank(Transport transport)
			{
				TransportAvailability availability = pathfinderConfig.getTransportAvailability(false);
				if (transport.getOrigin() == WorldPointUtil.UNDEFINED)
				{
					return Arrays.asList(availability.getUsableTeleports()).contains(transport);
				}
				return Arrays.asList(availability.getTransportsPacked()
					.getOrDefault(transport.getOrigin(), TransportAvailability.EMPTY_TRANSPORTS)).contains(transport);
			}

			@Override
			public int onHandQuantity(int itemId)
			{
				return count(onHand, itemId);
			}

			@Override
			public int bankQuantity(int itemId)
			{
				return count(banked, itemId);
			}

			@Override
			public String itemName(int itemId)
			{
				return "item#" + itemId;
			}

			@Override
			public boolean fairyRingsNeedStaff()
			{
				return true;
			}

			@Override
			public String bankNameAt(int packed)
			{
				return placeIndex.bankNameAt(packed);
			}

			@Override
			public String nearestBankName(int packed, int maxDistance)
			{
				return placeIndex.nearestBankName(packed, maxDistance);
			}
		};
	}

	private static int count(Item[] items, int id)
	{
		int total = 0;
		for (Item item : items)
		{
			if (item.getId() == id)
			{
				total += item.getQuantity();
			}
		}
		return total;
	}

	private void printRoute(String title, int start, Set<Integer> targets)
	{
		Pathfinder pathfinder = new Pathfinder(pathfinderConfig, start, targets);
		pathfinder.run();
		List<PathStep> path = pathfinder.getPath();
		List<RouteStep> steps = RouteCompiler.compile(path, context(), "target", true);
		int ticks = 0;
		System.out.println("=== " + title + " (path " + path.size() + " tiles) ===");
		for (RouteStep s : steps)
		{
			ticks += s.getTicks();
			System.out.printf("%-10s %-60s ticks=%d%n", s.getType(), s.summary(), s.getTicks());
		}
		System.out.println("estimated total ticks: " + ticks);
	}

	private static Set<Integer> gemstoneCrabs()
	{
		return new HashSet<>(Arrays.asList(
			WorldPointUtil.packWorldPoint(1275, 3160, 0),
			WorldPointUtil.packWorldPoint(1351, 3110, 0),
			WorldPointUtil.packWorldPoint(1237, 3042, 0)));
	}

	@Test
	public void grandExchangeToGemstoneCrab()
	{
		int ge = WorldPointUtil.packWorldPoint(3165, 3487, 0);
		Item[] staff = {new Item(ItemID.DRAMEN_STAFF, 1)};
		Item[] fullBank = {
			new Item(ItemID.LAWRUNE, 500), new Item(ItemID.AIRRUNE, 500), new Item(ItemID.FIRERUNE, 500),
			new Item(ItemID.WATERRUNE, 500), new Item(ItemID.EARTHRUNE, 500), new Item(ItemID.SOULRUNE, 500),
			new Item(ItemID.COINS, 100000),
		};

		setup(staff, fullBank);
		printRoute("GE, staff in inventory, runes in bank, defaults", ge, gemstoneCrabs());

		magicLevel = 53; // no Civitas illa Fortis Teleport (54), Ardougne Teleport (51) still allowed
		setup(staff, fullBank);
		printRoute("GE, staff in inventory, runes in bank, 53 Magic", ge, gemstoneCrabs());
		magicLevel = 99;

		setup(staff, new Item[0]);
		printRoute("GE, staff in inventory, empty bank", ge, gemstoneCrabs());

		config.quetzals = false;
		setup(staff, new Item[0]);
		printRoute("GE, staff in inventory, empty bank, quetzals OFF", ge, gemstoneCrabs());
		config.quetzals = true;

		// Fairy ring only: where does DKR -> Aldarin actually land relative to the crabs?
		int aldarinRing = WorldPointUtil.packWorldPoint(1359, 2941, 0);
		setup(staff, new Item[0]);
		printRoute("GE -> Aldarin fairy ring (AJP)", ge, Set.of(aldarinRing));
		printRoute("Aldarin fairy ring -> crabs on foot", aldarinRing, gemstoneCrabs());
	}

	@Test
	public void varrockToGemstoneCrab()
	{
		int varrock = WorldPointUtil.packWorldPoint(3212, 3424, 0);
		Item[] empty = new Item[0];
		Item[] fullBank = {
			new Item(ItemID.DRAMEN_STAFF, 1),
			new Item(ItemID.LAWRUNE, 500), new Item(ItemID.AIRRUNE, 500), new Item(ItemID.FIRERUNE, 500),
			new Item(ItemID.WATERRUNE, 500), new Item(ItemID.EARTHRUNE, 500), new Item(ItemID.SOULRUNE, 500),
			new Item(ItemID.COINS, 100000),
		};

		setup(empty, fullBank);
		printRoute("defaults, empty inventory, staff + runes in bank", varrock, gemstoneCrabs());

		config.minigames = false;
		setup(empty, fullBank);
		printRoute("minigame teleports OFF", varrock, gemstoneCrabs());

		config.minigames = true;
		setup(new Item[]{new Item(ItemID.DRAMEN_STAFF, 1)}, fullBank);
		printRoute("staff in inventory", varrock, gemstoneCrabs());

		config.minigames = false;
		config.quetzals = false;
		setup(new Item[]{new Item(ItemID.DRAMEN_STAFF, 1)}, fullBank);
		printRoute("staff in inventory, minigames OFF, quetzals OFF", varrock, gemstoneCrabs());

		config.minigames = true;
		config.quetzals = true;
		setup(new Item[]{new Item(ItemID.DRAMEN_STAFF, 1)}, new Item[0]);
		printRoute("staff in inventory, empty bank (no runes anywhere)", varrock, gemstoneCrabs());
	}
}

