public class TransportDescriberTest
{
	@Test
	public void splitsObjectInfoIntoOptionAndTarget()
	{
		assertArrayEquals(new String[]{"Configure", "Fairy ring"}, TransportDescriber.splitObjectInfo("Configure Fairy ring 29495"));
		assertArrayEquals(new String[]{"Talk-to", "Pirate Pete"}, TransportDescriber.splitObjectInfo("Talk-to Pirate Pete 601"));
		assertArrayEquals(new String[]{"Open", "Door"}, TransportDescriber.splitObjectInfo("Open Door 9398"));
		assertArrayEquals(new String[]{"Climb-over", "Stile"}, TransportDescriber.splitObjectInfo("Climb-over Stile"));
