		List<NpcIndex.Npc> results = index.search("co", 10);
		assertEquals("Cook", results.get(0).getName());
		assertEquals(1, index.search("lumbridge", 10).size()); // page title contains
		assertTrue(index.search("", 10).isEmpty());
		assertTrue(index.search("zzz", 10).isEmpty());
