	@Test
	public void bundledDataLoadsAndContainsKnownNpcs()
	{
		NpcIndex index = NpcIndex.loadFromResources(new Gson());
		assertTrue("expected thousands of NPCs, got " + index.size(), index.size() > 3000);
		NpcIndex.Npc hans = index.find("Hans");
